def env_bool(name: str, default: bool = False) -> bool:
    val = os.getenv(name)
    if val is None:
        return default
    return str(val).strip().lower() in ("1", "true", "yes", "on")


def resolve_path(base_root: str, path_value: str, default_name: str) -> str:
    raw = (path_value or default_name or "").strip()
    if not raw:
        raw = default_name
    if os.path.isabs(raw):
        return raw
    return os.path.join(base_root, raw)


def utcnow() -> dt.datetime:
    return dt.datetime.utcnow()


def utcnow_z() -> str:
    return utcnow().isoformat() + "Z"


def allowed_image(filename: str) -> bool:
    if not filename:
        return False
    ext = filename.rsplit(".", 1)[-1].lower() if "." in filename else ""
    return ext in {"png", "jpg", "jpeg", "webp", "gif"}


def sanitize_key(text: str) -> str:
    raw = str(text or "").strip().lower()
    out = []
    prev_underscore = False
    for ch in raw:
        if ch.isalnum():
            out.append(ch)
            prev_underscore = False
        else:
            if not prev_underscore:
                out.append("_")
                prev_underscore = True
    return "".join(out).strip("_")


def slugify(text: str) -> str:
    raw = str(text or "").strip().lower()
    out = []
    prev_dash = False

    for ch in raw:
        if ch.isalnum():
            out.append(ch)
            prev_dash = False
        else:
            if not prev_dash:
                out.append("-")
                prev_dash = True

    slug = "".join(out).strip("-")
    return slug[:80] or "simo-build"


def is_hosted_model_url(url: str) -> bool:
    if not url:
        return False
    lowered = url.strip().lower()
    return (
        (lowered.startswith("http://") or lowered.startswith("https://"))
        and (".glb" in lowered or ".gltf" in lowered)
    )


def is_local_model_url(url: str) -> bool:
    if not url:
        return False
    lowered = url.strip().lower()
    return lowered.startswith("/static/models/") and (".glb" in lowered or ".gltf" in lowered)


def is_any_model_url(url: str) -> bool:
    return is_hosted_model_url(url) or is_local_model_url(url)


def normalize_model_url(url: str) -> str:
    raw = str(url or "").strip().rstrip("),.; ")
    if not raw:
        return ""

    lowered = raw.lower()
    if lowered.startswith("http://") or lowered.startswith("https://"):
        return raw
    if lowered.startswith("/static/models/"):
        return raw
    if lowered.startswith("static/models/"):
        return "/" + raw.lstrip("/")

    if lowered.endswith(".glb") or lowered.endswith(".gltf"):
        filename = os.path.basename(raw.replace("\\", "/"))
        return f"/static/models/{filename}"

    return raw


def prettify_model_name(name: str) -> str:
    raw = str(name or "").strip()
    if not raw:
        return "3D model"
    return raw.replace("_", " ").replace("-", " ").strip().title()


def safe_json_loads(raw: str, fallback):
    try:
        return json.loads(raw)
    except Exception:
        return fallback


def clean_choice_label(label: str, object_name: str = "") -> str:
    text = prettify_model_name(label or "")
    obj = prettify_model_name(object_name or "")

    if not text:
        return obj or "3D Model"

    low = text.lower()
    obj_low = obj.lower()

    if obj and low == obj_low:
        return obj

    if "fallback" in low:
        return f"{obj} Fallback" if obj else "Fallback"

    return text


def parse_labeled_env_choices(value: str, object_name: str):
    raw = str(value or "").strip()
    if not raw:
        return []

    out = []
    parts = [p.strip() for p in raw.split("|") if p.strip()]
    pretty_obj = prettify_model_name(object_name)

    for idx, part in enumerate(parts, start=1):
        label = f"{pretty_obj} Option {idx}"
        url = part

        if "::" in part:
            maybe_label, maybe_url = part.split("::", 1)
            maybe_label = str(maybe_label or "").strip()
            maybe_url = normalize_model_url(maybe_url)
            if maybe_label:
                label = maybe_label
            url = maybe_url

        url = normalize_model_url(url)
        if url and is_any_model_url(url):
            out.append(
                {
                    "label": clean_choice_label(label, object_name),
                    "url": url,
                    "source": "candidate",
                    "verified": False,
                    "tier": "candidate",
                    "style": "default",
                }
            )

    return out


def parse_phase39_multi_env_choices(object_name: str):
    key = sanitize_key(object_name).upper()
    env_name = f"SIMO_3D_MULTI_{key}"
    raw = str(os.getenv(env_name, "") or "").strip()
    if not raw:
        return []

    out = []
    chunks = [c.strip() for c in raw.split(",") if c.strip()]
    pretty_obj = prettify_model_name(object_name)

    for idx, chunk in enumerate(chunks, start=1):
        parts = [str(p or "").strip() for p in chunk.split("|")]

        file_or_url = parts[0] if len(parts) > 0 else ""
        label = parts[1] if len(parts) > 1 and parts[1] else f"{pretty_obj} Option {idx}"
        tier = (parts[2] if len(parts) > 2 and parts[2] else "verified").strip().lower()
        style = (parts[3] if len(parts) > 3 and parts[3] else "default").strip().lower()

        url = normalize_model_url(file_or_url)
        if not url or not is_any_model_url(url):
            continue

        source = tier if tier in {"verified", "candidate", "fallback", "concept"} else "candidate"
        verified = source == "verified"

        out.append(
            {
                "label": clean_choice_label(label, object_name),
                "url": url,
                "source": source,
                "verified": verified,
                "tier": source,
                "style": style,
            }
        )

    return out


def extract_html_document(text: str) -> str:
    raw = str(text or "").strip()
    if not raw:
        return ""

    lowered = raw.lower()
    doctype_index = lowered.find("<!doctype html")
    html_index = lowered.find("<html")

    if doctype_index != -1:
        return raw[doctype_index:].strip()

    if html_index != -1:
        return raw[html_index:].strip()

    return ""



def normalize_website_request_text(user_text: str) -> str:
    # Pull the user's actual website request out of builder wrappers/context.
    raw = str(user_text or "").strip()
    if not raw:
        return ""
    m = re.search(r"\[USER_REQUEST\]\s*([\s\S]+)$", raw, re.I)
    if m:
        raw = m.group(1).strip()
    m = re.search(r"User request:\s*([\s\S]+)$", raw, re.I)
    if m:
        raw = m.group(1).strip()
    m = re.search(r"The user wants(?: a website/app| a website| a page)?(?: for| about| around)?\s*[:\-]?\s*([\s\S]+)$", raw, re.I)
    if m:
        raw = m.group(1).strip()
    raw = re.sub(r"\[VISUAL_ANALYSIS\][\s\S]*?\[BUILDER_INSTRUCTION\]", " ", raw, flags=re.I)
    raw = re.sub(r"\[IMAGE_CONTEXT\][\s\S]*?\[USER_REQUEST\]", " ", raw, flags=re.I)
    return re.sub(r"\s+", " ", raw).strip()


def extract_website_subject(user_text: str) -> str:
    text = normalize_website_request_text(user_text)
    text = re.sub(r"^(please\s+)?(can you\s+|could you\s+|would you\s+|i want\s+|i need\s+)?(show me\s+|build me\s+|build\s+|make me\s+|make\s+|create\s+|design\s+|generate\s+|give me\s+)", "", text, flags=re.I).strip()
    text = re.sub(r"\b(beautiful|premium|modern|professional|ready to publish|publish ready|editable|website|web site|site|landing page|homepage|webpage|page|for me|please)\b", " ", text, flags=re.I)
    text = re.sub(r"\b(for|about|around|of)\b", " ", text, flags=re.I)
    text = re.sub(r"\s+", " ", text).strip(" .,-")
    if not text:
        text = normalize_website_request_text(user_text)
    return text[:80].strip() or "business"


def title_case_brand(value: str) -> str:
    return re.sub(r"\s+", " ", str(value or "").strip()).title()


