# SIMO Website Builder 5.0: prevent browser cache from serving old stacked builder files.
@app.after_request
def simo_web5_no_cache_static_builder(response):
    try:
        path = request.path or ""
        if path.endswith(("/static/simo-website-builder-recovery.js", "/static/script.js", "/")):
            response.headers["Cache-Control"] = "no-store, no-cache, must-revalidate, max-age=0"
            response.headers["Pragma"] = "no-cache"
            response.headers["Expires"] = "0"
    except Exception:
        pass
    return response


