# =========================================================
# SIMO WEBSITE / APP BUILDER V3 — ISOLATED CHAT-STYLE LANE
# Purpose: keep Design Workspace untouched while giving website/app prompts
# one source of truth: generated HTML -> editor -> library -> publish.
# =========================================================
def simo_v3_extract_html(text: str) -> str:
    raw = str(text or "").strip()
    if not raw:
        return ""
    raw = re.sub(r"^```(?:html)?\s*", "", raw, flags=re.I).strip()
    raw = re.sub(r"\s*```$", "", raw, flags=re.I).strip()
    low = raw.lower()
    d = low.find("<!doctype")
    h = low.find("<html")
    start = d if d >= 0 else h
    if start >= 0:
        return raw[start:].strip()
    return raw if "<body" in low or "<section" in low else ""


def simo_v3_title_from_prompt(prompt: str) -> str:
    raw = re.sub(r"\s+", " ", str(prompt or "")).strip()
    raw = re.sub(r"^(show me|build me|build|make me|make|create me|create|design me|design|generate me|generate)\s+", "", raw, flags=re.I).strip()
    raw = re.sub(r"\b(i can edit|for me|please|website|webpage|web page|landing page|app|application|dashboard|site)\b", "", raw, flags=re.I).strip()
    raw = re.sub(r"\s+", " ", raw).strip(" -—:")
    if not raw:
        raw = "Simo Website"
    return raw[:70].title()


def simo_v3_fallback_html(prompt: str, title: str = "") -> str:
    title = title or simo_v3_title_from_prompt(prompt)
    p = str(prompt or "").lower()
    # Small universal fallback only if AI is unavailable. Avoid generic pricing clones.
