def simo_v3_system_prompt(prompt: str, kind: str = "website") -> str:
    return f"""You are Simo's Website/App Builder engine.

The user asked for: {prompt!r}

Return ONE complete, polished, production-style HTML document only.
Start with <!DOCTYPE html>. Do not use markdown. Do not explain.

QUALITY STANDARD:
- The page must look like a beautiful modern AI-generated website mockup, not a generic template.
- It must deeply understand the user's exact subject/business/app idea the way an expert copywriter/designer would.
- Every section, headline, visual block, service card, CTA, proof point, price, offer, and detail must be specific to the prompt.
- Avoid generic phrases like "A Premium [Subject] Experience" or "built around what customers need" unless the prompt explicitly asks for a generic strategy page.
- Do not reuse generic bakery/SaaS/pricing filler unless the prompt actually asks for it.
- For websites: create a finished homepage/landing page.
- For apps/dashboards: create a polished app/dashboard screen in HTML with sidebar/topbar/cards/tables/forms as appropriate.

VISUAL RULES:
- Use premium CSS, strong layout, responsive design, gradients, cards, realistic UI/product visual blocks.
- Use real subject-relevant image areas when possible. Reliable Unsplash Source URLs are allowed, for example https://source.unsplash.com/1600x1000/?guitar,store.
- If using images, pair them with dark overlays so text remains readable.
- Make visual areas feel intentional, cinematic, and specific to the prompt, like the razor benchmark.

EDITOR RULES:
- Add data-simo-section attributes on major sections: hero, nav, services, gallery, pricing, testimonials, contact, footer, dashboard, etc.
- Add data-simo-editable on meaningful editable elements/blocks/images/cards/buttons.
- Keep anchors/forms preview-safe.

OUTPUT:
- Complete HTML only.
"""


def simo_v3_edit_prompt(instruction: str, selected: dict, current_html: str) -> str:
    selected_json = json.dumps(selected or {}, ensure_ascii=False)[:6000]
    current = str(current_html or "")[:120000]
    return f"""You are Simo's selection-aware Website/App Editor.

The user selected part of the current page and asked for an edit.

USER EDIT INSTRUCTION:
{instruction}

SELECTED AREA INFORMATION:
{selected_json}

CURRENT HTML:
{current}

TASK:
- Return ONE complete updated HTML document only.
- Start with <!DOCTYPE html>. No markdown. No explanation.
- Apply the user's instruction primarily to the selected area.
- Preserve the rest of the page unless the instruction requires a broader change.
- Keep the page beautiful, prompt-specific, responsive, and preview-safe.
- Keep/add data-simo-section and data-simo-editable attributes so the editor can continue selecting areas.
- External image URLs are allowed when they are relevant and reliable, especially Unsplash Source URLs. Prefer full-width CSS background images or image cards with fallbacks so the page feels visually rich.
"""


@app.route("/api/simo-website-v3/generate", methods=["POST"])
def api_simo_website_v3_generate():
    try:
        data = request.get_json(silent=True) or {}
        prompt = str(data.get("prompt") or data.get("message") or "").strip()
        kind = str(data.get("kind") or "website").strip() or "website"
        if not prompt:
            return jsonify({"ok": False, "error": "Prompt is required."}), 400
        title = simo_v3_title_from_prompt(prompt)
        client = get_client()
        html = ""
        if client:
            try:
                resp = client.responses.create(
                    model=OPENAI_MODEL,
                    input=[
                        {"role": "system", "content": simo_v3_system_prompt(prompt, kind)},
                        {"role": "user", "content": prompt},
                    ],
                )
                html = simo_v3_extract_html(extract_first_text_from_openai_response(resp))
            except Exception:
                resp = client.chat.completions.create(
                    model=OPENAI_MODEL,
                    messages=[
                        {"role": "system", "content": simo_v3_system_prompt(prompt, kind)},
                        {"role": "user", "content": prompt},
                    ],
                )
                html = simo_v3_extract_html(extract_first_text_from_openai_response(resp))
        if not html:
            html = simo_v3_fallback_html(prompt, title)
        canonical_hash = hashlib.sha256(html.encode("utf-8")).hexdigest()
        session["simo_website_v3_current_html"] = html
        session["simo_website_v3_current_prompt"] = prompt
        session["simo_website_v3_current_hash"] = canonical_hash
        session["simo_website_v3_current_hash"] = canonical_hash
        return jsonify({"ok": True, "title": title, "html": html, "kind": kind})
    except Exception as e:
        return jsonify({"ok": False, "error": f"Website V3 generation failed: {str(e)}"}), 500


@app.route("/api/simo-website-v3/edit", methods=["POST"])
def api_simo_website_v3_edit():
    try:
        data = request.get_json(silent=True) or {}
        instruction = str(data.get("instruction") or data.get("prompt") or "").strip()
        current_html = str(data.get("html") or data.get("current_html") or session.get("simo_website_v3_current_html") or "").strip()
        selected = data.get("selected") if isinstance(data.get("selected"), dict) else {}
        if not instruction:
            return jsonify({"ok": False, "error": "Edit instruction is required."}), 400
        if not current_html:
            return jsonify({"ok": False, "error": "Current HTML is required."}), 400
        client = get_client()
        html = ""
        if client:
            try:
                resp = client.responses.create(
                    model=OPENAI_MODEL,
                    input=[{"role": "system", "content": simo_v3_edit_prompt(instruction, selected, current_html)}],
                )
                html = simo_v3_extract_html(extract_first_text_from_openai_response(resp))
            except Exception:
                resp = client.chat.completions.create(
                    model=OPENAI_MODEL,
                    messages=[{"role": "system", "content": simo_v3_edit_prompt(instruction, selected, current_html)}],
                )
                html = simo_v3_extract_html(extract_first_text_from_openai_response(resp))
        if not html:
            html = current_html
        session["simo_website_v3_current_html"] = html
        return jsonify({"ok": True, "html": html})
    except Exception as e:
        return jsonify({"ok": False, "error": f"Website V3 edit failed: {str(e)}"}), 500



