@app.route("/api/library", methods=["GET"])
def api_get_library():
    email = current_user_email()
    if not email or not is_pro_user():
        return jsonify({"ok": True, "items": [], "scope": "guest_free", "account_owned": False})

    conn = get_db()
    rows = conn.execute(
        "SELECT * FROM saved_builds WHERE lower(trim(user_email)) = ? ORDER BY updated_at DESC",
        (email.strip().lower(),),
    ).fetchall()
    conn.close()

    items = [normalize_saved_build_item(r) for r in rows]
    return jsonify({
        "ok": True,
        "items": items,
        "count": len(items),
        "scope": "pro_account",
        "account_owned": True,
    })


@app.route("/api/library/save", methods=["POST"])
def api_save_build():
    email = current_user_email()
    if not email or not is_pro_user():
        return jsonify({"ok": False, "error": "pro_account_required", "message": "Guest / Free Library is local-only. Upgrade to Pro for account-owned Library sync."}), 403

    data = request.get_json(silent=True) or {}
    if not isinstance(data, dict):
        data = {}

    build_id = str(data.get("id") or secrets.token_hex(8)).strip()
    title = str(data.get("title") or data.get("name") or data.get("projectTitle") or "Untitled Build").strip() or "Untitled Build"

    image_raw = _simo_best_image_from_payload(data)
    image_url = _simo_live_safe_image_url(image_raw, build_id)
    item_payload = _simo_library_payload_for_storage(data, image_url)
    item_payload["id"] = build_id
    item_payload["title"] = title
    item_payload["updatedAt"] = utcnow_z()
    item_payload.setdefault("createdAt", utcnow_z())

    html = str(data.get("html") or item_payload.get("html") or "").strip()
    if image_url and (not html or "<img" not in html.lower()):
        html = """<!doctype html><html><head><meta charset="utf-8"><title>{title}</title></head><body style="margin:0;background:#0b1020;color:#fff;font-family:Arial,sans-serif;"><main style="max-width:960px;margin:0 auto;padding:24px;"><h1>{title}</h1><img src="{image_url}" alt="{title}" style="max-width:100%;border-radius:18px;display:block;"><p>Saved Simo workspace design.</p></main></body></html>""".format(title=title, image_url=image_url)

    is_website_builder = bool(item_payload.get("website_builder")) or str(item_payload.get("type") or "").strip().lower() in {"website", "website_builder", "website_builder_html"} or str(item_payload.get("kind") or "").strip().lower() == "website"
    marker = "[SIMO_WEBSITE_BUILDER_SAVED]" if is_website_builder else "[SIMO_CLEAN_WORKSPACE_SAVED]"
    source_text = marker + "\n" + json.dumps(item_payload, ensure_ascii=False)

    notes = str(data.get("notes") or "").strip()
    tags = safe_text_list(data.get("tags", []))
    if not tags:
        tags = ["website", "builder", "html", "publish"] if is_website_builder else ["visual", "design", "workspace", "prompt-first"]
    pinned = 1 if bool(data.get("pinned", False)) else 0
    archived = 1 if bool(data.get("archived", False)) else 0

    now = dt.datetime.utcnow().isoformat()

    incoming_bytes = len(html.encode("utf-8")) + len(source_text.encode("utf-8"))
    quota_ok, quota = _simo_library_quota(email, build_id, incoming_bytes)
    if not quota_ok:
        return jsonify({
            "ok": False,
            "error": "library_storage_limit_reached",
            "message": "This account has reached its Simo Library storage allowance. Delete older items or move to a larger plan before saving more.",
            "library_quota": quota,
        }), 507

    conn = get_db()
    existing_owner = conn.execute("SELECT user_email FROM saved_builds WHERE id = ?", (build_id,)).fetchone()
    if existing_owner and str(existing_owner["user_email"] or "").strip().lower() != email.strip().lower():
        build_id = secrets.token_hex(16)
        item_payload["id"] = build_id
    conn.execute(
        """
        INSERT INTO saved_builds (
            id, user_email, title, html, source_text, notes, tags_json,
            pinned, archived, created_at, updated_at
        )
        VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
        ON CONFLICT(id) DO UPDATE SET
            title = excluded.title,
            html = excluded.html,
            source_text = excluded.source_text,
            notes = excluded.notes,
            tags_json = excluded.tags_json,
            pinned = excluded.pinned,
            archived = excluded.archived,
            updated_at = excluded.updated_at
        """,
        (
            build_id,
            email,
            title,
            html,
            source_text,
            notes,
            json.dumps(tags),
            pinned,
            archived,
            now,
            now,
        ),
    )
    conn.commit()
    conn.close()

    return jsonify({"ok": True, "id": build_id, "imageUrl": image_url, "item": item_payload})


@app.route("/api/library/delete", methods=["POST"])
def api_delete_build():
    email = current_user_email()
    if not email or not is_pro_user():
        return jsonify({"ok": False, "error": "pro_account_required"}), 403

    data = request.get_json(silent=True) or {}
    build_id = str(data.get("id") or "").strip()
    if not build_id:
        return jsonify({"ok": False, "error": "missing_id"}), 400

    conn = get_db()
    conn.execute(
        "DELETE FROM saved_builds WHERE id = ? AND user_email = ?",
        (build_id, email),
    )
    conn.commit()
    conn.close()

    return jsonify({"ok": True})


@app.route("/api/library/rename", methods=["POST"])
def api_rename_build():
    email = current_user_email()
    if not email or not is_pro_user():
        return jsonify({"ok": False, "error": "pro_account_required"}), 403
    data = request.get_json(silent=True) or {}
    build_id = str(data.get("id") or "").strip()
    title = re.sub(r"\s+", " ", str(data.get("title") or "")).strip()[:160]
    if not build_id:
        return jsonify({"ok": False, "error": "missing_id"}), 400
    if not title:
        return jsonify({"ok": False, "error": "missing_title"}), 400
    conn = get_db()
    row = conn.execute("SELECT source_text FROM saved_builds WHERE id = ? AND user_email = ?", (build_id, email)).fetchone()
    if not row:
        conn.close()
        return jsonify({"ok": False, "error": "not_found"}), 404
    source_text = str(row["source_text"] or "")
    prefix, sep, raw_payload = source_text.partition("\n")
    if sep:
        payload = safe_json_loads(raw_payload, {})
        if isinstance(payload, dict):
            payload.update({"title": title, "name": title, "projectTitle": title, "updatedAt": utcnow_z()})
            source_text = prefix + "\n" + json.dumps(payload, ensure_ascii=False)
    conn.execute("UPDATE saved_builds SET title = ?, source_text = ?, updated_at = ? WHERE id = ? AND user_email = ?", (title, source_text, dt.datetime.utcnow().isoformat(), build_id, email))
    conn.commit(); conn.close()
    return jsonify({"ok": True, "id": build_id, "title": title})


