# =========================================================
# SIMO R10.60Z65 — Website/App Creator Premium Universal Brain
# Backend override layer. Design Workspace untouched.
# =========================================================
def simo_z65_clean_prompt(prompt: str) -> str:
    raw = str(prompt or '').strip()
    raw = re.sub(r'\s+', ' ', raw)
    raw = re.sub(r'^(please\s+)?(can you\s+|could you\s+|would you\s+)?(show me|build me|build|make me|make|create|design|generate|give me)\s+', '', raw, flags=re.I).strip()
    raw = re.sub(r'\b(a|an|the|beautiful|premium|modern|professional|ready to publish|publish ready|editable|website|web site|site|landing page|homepage|webpage|page|for me|please|for|about|around|of)\b', ' ', raw, flags=re.I)
    return re.sub(r'\s+', ' ', raw).strip(' .,-:') or 'business'


def simo_z65_subject_kind(prompt: str) -> str:
    p = str(prompt or '').lower()
    if re.search(r'\b(razor|shaver|shaving|grooming|5\s*blade|five\s*blade|blade cartridge)\b', p): return 'razor'
    if re.search(r'\b(used\s+camera|camera\s+store|camera shop|cameras?|dslr|mirrorless|lenses|photography gear|canon|nikon|sony|fuji|fujifilm)\b', p): return 'camera_store'
    if re.search(r'\b(computer store|used computer|pc shop|laptop|gaming pc|desktop|computer repair|macbook|windows pc)\b', p): return 'computer_store'
    if re.search(r'\b(phone repair|cell phone|used phone|iphone repair|samsung repair|mobile repair|screen repair)\b', p): return 'phone_repair'
    if re.search(r'\b(church|ministry|bible study|sermon|prayer|worship|pastor)\b', p): return 'church'
    if re.search(r'\b(real estate|realtor|homes for sale|property listing|luxury home|open house)\b', p): return 'real_estate'
    if re.search(r'\b(appliance|refrigerator|washer|dryer|dishwasher|stove|range|microwave)\b', p): return 'appliance_store'
    if re.search(r'\b(bakery|bread|pastry|cake|cupcake|donut|croissant|sourdough)\b', p): return 'bakery'
    return 'universal'


