def build_fallback_html(user_text: str) -> str:
    return simo_z65_premium_html(user_text)

def generate_builder_html(user_text: str, client, prior_state: dict = None) -> str:
    prior_state = prior_state or {}
    kind = builder_request_kind(user_text)
    clean_text = strip_mode_and_preset_lines(user_text)
    if kind == 'build':
        return simo_z65_premium_html(clean_text)
