# =========================================================
# SIMO R10.60Z66 — Website/App Creator prompt-leak guard + deterministic build routing
# Fixes Z65 bug where the Website Creator instruction text could become page content.
# =========================================================
def simo_z66_extract_real_user_prompt(raw: str) -> str:
    text = str(raw or '').strip()
    if not text:
        return ''
    patterns = [
        r"\[USER_REQUEST\]\s*([\s\S]+)$",
        r"User request:\s*([\s\S]+)$",
        r"The user asked for:\s*['\"]([^'\"]+)['\"]",
        r"origin_prompt['\"]?\s*[:=]\s*['\"]([^'\"]+)['\"]",
    ]
    for pat in patterns:
        m = re.search(pat, text, flags=re.I)
        if m:
            found = str(m.group(1) or '').strip()
            if found:
                return found.split('\n\n')[0].strip()
    if re.search(r"You are Simo'?s.*Website|Return ONE complete|Do not use generic template|No markdown|single-file html", text, flags=re.I):
        m = re.search(r"for (?:a|an) ([a-z0-9 '&-]+?)(?: website| store website| landing page| web page| site)\b", text, flags=re.I)
        if m:
            return 'make me a website for a ' + m.group(1).strip()
        return 'make me a premium business website'
    return text


def simo_z66_prompt_leaked_html(html: str) -> bool:
    h = str(html or '')
    return bool(re.search(r"You are Simo'?s|Return ONE complete|No markdown|Do not use generic template|single-file html|Create polished.*ready-to-publish", h, flags=re.I))


