_simo_z66_previous_generate_builder_html = generate_builder_html

def generate_builder_html(user_text: str, client, prior_state: dict = None) -> str:
    real_prompt = simo_z66_extract_real_user_prompt(strip_mode_and_preset_lines(user_text))
    kind = builder_request_kind(real_prompt)
    lower = real_prompt.lower()
    explicit_site = is_builder_request(real_prompt) or kind == 'build' or any(x in lower for x in ['website','webpage','web page','landing page','homepage','site'])
    if explicit_site:
        if re.search(r'\b(furniture|sofa|couch|dining|bedroom set|showroom)\b', lower, flags=re.I):
            return simo_z66_furniture_html()
        html = simo_z65_premium_html(real_prompt)
        if simo_z66_prompt_leaked_html(html):
            html = simo_v3_fallback_html(real_prompt, simo_v3_title_from_prompt(real_prompt))
        return html
    return _simo_z66_previous_generate_builder_html(user_text, client, prior_state)


def api_simo_website_v3_generate_z66():
    try:
        data=request.get_json(silent=True) or {}
        prompt=simo_z66_extract_real_user_prompt(str(data.get('prompt') or data.get('message') or '').strip())
        kind=str(data.get('kind') or 'website').strip() or 'website'
        if not prompt: return jsonify({'ok':False,'error':'Prompt is required.'}),400
        title=simo_v3_title_from_prompt(prompt)
        if re.search(r'\b(furniture|sofa|couch|dining|bedroom set|showroom)\b', prompt, flags=re.I):
            html=simo_z66_furniture_html()
        else:
            html=simo_z65_premium_html(prompt, title)
        if simo_z66_prompt_leaked_html(html):
            html=simo_v3_fallback_html(prompt, title)
        session['simo_website_v3_current_html']=html
        session['simo_website_v3_current_prompt']=prompt
        return jsonify({'ok':True,'title':title,'html':html,'kind':kind,'phase':'R10.60Z66'})
    except Exception as e:
        return jsonify({'ok':False,'error':f'Website Z66 generation failed: {str(e)}'}),500
