# =========================================================
# SIMO R10.60Z67 — Website/App Creator deterministic subject reset
# Fixes: new subject prompts must start fresh and use a premium subject page,
# not previous-context generic/universal fallback. Design Workspace untouched.
# =========================================================
def simo_z67_real_prompt(prompt: str) -> str:
    raw = str(prompt or '').strip()
    try:
        raw = simo_z66_extract_real_user_prompt(raw)
    except Exception:
        pass
    try:
        raw = strip_mode_and_preset_lines(raw)
    except Exception:
        pass
    raw = re.sub(r'\s+', ' ', raw).strip()
    # If a wrapper leaks through, grab the final natural request.
    matches = re.findall(r'(?:make|build|create|design|show)\s+me\s+(?:a|an)?\s*(?:beautiful\s+|premium\s+|modern\s+|professional\s+)?(?:website|web site|webpage|landing page|homepage|site)\s+(?:for|about|around)\s+(?:a|an|the)?\s*([^\.\n]+)', raw, flags=re.I)
    if matches:
        return 'make me a website for ' + matches[-1].strip(' .,-:')
    return raw


def simo_z67_kind(prompt: str) -> str:
    p = simo_z67_real_prompt(prompt).lower()
    if re.search(r'\b(used\s+car\s+lot|car\s+lot|auto\s+sales|used\s+cars?|car\s+dealer|dealership|vehicles?|trucks?|suvs?)\b', p):
        return 'used_car_lot'
    if re.search(r'\b(furniture\s+store|furniture|sofa|couch|sectional|dining\s+set|bedroom\s+set|showroom|mattress|chairs?)\b', p):
        return 'furniture_store'
    if re.search(r'\b(used\s+camera|camera\s+store|camera\s+shop|cameras?|dslr|mirrorless|lenses|photography\s+gear|canon|nikon|sony|fuji|fujifilm)\b', p):
        return 'camera_store'
    if re.search(r'\b(razor|shaver|shaving|grooming|5\s*blade|five\s*blade|blade\s+cartridge)\b', p):
        return 'razor'
    if re.search(r'\b(appliance|refrigerator|washer|dryer|dishwasher|stove|range|microwave)\b', p):
        return 'appliance_store'
    if re.search(r'\b(computer\s+store|used\s+computer|pc\s+shop|laptop|gaming\s+pc|desktop|computer\s+repair|macbook|windows\s+pc)\b', p):
        return 'computer_store'
    if re.search(r'\b(phone\s+repair|cell\s+phone\s+repair|used\s+phone|iphone\s+repair|samsung\s+repair|mobile\s+repair|screen\s+repair)\b', p):
        return 'phone_repair'
    if re.search(r'\b(church|ministry|bible\s+study|sermon|prayer|worship|pastor)\b', p):
        return 'church'
    if re.search(r'\b(real\s+estate|realtor|homes\s+for\s+sale|property\s+listing|luxury\s+home|open\s+house)\b', p):
        return 'real_estate'
    if re.search(r'\b(bakery|bread|pastry|cake|cupcake|donut|croissant|sourdough)\b', p):
        return 'bakery'
    return 'universal'


