def simo_z69_visual_svg(kind: str, accent: str, accent2: str) -> str:
    if kind == 'phone':
        return f'<svg viewBox="0 0 900 620"><defs><linearGradient id="g" x1="0" x2="1"><stop stop-color="{accent}"/><stop offset="1" stop-color="{accent2}"/></linearGradient></defs><rect width="900" height="620" rx="42" fill="#050914"/><circle cx="680" cy="150" r="190" fill="url(#g)" opacity=".20"/><rect x="208" y="92" width="214" height="430" rx="42" fill="#111827" stroke="#e5e7eb" stroke-width="10"/><rect x="236" y="138" width="158" height="300" rx="20" fill="url(#g)" opacity=".85"/><circle cx="315" cy="474" r="18" fill="#e5e7eb"/><rect x="480" y="134" width="220" height="350" rx="45" fill="#0b1220" stroke="{accent}" stroke-width="8"/><circle cx="590" cy="190" r="28" fill="#020617" stroke="#e5e7eb" stroke-width="7"/><text x="450" y="572" text-anchor="middle" font-family="Arial" font-size="34" font-weight="900" fill="#fff">Certified phones • repair • trade-in</text></svg>'
    if kind == 'car':
        return f'<svg viewBox="0 0 900 620"><defs><linearGradient id="paint" x1="0" x2="1"><stop stop-color="#e5e7eb"/><stop offset=".5" stop-color="{accent2}"/><stop offset="1" stop-color="#111827"/></linearGradient></defs><rect width="900" height="620" rx="42" fill="#050914"/><path d="M0 455 C180 380 360 425 520 370 C690 312 780 360 900 322 L900 620 L0 620Z" fill="#111827"/><rect x="145" y="330" width="610" height="135" rx="50" fill="url(#paint)"/><path d="M288 320 C330 230 485 215 570 314 Z" fill="#cfe8ff" stroke="#94a3b8" stroke-width="10"/><circle cx="270" cy="476" r="70" fill="#020617"/><circle cx="270" cy="476" r="28" fill="#f8fafc"/><circle cx="650" cy="476" r="70" fill="#020617"/><circle cx="650" cy="476" r="28" fill="#f8fafc"/><rect x="610" y="360" width="95" height="20" rx="10" fill="{accent}"/><text x="450" y="110" text-anchor="middle" font-family="Arial" font-size="48" font-weight="900" fill="#fff">Featured inspected vehicle</text></svg>'
