# =========================================================
# SIMO R10.60Z71 — Universal Website/App Creator planner
# Scope: Website/App Creator only. No Design Workspace changes.
# =========================================================
def simo_z71_clean_prompt(raw: str) -> str:
    text = str(raw or '').strip()
    try:
        text = simo_z70_clean_prompt(text)
    except Exception:
        pass
    # If an internal instruction ever wraps the user prompt, strip back to the real ask.
    m = re.search(r'(?:user\s+wants?|request|prompt)\s*[:\-]\s*["\']?(.{4,220}?)(?:["\']?\s*(?:$|\.|\n))', text, re.I)
    if m and re.search(r'\b(website|web\s*site|webpage|landing\s+page|homepage|app)\b', m.group(1), re.I):
        text = m.group(1)
    text = re.sub(r'\s+', ' ', text).strip()
    return text


def simo_z71_title_words(prompt: str) -> str:
    t = simo_z71_clean_prompt(prompt)
    t = re.sub(r'^(please\s+)?(make|build|create|show|design|generate|give)\s+(me|us)?\s*', '', t, flags=re.I).strip()
    t = re.sub(r'\b(a|an|the|nice|beautiful|premium|modern|professional|for|about|website|web\s*site|webpage|web\s*page|landing\s+page|homepage|site|page|app|business)\b', ' ', t, flags=re.I)
    t = re.sub(r'\s+', ' ', t).strip(' .-')
    return (t[:70] or 'business').title()


def simo_z71_subject_kind(prompt: str) -> str:
    t = simo_z71_clean_prompt(prompt).lower()
    t = t.replace('cell phobne','cellphone').replace('cellphobne','cellphone').replace('cell phone','cellphone')
    rules = [
        ('kitchenette', r'\b(kitchenette|compact\s+kitchen|small\s+kitchen|kitchen\s+remodel|cabinetry|cabinets?|countertops?|backsplash|sink\s+base|apartment\s+kitchen)\b'),
        ('used_cellphone', r'\b(used\s*cellphone|cellphone|cellular|mobile\s+phone|used\s+phone|phone\s+store|phone\s+shop|smartphone|iphone|samsung|android|pixel|screen\s+repair|battery\s+replacement|phone\s+repair|cell\s+repair|unlocked\s+phone|pre\s*owned\s+phone)\b'),
        ('used_car_lot', r'\b(used\s+car\s+lot|car\s+lot|used\s+cars?|auto\s+sales|dealership|vehicle\s+inventory|pre\s*owned\s+cars?|preowned\s+cars?|car\s+dealer|truck\s+dealer|test\s+drive|financing)\b'),
        ('razor', r'\b(razor|shaver|shaving|grooming|five\s*blade|5\s*blade|blade\s+refill)\b'),
        ('camera_store', r'\b(used\s+camera|camera\s+store|camera\s+shop|photography\s+gear|dslr|mirrorless|lens|lenses|canon|nikon|fujifilm|sony\s+a7)\b'),
        ('furniture_store', r'\b(furniture|sofa|couch|sectional|dining\s+set|bedroom\s+set|mattress|showroom|chairs?|tables?|home\s+decor)\b'),
        ('computer_store', r'\b(computer\s+store|used\s+computer|laptop|desktop|pc\s+shop|gaming\s+pc|macbook|chromebook|computer\s+repair)\b'),
        ('appliance_store', r'\b(appliance|washer|dryer|refrigerator|fridge|stove|oven|dishwasher|laundry\s+pair)\b'),
        ('real_estate', r'\b(real\s+estate|realtor|property|homes?\s+for\s+sale|listing|open\s+house|brokerage)\b'),
        ('church', r'\b(church|ministry|bible\s+study|sermon|prayer|worship|pastor|service\s+times)\b'),
        ('bakery', r'\b(bakery|pastry|cake|bread|dessert|croissant|cookie|cupcake)\b'),
        ('restaurant', r'\b(restaurant|cafe|coffee\s+shop|bistro|food\s+truck|menu|dining)\b'),
        ('salon', r'\b(salon|barber|hair|nails?|spa|beauty)\b'),
        ('plumber', r'\b(plumber|plumbing|drain|water\s+heater|pipe|leak\s+repair)\b'),
        ('law_firm', r'\b(law\s+firm|lawyer|attorney|legal|injury|divorce|estate\s+planning)\b'),
        ('dentist', r'\b(dentist|dental|orthodontic|teeth|smile|cleaning)\b'),
    ]
    for kind, pat in rules:
        if re.search(pat, t): return kind
    return 'universal'


def simo_z71_make_brand(subject: str, kind: str) -> str:
    if kind == 'kitchenette': return 'StudioKit Kitchenettes'
    if kind == 'used_cellphone': return 'Second Life Mobile'
    if kind == 'used_car_lot': return 'Motor Row Select'
    if kind == 'universal':
        core = subject.replace(' Wbsite','').replace(' Website','').strip() or 'Simo Studio'
        return core if re.search(r'\b(co|company|studio|shop|store|center|clinic|church|firm)\b', core, re.I) else core + ' Co.'
    return simo_z70_data('make me a website for ' + subject).get('brand', subject + ' Co.')


def simo_z71_data(prompt: str) -> dict:
    prompt = simo_z71_clean_prompt(prompt)
