def simo_z71_premium_html(prompt: str, title: str = '') -> str:
    return simo_z69_render(simo_z71_data(prompt))

def simo_v3_fallback_html(prompt: str, title: str = '') -> str:
    return simo_z71_premium_html(prompt, title)

def build_subject_premium_html(user_text: str) -> str:
    return simo_z71_premium_html(user_text)

def build_fallback_html(user_text: str) -> str:
    return simo_z71_premium_html(user_text)

_simo_z71_previous_generate_builder_html = generate_builder_html

def generate_builder_html(user_text: str, client, prior_state: dict = None) -> str:
    real = simo_z71_clean_prompt(user_text)
    if is_builder_request(real) or builder_request_kind(real) == 'build' or re.search(r'\b(website|web\s*site|webpage|web\s*page|landing\s+page|homepage|site)\b', real, re.I):
        return simo_z71_premium_html(real, simo_v3_title_from_prompt(real))
    return _simo_z71_previous_generate_builder_html(user_text, client, prior_state)


def api_simo_website_v3_generate_z71():
    try:
        data = request.get_json(silent=True) or {}
        prompt = simo_z71_clean_prompt(str(data.get('prompt') or data.get('message') or '').strip())
        kind = str(data.get('kind') or 'website').strip() or 'website'
        if not prompt:
            return jsonify({'ok': False, 'error': 'Prompt is required.'}), 400
        title = simo_v3_title_from_prompt(prompt)
        html = simo_z71_premium_html(prompt, title)
        session['simo_website_v3_current_html'] = html
        session['simo_website_v3_current_prompt'] = prompt
        return jsonify({'ok': True, 'title': title, 'html': html, 'kind': kind, 'subject_kind': simo_z71_subject_kind(prompt), 'phase': 'R10.60Z71'})
    except Exception as e:
        return jsonify({'ok': False, 'error': f'Website Z71 generation failed: {str(e)}'}), 500

try:
    _simo_z69_original_visual_svg = globals().get('_simo_z69_original_visual_svg') or globals().get('simo_z69_visual_svg')
    # rebind after storing original is handled above by assignment order in this block
except Exception:
    pass
try:
    app.view_functions['api_simo_website_v3_generate'] = api_simo_website_v3_generate_z71
except Exception as _simo_z71_route_err:
    print(f'[SIMO R10.60Z71] could not swap website v3 route: {_simo_z71_route_err}', flush=True)



