# SIMO NORTH STAR REAL BENCHMARK — final Website/App Creator override
# Website lane only. Adds real subject handling for car stereo, guitar strings,
# comic shop, plumbing, tutoring, flashlight, and preserves razor benchmark.
# =========================================================
def simo_ns_kind(prompt: str) -> str:
    t = str(prompt or '').lower()
    rules = [
        ('car_stereo', r'car\s*stereo|car\s*audio|subwoofer|amplifier|speaker\s*install|remote\s*start|dash\s*cam|backup\s*camera'),
        ('guitar_strings', r'guitar\s*strings?|string\s*sets?|bass\s*strings?|acoustic\s*strings?|electric\s*strings?|coated\s*strings?|gauge'),
        ('comic_shop', r'comic\s*book|comic\s*shop|manga|graphic\s*novel|collectibles?|pull\s*list'),
        ('plumbing', r'plumbing|plumber|drain|pipe|water\s*heater|leak\s*repair|sewer|sump\s*pump'),
        ('tutoring', r'tutoring|tutor|math\s*tutor|reading\s*tutor|sat|act|homework|student\s*lessons?|test\s*prep'),
        ('flashlight', r'flashlight|lantern|tactical\s*light|headlamp|torch|battery\s*light'),
        ('razor', r'razor|shaver|shaving|grooming|five\s*blade|5\s*blade|blade\s+refill'),
    ]
    for kind, pat in rules:
        if re.search(pat, t): return kind
    try: return simo_z71_subject_kind(prompt)
    except Exception: return 'universal'


def simo_ns_title(prompt: str) -> str:
    t = re.sub(r'^(please\s+)?(make|build|create|show|design|generate|give)\s+(me|us)?\s*', '', str(prompt or ''), flags=re.I)
    t = re.sub(r'\b(a|an|the|website|web\s*site|webpage|web\s*page|landing\s+page|homepage|site|page|for|about|please)\b', ' ', t, flags=re.I)
    return re.sub(r'\s+', ' ', t).strip(' .-').title() or 'Simo Website'


