def simo_ns_render(d: dict) -> str:
    icon={'car_stereo':'♫','guitar_strings':'≋','comic_shop':'★','plumbing':'⌁','tutoring':'A+','flashlight':'✦'}.get(d['kind'],'◆')
    label={'car_stereo':'dashboard screen • subs • amps • clean wiring','guitar_strings':'nickel • bronze • coated • gauges','comic_shop':'new releases • manga • variants • pull lists','plumbing':'pipes • drains • heaters • emergency service','tutoring':'math • reading • test prep • confidence','flashlight':'lumens • beam distance • runtime • rugged gear'}.get(d['kind'],'subject-specific website')
    cards=''.join([f'<article class="card" data-simo-editable="featured card"><div class="thumb">{i+1}</div><h3>{a}</h3><p>{b}</p><strong>{c}</strong></article>' for i,(a,b,c) in enumerate(d['cards'])])
    services=''.join([f'<article class="mini" data-simo-editable="service card"><h3>{a}</h3><p>{b}</p></article>' for a,b in d['services']])
    nav=''.join([f'<a href="#{slugify(n)}">{n}</a>' for n in d['nav']])
    return f'''<!DOCTYPE html><html lang="en"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1.0"><title>{d['brand']}</title><style>*{{box-sizing:border-box}}html{{scroll-behavior:smooth}}body{{margin:0;font-family:Inter,Arial,sans-serif;background:#050914;color:#f8fafc}}a{{color:inherit;text-decoration:none}}.wrap{{width:min(1180px,calc(100% - 34px));margin:auto}}.page{{overflow:hidden;background:radial-gradient(circle at 74% 18%,{d['accent']}33,transparent 24%),radial-gradient(circle at 16% 8%,{d['accent2']}29,transparent 24%),linear-gradient(180deg,#050914,#0b1220 52%,#050914)}}header{{position:sticky;top:0;z-index:30;background:rgba(5,9,20,.78);backdrop-filter:blur(16px);border-bottom:1px solid rgba(255,255,255,.10)}}nav{{height:76px;display:flex;align-items:center;justify-content:space-between;gap:18px}}.brand{{font-weight:1000;font-size:25px;color:{d['accent']}}}.links{{display:flex;gap:20px;font-weight:900;color:#dbeafe}}.hero{{min-height:82vh;display:grid;grid-template-columns:1fr .9fr;gap:48px;align-items:center;padding:64px 0}}.eyebrow{{display:inline-flex;border:1px solid {d['accent']}99;color:{d['accent']};background:{d['accent']}18;border-radius:999px;padding:9px 13px;text-transform:uppercase;letter-spacing:.16em;font-size:12px;font-weight:1000}}h1{{font-size:clamp(48px,7vw,94px);line-height:.9;letter-spacing:-.065em;margin:18px 0}}.lead{{font-size:21px;line-height:1.64;color:#cbd5e1;max-width:760px}}.actions{{display:flex;gap:14px;flex-wrap:wrap;margin-top:28px}}.btn{{display:inline-flex;border-radius:999px;padding:15px 23px;font-weight:1000}}.primary{{background:{d['accent']};color:#04111d;box-shadow:0 18px 46px {d['accent']}33}}.secondary{{border:1px solid rgba(255,255,255,.22);background:rgba(255,255,255,.05)}}.visual{{min-height:500px;border-radius:42px;border:1px solid rgba(255,255,255,.13);background:linear-gradient(145deg,#111827,#030712);position:relative;overflow:hidden;box-shadow:0 34px 110px #000a}}.glow{{position:absolute;inset:-20%;background:radial-gradient(circle at 55% 24%,{d['accent']}55,transparent 22%),radial-gradient(circle at 75% 76%,{d['accent2']}44,transparent 26%)}}.bigIcon{{position:absolute;inset:0;display:grid;place-items:center;font-size:clamp(96px,13vw,190px);font-weight:1000;color:white;text-shadow:0 18px 55px #000}}.visualLabel{{position:absolute;left:30px;right:30px;bottom:34px;border:1px solid rgba(255,255,255,.14);background:rgba(0,0,0,.35);border-radius:22px;padding:18px;font-weight:1000;color:#e0f2fe;text-transform:uppercase;letter-spacing:.08em}}section{{padding:76px 0}}.sectionHead{{display:flex;justify-content:space-between;gap:24px;align-items:end;flex-wrap:wrap;margin-bottom:26px}}h2{{font-size:clamp(36px,5vw,66px);line-height:1;margin:0;letter-spacing:-.045em}}.muted{{font-size:18px;line-height:1.65;color:#cbd5e1;max-width:760px}}.grid3{{display:grid;grid-template-columns:repeat(3,1fr);gap:18px}}.card,.mini{{background:#101827;border:1px solid rgba(255,255,255,.12);border-radius:28px;padding:25px;box-shadow:0 20px 70px #0005}}.thumb{{height:150px;border-radius:22px;background:linear-gradient(145deg,{d['accent']},{d['accent2']});display:grid;place-items:center;font-size:58px;font-weight:1000;color:#06111f;margin-bottom:18px}}.card h3,.mini h3{{font-size:25px;color:{d['accent']};margin:0 0 12px}}.card p,.mini p{{font-size:18px;color:#e5edf7;line-height:1.55}}.card strong{{font-size:29px}}.banner{{display:grid;grid-template-columns:1fr auto;gap:24px;align-items:center;background:linear-gradient(135deg,{d['accent']},{d['accent2']});color:#020617;border-radius:36px;padding:42px;margin:54px 0}}.banner p{{color:#06111f}}footer{{padding:34px 0;border-top:1px solid rgba(255,255,255,.1);color:#94a3b8}}@media(max-width:900px){{.hero,.grid3,.banner{{grid-template-columns:1fr}}.links{{display:none}}}}</style></head><body><div class="page"><header><nav class="wrap" data-simo-section="nav"><div class="brand">{d['brand']}</div><div class="links">{nav}</div></nav></header><main class="wrap"><section class="hero" data-simo-section="hero"><div><div class="eyebrow">{d['eyebrow']}</div><h1 data-simo-editable="headline">{d['headline']}</h1><p class="lead" data-simo-editable="lead">{d['sub']}</p><div class="actions"><a class="btn primary" data-simo-editable="primary button" href="#contact">{d['primary']}</a><a class="btn secondary" data-simo-editable="secondary button" href="#featured">{d['secondary']}</a></div></div><div class="visual" data-simo-editable="subject visual"><div class="glow"></div><div class="bigIcon">{icon}</div><div class="visualLabel">{label}</div></div></section><section id="featured" data-simo-section="featured"><div class="sectionHead"><h2>Featured offers that match the request.</h2><p class="muted">This is not a title-swapped generic page. The services, product cards, and action path are tied to the subject.</p></div><div class="grid3">{cards}</div></section><section id="services" data-simo-section="services"><div class="grid3">{services}</div></section><section id="contact" data-simo-section="contact"><div class="banner" data-simo-editable="cta"><div><h2>{d['offer_title']}</h2><p>{d['offer_text']}</p></div><a class="btn secondary" href="mailto:hello@example.com">{d['price']}</a></div></section><footer>© 2026 {d['brand']} • Generated by Simo.</footer></main></div></body></html>'''


def simo_ns_html(prompt: str, title: str = '') -> str:
    kind=simo_ns_kind(prompt)
    if kind == 'razor':
        try: return _simo_z65_original_simo_v3_fallback_html(prompt, title or 'R5 Precision')
        except Exception: pass
    if kind not in {'car_stereo','guitar_strings','comic_shop','plumbing','tutoring','flashlight'}:
        try: return simo_z71_premium_html(prompt, title)
        except Exception: pass
    return simo_ns_render(simo_ns_data(prompt))


def api_simo_website_v3_generate_northstar_real():
    try:
        data=request.get_json(silent=True) or {}
        prompt=str(data.get('prompt') or data.get('message') or '').strip()
        if not prompt: return jsonify({'ok':False,'error':'Prompt is required.'}),400
        title=simo_v3_title_from_prompt(prompt)
        html=simo_ns_html(prompt,title)
        session['simo_website_v3_current_html']=html
        session['simo_website_v3_current_prompt']=prompt
        return jsonify({'ok':True,'title':title,'html':html,'kind':str(data.get('kind') or 'website'),'subject_kind':simo_ns_kind(prompt),'phase':'SIMO_NORTHSTAR_REAL_BENCHMARK'})
    except Exception as e:
        return jsonify({'ok':False,'error':f'North Star Website generation failed: {str(e)}'}),500

