def _simo_ns_render(prompt):
    p = _simo_ns_profile(prompt)
    bg = '#05070b' if p.get('dark') else '#f7f1e8'; text = '#ffffff' if p.get('dark') else '#172033'; muted = '#c7d2e6' if p.get('dark') else '#536070'; panel = 'rgba(255,255,255,.08)' if p.get('dark') else 'rgba(255,255,255,.88)'; line = 'rgba(255,255,255,.15)' if p.get('dark') else 'rgba(15,23,42,.13)'; accent=p.get('accent','#38bdf8'); accent2=p.get('accent2','#8b5cf6')
    img_q = urllib.parse.quote_plus(str(p.get('image') or p.get('subject') or 'business'))
    image_url = 'https://source.unsplash.com/1600x1000/?' + img_q
    offers = ''.join(['<article class="card" data-simo-select="offer {0}"><h3>{1}</h3><p>{2}</p><div class="price">{3}</div></article>'.format(i+1,_simo_ns_safe(a),_simo_ns_safe(b),_simo_ns_safe(c)) for i,(a,b,c) in enumerate(p['offers'])])
    sections = ''.join(['<article class="card" data-simo-select="service {0}"><h3>{1}</h3><p>{2}</p></article>'.format(i+1,_simo_ns_safe(a),_simo_ns_safe(b)) for i,(a,b) in enumerate(p['sections'])])
    stats = ''.join(['<div class="stat"><strong>{0}</strong><span>{1}</span></div>'.format(_simo_ns_safe(x.split()[0]),_simo_ns_safe(x)) for x in p['proof']])
    proof = ''.join(['<div><b>0{0}</b><span>{1}</span></div>'.format(i+1,_simo_ns_safe(x)) for i,x in enumerate(p['proof'])])
    nav = ''.join(['<a href="#{0}">{1}</a>'.format(re.sub(r'[^a-z0-9]+','-',n.lower()).strip('-'),_simo_ns_safe(n)) for n in p['nav']])
    if re.search(r'razor|shav|blade|groom', p['subject'], re.I):
        visual = '<div class="razorViz" data-simo-select="razor product visual"><div class="razorHead"></div><div class="razorHandle">R5</div><div class="bladeText">5 BLADES</div></div>'
