def _simo_northstar_subject_clean(prompt: str) -> str:
    raw = re.sub(r"\s+", " ", str(prompt or "")).strip()
    raw = re.sub(r"^(please\s+)?(can you\s+|could you\s+|would you\s+|i want\s+|i need\s+)?(make me|build me|create me|design me|generate me|show me|make|build|create|design|generate|give me)\s+", "", raw, flags=re.I).strip()
    raw = re.sub(r"\b(a|an|the|for me|please|editable|ready to publish|publish ready|website|web site|webpage|web page|landing page|homepage|page|site|app|application|dashboard)\b", " ", raw, flags=re.I)
    raw = re.sub(r"\s+", " ", raw).strip(" .,-—:")
    return raw[:90] or "business"


def _simo_northstar_photo_query(prompt: str) -> str:
    subject = _simo_northstar_subject_clean(prompt).lower()
    words = re.sub(r"[^a-z0-9 ]+", " ", subject).split()
    blocked = {"business", "company", "store", "shop", "service", "website", "page", "landing"}
    kept = [w for w in words if w not in blocked][:5]
    if not kept:
        kept = ["premium", "business"]
    return ",".join(kept + ["detail", "professional"])


def _simo_northstar_ai_prompt(prompt: str, kind: str = "website") -> str:
    subject = _simo_northstar_subject_clean(prompt)
    photo_query = _simo_northstar_photo_query(prompt)
    return """You are SIMO NORTH STAR, an expert AI website/app creator.

The user request is: {prompt!r}
Detected subject: {subject!r}
Build type: {kind!r}

Return ONLY a complete HTML document starting with <!DOCTYPE html>. No markdown. No explanation.

NON-NEGOTIABLE QUALITY STANDARD:
The result must look and read like a beautiful 90% to 100% ready website mockup generated by a premium AI website builder. It must feel custom to the exact subject, not like a reusable generic template.

DESIGN REQUIREMENTS:
- Create a unique visual direction that matches the subject. Infer the industry, customer intent, mood, products/services, proof, and next step.
- Use premium responsive CSS inside one <style> tag. No external CSS files.
- Use subject-relevant imagery or image areas. You may use public image URLs such as https://source.unsplash.com/1600x1000/?{photo_query} for backgrounds/cards, but always add overlays/fallback gradients so the page still looks good.
- Make the hero cinematic and specific. For product prompts, use product launch energy. For stores, show inventory/product cards. For services, show service/process/reviews/quote flow. For churches/Bible study/community, show schedule, groups, prayer/fellowship, and welcome path. For apps/dashboards, create app landing + UI screen cards.
- Include realistic sections that belong to this subject: navigation, hero, services/products/offers, gallery/proof, pricing or packages when useful, testimonials/reviews, FAQ, and contact/booking/order section.
- Include realistic copy, not placeholders. Avoid generic filler phrases like built around what visitors care about, featured offers, custom help, starter path, or signature offer.
- Include real-feeling CTAs, example phone/email/contact details, and preview-safe forms.
- Make it polished on first generation so the user only needs minor edits.

EDITOR HOOKS:
- Add data-simo-section to every major section.
- Add data-simo-editable to headlines, text blocks, buttons, visual/image blocks, cards, pricing/services, reviews, FAQ, and contact form.
- Keep anchors and forms preview-safe.

OUTPUT ONLY THE HTML DOCUMENT.
""".format(prompt=prompt, subject=subject, kind=kind, photo_query=photo_query)


def _simo_northstar_html_is_good(html: str, prompt: str) -> bool:
    raw = str(html or "").strip()
    low = raw.lower()
    if len(raw) < 3500:
        return False
    if "<html" not in low or "</html>" not in low or "<style" not in low:
        return False
    bad = [
        "built around what visitors care about",
        "built around what customers actually came to find",
        "featured offers",
        "custom help",
        "starter path",
        "signature offer",
        "lorem ipsum",
        "placeholder"
    ]
    if any(x in low for x in bad):
        return False
    subject_words = [w for w in re.sub(r"[^a-z0-9 ]+", " ", _simo_northstar_subject_clean(prompt).lower()).split() if len(w) > 3]
    if subject_words and not any(w in low for w in subject_words[:6]):
        return False
    return True


