def _simo_northstar_generate_endpoint_v2():
    try:
        data = request.get_json(silent=True) or {}
        prompt = str(data.get("prompt") or data.get("message") or "").strip()
        kind = str(data.get("kind") or "website").strip() or "website"
        if not prompt:
            return jsonify({"ok": False, "error": "Prompt is required."}), 400
        title = simo_v3_title_from_prompt(prompt)
        client = get_client()
        html = ""
        source = "local_premium"
        ai_error = ""
        if client:
            try:
                resp = client.responses.create(model=OPENAI_MODEL, input=[{"role":"system","content":_simo_northstar_ai_prompt(prompt, kind)}, {"role":"user","content":prompt}])
                html = simo_v3_extract_html(extract_first_text_from_openai_response(resp))
                if _simo_northstar_html_is_good(html, prompt): source = "ai"
            except Exception as e1:
                ai_error = str(e1)
                try:
                    resp = client.chat.completions.create(model=OPENAI_MODEL, messages=[{"role":"system","content":_simo_northstar_ai_prompt(prompt, kind)}, {"role":"user","content":prompt}])
                    html = simo_v3_extract_html(extract_first_text_from_openai_response(resp))
                    if _simo_northstar_html_is_good(html, prompt): source = "ai"
                except Exception as e2:
                    ai_error = (ai_error + " | " + str(e2)).strip(" |")
        if source != "ai":
            html = _simo_ns_v2_html(prompt, title)
        session["simo_website_v3_current_html"] = html
        session["simo_website_v3_current_prompt"] = prompt
        return jsonify({"ok": True, "title": title, "html": html, "kind": kind, "subject": _simo_northstar_subject_clean(prompt), "phase": "SIMO_NORTHSTAR_AI_FIRST_PREMIUM_LOCAL_V2_2026_06_22", "source": source, "ai_error": ai_error if source != "ai" else ""})
    except Exception as e:
        return jsonify({"ok": False, "error": "North Star V2 generation failed: " + str(e)}), 500

try:
    app.view_functions["api_simo_website_v3_generate"] = _simo_northstar_generate_endpoint_v2
    print("[SIMO NORTH STAR V2] AI-first route active with premium local render fallback.", flush=True)
except Exception as _simo_v2_err:
    print("[SIMO NORTH STAR V2] route override failed: " + str(_simo_v2_err), flush=True)

# =========================================================
# SIMO NORTH STAR V3 — ARTIFACT-GRADE WEBSITE RENDERER
# Fix: do not accept weak AI/plain template output as a finished website.
# The route now returns a premium, image-forward, subject-specific page.
# =========================================================
def _simo_artifact_clean_subject(prompt: str) -> str:
    raw = re.sub(r"\s+", " ", str(prompt or "")).strip()
    raw = re.sub(r"^(please\s+)?(can you\s+|could you\s+|would you\s+|i want\s+|i need\s+)?(make me|build me|create me|design me|generate me|show me|make|build|create|design|generate|give me)\s+", "", raw, flags=re.I).strip()
    raw = re.sub(r"\b(a|an|the|for me|please|editable|ready to publish|publish ready|website|web site|webpage|web page|landing page|homepage|page|site|app|application|dashboard)\b", " ", raw, flags=re.I)
    raw = re.sub(r"\s+", " ", raw).strip(" .,-—:")
    return raw[:90] or "business"


def _simo_artifact_kind(subject: str) -> str:
    s = str(subject or "").lower()
    if re.search(r"\b(monitor|display|screen|computer monitor|gaming monitor|4k monitor|ultrawide)\b", s): return "monitor"
    if re.search(r"\b(razor|shav|blade|groom)\b", s): return "razor"
    if re.search(r"\b(camera|lens|photography|photo gear)\b", s): return "camera"
    if re.search(r"\b(furniture|sofa|chair|table|bedroom|living room)\b", s): return "furniture"
    if re.search(r"\b(car|classic car|used car|auto lot|vehicle)\b", s): return "auto"
    if re.search(r"\b(church|bible|ministry|prayer|study group)\b", s): return "community"
    if re.search(r"\b(plumb|roof|floor|repair|service|clinic|dental|contractor)\b", s): return "service"
    if re.search(r"\b(store|shop|boutique|sunglasses|battery|guitar|comic|tire|rim|retail)\b", s): return "retail"
    return "universal"


