def _simo_artifact_html(prompt: str) -> str:
    p = _simo_artifact_profile(prompt)
    def e(v):
        return str(v or "").replace("&","&amp;").replace("<","&lt;").replace(">","&gt;").replace('"',"&quot;").replace("'","&#039;")
    brand=e(p["brand"]); accent=p["accent"]; accent2=p["accent2"]
    nav=''.join([f'<a href="#{e(n).lower().replace(" ","-")}">{e(n)}</a>' for n in p["nav"]]) + '<a class="navCta" href="#contact">Get Help</a>'
    cards=''.join([f'<article class="productCard" data-simo-editable="product card"><div class="productPhoto" style="background-image:url({e(p["gallery"][i%len(p["gallery"])])})"></div><div class="productBody"><h3>{e(a)}</h3><p>{e(b)}</p><div class="price">{e(c)}</div></div></article>' for i,(a,b,c) in enumerate(p["cards"])])
    features=''.join([f'<article class="infoCard" data-simo-editable="feature card"><span>0{i+1}</span><h3>{e(a)}</h3><p>{e(b)}</p></article>' for i,(a,b) in enumerate(p["features"])])
    gallery=''.join([f'<div class="galleryImg" data-simo-editable="gallery image" style="background-image:url({e(u)})"></div>' for u in p["gallery"]])
    reviews=''.join([f'<article class="review" data-simo-editable="customer review"><div class="stars">★★★★★</div><p>“{e(b)}”</p><b>{e(a)}</b></article>' for a,b in p["reviews"]])
    faq=''.join([f'<details data-simo-editable="faq item"><summary>{e(a)}</summary><p>{e(b)}</p></details>' for a,b in p["faq"]])
    return f'''<!DOCTYPE html>
<html lang="en"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1.0"><title>{brand}</title><style>
*{{box-sizing:border-box}}html{{scroll-behavior:smooth}}body{{margin:0;font-family:Inter,Arial,sans-serif;background:#050914;color:#f8fafc;line-height:1.5}}a{{color:inherit;text-decoration:none}}.wrap{{width:min(1120px,calc(100% - 36px));margin:auto}}.site{{overflow:hidden;background:radial-gradient(circle at 72% 8%,{accent}33,transparent 24%),radial-gradient(circle at 10% 20%,{accent2}24,transparent 24%),linear-gradient(180deg,#050914,#07101e 44%,#050914)}}
.nav{{position:sticky;top:0;z-index:20;border-bottom:1px solid rgba(255,255,255,.10);background:rgba(5,9,20,.72);backdrop-filter:blur(18px)}}.nav .wrap{{display:flex;align-items:center;justify-content:space-between;gap:20px;padding:18px 0}}.brand{{display:flex;align-items:center;gap:11px;font-size:24px;font-weight:1000;letter-spacing:-.05em}}.mark{{width:34px;height:34px;border-radius:12px;background:linear-gradient(135deg,{accent},{accent2});box-shadow:0 0 40px {accent}77}}.links{{display:flex;align-items:center;gap:21px;font-weight:900;color:#dbeafe}}.navCta,.btn{{display:inline-flex;align-items:center;justify-content:center;border-radius:999px;padding:14px 19px;font-weight:1000}}.navCta,.primary{{background:{accent};color:#04111d;box-shadow:0 18px 50px {accent}38}}.secondary{{border:1px solid rgba(255,255,255,.20);background:rgba(255,255,255,.08)}}
.hero{{min-height:86vh;display:grid;grid-template-columns:1fr .98fr;gap:38px;align-items:center;padding:62px 0}}.eyebrow{{display:inline-flex;color:{accent};font-size:12px;letter-spacing:.34em;text-transform:uppercase;font-weight:1000;margin-bottom:20px}}h1{{font-size:clamp(52px,7vw,92px);line-height:.95;letter-spacing:-.075em;margin:0 0 22px;max-width:900px}}.lead{{font-size:20px;color:#dbeafe;max-width:690px;margin:0}}.actions{{display:flex;gap:14px;flex-wrap:wrap;margin-top:30px}}.heroStage{{position:relative;min-height:560px;border-radius:38px;overflow:hidden;border:1px solid rgba(255,255,255,.13);box-shadow:0 40px 110px rgba(0,0,0,.48);background:#0d1423}}.heroPhoto{{position:absolute;inset:0;background:url('{e(p["hero_img"])}') center/cover;filter:saturate(1.05) contrast(1.04);opacity:.72}}.heroStage:after{{content:"";position:absolute;inset:0;background:linear-gradient(90deg,rgba(5,9,20,.34),rgba(5,9,20,.15)),linear-gradient(180deg,transparent,rgba(5,9,20,.88))}}.glassLabel{{position:absolute;z-index:2;left:24px;right:24px;bottom:24px;border:1px solid rgba(255,255,255,.18);background:rgba(5,9,20,.55);backdrop-filter:blur(14px);border-radius:24px;padding:20px}}.glassLabel b{{display:block;font-size:30px;letter-spacing:-.04em}}.glassLabel span{{color:#cbd5e1}}
section{{padding:76px 0}}.sectionTop{{display:flex;justify-content:space-between;align-items:end;gap:22px;margin-bottom:28px;flex-wrap:wrap}}h2{{font-size:clamp(34px,5vw,60px);line-height:1;letter-spacing:-.055em;margin:0}}.muted{{color:#9fb0cc;font-size:18px;max-width:720px}}.productGrid,.infoGrid,.reviewGrid{{display:grid;grid-template-columns:repeat(3,1fr);gap:20px}}.productCard,.infoCard,.review,details,.contactBox{{border:1px solid rgba(255,255,255,.13);background:linear-gradient(180deg,rgba(255,255,255,.08),rgba(255,255,255,.035));border-radius:28px;overflow:hidden;box-shadow:0 22px 58px rgba(0,0,0,.24)}}.productPhoto{{height:190px;background-size:cover;background-position:center}}.productBody,.infoCard,.review{{padding:24px}}h3{{font-size:23px;margin:0 0 10px;letter-spacing:-.03em}}.productCard p,.infoCard p,.review p,details p{{color:#cbd5e1}}.price{{margin-top:20px;color:{accent};font-weight:1000;font-size:20px}}.infoCard span{{color:{accent};font-size:13px;letter-spacing:.26em;font-weight:1000}}.galleryGrid{{display:grid;grid-template-columns:1.2fr .9fr .9fr;gap:18px}}.galleryImg{{min-height:330px;border-radius:30px;background-size:cover;background-position:center;border:1px solid rgba(255,255,255,.13);box-shadow:0 26px 70px rgba(0,0,0,.30)}}.stars{{color:{accent};letter-spacing:.12em}}details{{padding:18px 20px;margin-bottom:12px}}summary{{cursor:pointer;font-weight:1000;font-size:18px}}.contactBox{{display:grid;grid-template-columns:1fr .9fr;gap:24px;padding:32px;background:linear-gradient(135deg,{accent}22,{accent2}20)}}form{{display:grid;gap:12px}}input,textarea{{width:100%;border:1px solid rgba(255,255,255,.14);background:rgba(255,255,255,.08);color:white;border-radius:16px;padding:15px;font:inherit}}textarea{{min-height:110px}}footer{{padding:30px 0;border-top:1px solid rgba(255,255,255,.10);color:#94a3b8}}@media(max-width:900px){{.hero,.contactBox{{grid-template-columns:1fr}}.productGrid,.infoGrid,.reviewGrid,.galleryGrid{{grid-template-columns:1fr}}.links{{display:none}}.heroStage{{min-height:440px}}}}
</style></head><body><main class="site"><nav class="nav" data-simo-section="navigation"><div class="wrap"><div class="brand" data-simo-editable="brand"><span class="mark"></span>{brand}</div><div class="links">{nav}</div></div></nav><section class="hero wrap" data-simo-section="hero"><div><span class="eyebrow" data-simo-editable="eyebrow">{e(p["eyebrow"])}</span><h1 data-simo-editable="headline">{e(p["headline"])}</h1><p class="lead" data-simo-editable="intro text">{e(p["sub"])}</p><div class="actions"><a class="btn primary" data-simo-editable="primary button" href="#products">{e(p["primary"])}</a><a class="btn secondary" data-simo-editable="secondary button" href="#features">{e(p["secondary"])}</a></div></div><div class="heroStage" data-simo-editable="hero image"><div class="heroPhoto"></div><div class="glassLabel"><b>{brand}</b><span>{e(p["subject"])} page designed with product visuals, offers, proof, and contact flow.</span></div></div></section><section id="products" class="wrap" data-simo-section="products pricing"><div class="sectionTop"><div><h2 data-simo-editable="section headline">Find your perfect option</h2><p class="muted" data-simo-editable="section intro">Product and service cards with real-feeling details instead of placeholder boxes.</p></div></div><div class="productGrid">{cards}</div></section><section id="gallery" class="wrap" data-simo-section="gallery"><div class="sectionTop"><div><h2>Visual examples</h2><p class="muted">Relevant imagery gives the page the premium look visitors expect.</p></div></div><div class="galleryGrid">{gallery}</div></section><section id="features" class="wrap" data-simo-section="features"><div class="sectionTop"><div><h2>Built for real visitors</h2><p class="muted">Clear comparison points, trust signals, and useful information make the page feel ready.</p></div></div><div class="infoGrid">{features}</div></section><section id="reviews" class="wrap" data-simo-section="reviews"><div class="sectionTop"><div><h2>Customer reviews</h2><p class="muted">Replace these examples with real testimonials before publishing.</p></div></div><div class="reviewGrid">{reviews}</div></section><section id="pricing" class="wrap" data-simo-section="questions"><div class="sectionTop"><div><h2>Questions people ask</h2><p class="muted">Helpful answers that support buying, booking, or contacting.</p></div></div>{faq}</section><section id="contact" class="wrap" data-simo-section="contact"><div class="contactBox"><div><h2 data-simo-editable="contact headline">Ready to start with {brand}?</h2><p class="muted" data-simo-editable="contact text">Call (555) 010-2026, email hello@example.com, or send a quick request. Replace this with the real business details.</p></div><form data-simo-editable="contact form" onsubmit="event.preventDefault();this.querySelector('button').textContent='Message captured';"><input placeholder="Name"><input placeholder="Email or phone"><textarea placeholder="What are you looking for?"></textarea><button class="btn primary" type="submit">Send Request</button></form></div></section><footer><div class="wrap">© 2026 {brand} — Built with Simo.</div></footer></main></body></html>'''


def _simo_northstar_generate_endpoint_v3():
    try:
        data = request.get_json(silent=True) or {}
        prompt = str(data.get("prompt") or data.get("message") or "").strip()
        kind = str(data.get("kind") or "website").strip() or "website"
        if not prompt:
            return jsonify({"ok": False, "error": "Prompt is required."}), 400
        html = _simo_artifact_html(prompt)
        title = _simo_artifact_profile(prompt).get("brand") or _simo_artifact_clean_subject(prompt).title()
        session["simo_website_v3_current_html"] = html
        session["simo_website_v3_current_prompt"] = prompt
        return jsonify({"ok": True, "title": title, "html": html, "kind": kind, "subject": _simo_artifact_clean_subject(prompt), "phase": "SIMO_NORTHSTAR_V3_ARTIFACT_GRADE_2026_06_22", "source": "artifact_grade_renderer"})
    except Exception as e:
        return jsonify({"ok": False, "error": "North Star V3 generation failed: " + str(e)}), 500

try:
    app.view_functions["api_simo_website_v3_generate"] = _simo_northstar_generate_endpoint_v3
    print("[SIMO NORTH STAR V3] Artifact-grade Website Builder route active; weak AI/plain template output bypassed.", flush=True)
except Exception as _simo_v3_artifact_err:
    print("[SIMO NORTH STAR V3] route override failed: " + str(_simo_v3_artifact_err), flush=True)



