def _simo_v4_clean_prompt(prompt: str) -> str:
    import re
    t = str(prompt or '').strip()
    t = re.sub(r'^(please\s+)?(can you\s+|could you\s+|would you\s+|i want\s+|i need\s+)?(make me|build me|create me|design me|generate me|show me|make|build|create|design|generate|give me)\s+', '', t, flags=re.I)
    t = re.sub(r'\b(a|an|the|for me|please|editable|ready to publish|publish ready|website|web site|webpage|web page|landing page|homepage|page|site|app|application|dashboard)\b', ' ', t, flags=re.I)
    t = re.sub(r'\s+', ' ', t).strip(' .,-')
    return t or 'business'

def _simo_v4_kind(subject: str) -> str:
    import re
    s = str(subject or '').lower()
    rules = [
        ('monitor', r'\b(computer monitor|monitor|display|screen|ultrawide|gaming screen)\b'),
        ('music', r'\b(music studio|recording studio|audio studio|podcast studio|mixing|mastering|sound studio)\b'),
        ('auto', r'\b(classic car|car lot|used car|auto|vehicle|mechanic|tire|rim|wheel)\b'),
        ('church', r'\b(church|bible|ministry|worship|prayer)\b'),
        ('home', r'\b(furniture|hardwood|flooring|kitchen|kitchenette|cabinet|blind|shade|window|interior)\b'),
        ('service', r'\b(plumb|repair|stained glass|contractor|roof|cleaning|hvac|electric)\b'),
        ('fitness', r'\b(fitness|gym|trainer|yoga|wellness)\b'),
        ('pet', r'\b(animal shelter|pet|dog|cat|rescue|veterinary)\b'),
        ('realestate', r'\b(real estate|realtor|property|homes)\b'),
        ('food', r'\b(bakery|restaurant|coffee|grocery|food|cafe)\b'),
        ('retail', r'\b(sunglasses|fashion|store|shop|battery|guitar|string|comic|camera|phone|computer)\b'),
    ]
    for k, rx in rules:
        if re.search(rx, s): return k
    return 'universal'

