def _simo_v4_html(prompt: str) -> str:
    import html
    p = _simo_v4_profile(prompt)
    kind = _simo_v4_kind(_simo_v4_clean_prompt(prompt))
    def e(v): return html.escape(str(v or ''))
    accent, accent2 = p['accent'], p['accent2']
    hero = _simo_v4_svg_uri(kind, p['brand'], accent, accent2, 0)
    imgs = [_simo_v4_svg_uri(kind, title, accent, accent2, i+1) for i,(title,_,_) in enumerate(p['products'])]
    cards = ''.join([f'<article class="product-card" data-simo-editable="product card"><img src="{imgs[i]}" alt="{e(t)}"><div class="pcopy"><h3>{e(t)}</h3><p>{e(d)}</p><span>{e(price)}</span></div></article>' for i,(t,d,price) in enumerate(p['products'])])
    gallery = ''.join([f'<img src="{imgs[i]}" alt="{e(p["products"][i][0])}">' for i in range(min(3,len(imgs)))])
    features = ''.join([f'<article><b>0{i+1}</b><h3>{e(t)}</h3><p>{e(d)}</p></article>' for i,(t,d) in enumerate(p['features'])])
    reviews = ''.join([f'<article><div class="stars">★★★★★</div><p>“{txt}”</p><b>{name}</b></article>' for txt,name in [('The page immediately made the business feel real and professional.','Clean and premium'),('The visuals and offers are easy to understand quickly.','Easy to compare'),('It feels custom to the subject instead of a basic template.','Subject matched')]])
    faq = ''.join([f'<details><summary>{q}</summary><p>{a}</p></details>' for q,a in [('Can this be customized?','Yes. Change the words, prices, images, links, forms, services, products, and colors inside Simo.'),('Is this ready to publish?','It is built to be close. Replace real contact info, business photos, legal details, and final pricing before launch.'),('Can I add booking, social links, or video?','Yes. Use the builder buttons or type the change into the selected-area prompt.')]])
    css = f'''*{{box-sizing:border-box}}html{{scroll-behavior:smooth}}body{{margin:0;background:#020814;color:#f8fbff;font-family:Inter,ui-sans-serif,system-ui,-apple-system,Segoe UI,Arial,sans-serif;line-height:1.5}}a{{color:inherit;text-decoration:none}}img{{display:block;width:100%;height:auto}}.site{{min-height:100vh;overflow:hidden;background:radial-gradient(circle at 82% 12%,{accent}24,transparent 28%),radial-gradient(circle at 8% 25%,{accent2}22,transparent 30%),linear-gradient(180deg,#030915 0%,#06101f 50%,#020814 100%)}}.wrap{{width:min(1160px,calc(100% - 42px));margin:auto}}.nav{{position:sticky;top:0;z-index:20;background:rgba(2,8,20,.72);backdrop-filter:blur(18px);border-bottom:1px solid rgba(255,255,255,.08)}}.nav .wrap{{display:flex;justify-content:space-between;align-items:center;gap:18px;padding:18px 0}}.brand{{display:flex;align-items:center;gap:12px;font-weight:1000;font-size:22px;letter-spacing:-.03em}}.mark{{width:38px;height:38px;border-radius:14px;background:linear-gradient(135deg,{accent},{accent2});box-shadow:0 0 34px {accent}66}}.links{{display:flex;gap:20px;flex-wrap:wrap;color:#cbd5e1;font-weight:800}}.links a:last-child{{color:#06101f;background:{accent};padding:10px 16px;border-radius:999px}}.hero{{display:grid;grid-template-columns:minmax(0,1fr) minmax(420px,.95fr);gap:48px;align-items:center;min-height:760px;padding:72px 0 84px}}.eyebrow{{display:inline-flex;color:{accent};text-transform:uppercase;letter-spacing:.34em;font-size:13px;font-weight:1000;margin-bottom:22px}}h1{{font-size:clamp(52px,7.8vw,92px);line-height:.92;letter-spacing:-.075em;margin:0 0 24px;max-width:760px}}.lead{{font-size:20px;color:#dbeafe;max-width:680px;margin:0 0 30px}}.actions{{display:flex;gap:14px;flex-wrap:wrap}}.btn{{display:inline-flex;align-items:center;justify-content:center;min-height:48px;border-radius:999px;padding:13px 21px;font-weight:1000;border:1px solid rgba(255,255,255,.16)}}.primary{{background:linear-gradient(135deg,{accent},{accent2});color:#020814;box-shadow:0 18px 45px {accent}30}}.secondary{{background:rgba(255,255,255,.07);color:#fff}}.hero-card{{position:relative;border-radius:36px;overflow:hidden;border:1px solid rgba(255,255,255,.14);box-shadow:0 40px 100px rgba(0,0,0,.5);background:#0f172a}}.hero-card img{{height:560px;object-fit:cover}}.hero-card:after{{content:"";position:absolute;inset:0;background:linear-gradient(180deg,transparent 35%,rgba(2,8,20,.9))}}.hero-label{{position:absolute;left:26px;right:26px;bottom:24px;z-index:2;padding:20px;border-radius:24px;background:rgba(2,8,20,.72);border:1px solid rgba(255,255,255,.14);backdrop-filter:blur(12px)}}.hero-label b{{font-size:24px;display:block}}.hero-label span{{color:#cbd5e1}}section{{padding:70px 0}}.section-title{{display:flex;justify-content:space-between;gap:24px;align-items:end;margin-bottom:26px}}h2{{font-size:clamp(34px,4vw,54px);line-height:1;margin:0 0 10px;letter-spacing:-.055em}}.muted{{color:#aab7c8}}.product-grid,.feature-grid,.review-grid{{display:grid;grid-template-columns:repeat(3,1fr);gap:22px}}.product-card,.feature-grid article,.review-grid article,.contact-box,details{{background:linear-gradient(180deg,rgba(255,255,255,.075),rgba(255,255,255,.035));border:1px solid rgba(255,255,255,.13);border-radius:24px;box-shadow:0 18px 46px rgba(0,0,0,.25);overflow:hidden}}.product-card img{{height:245px;object-fit:cover}}.pcopy{{padding:24px}}h3{{font-size:23px;margin:0 0 12px;letter-spacing:-.03em}}.pcopy p,.feature-grid p,.review-grid p{{color:#d7e0ee;margin:0 0 18px}}.pcopy span{{color:{accent};font-weight:1000;font-size:18px}}.gallery-grid{{display:grid;grid-template-columns:1.2fr .8fr .8fr;gap:18px}}.gallery-grid img{{height:300px;object-fit:cover;border-radius:26px;border:1px solid rgba(255,255,255,.13);box-shadow:0 20px 50px rgba(0,0,0,.28)}}.gallery-grid img:first-child{{height:420px;grid-row:span 2}}.feature-grid article,.review-grid article{{padding:24px}}.feature-grid b{{color:{accent};letter-spacing:.2em}}.stars{{color:{accent};letter-spacing:.08em;margin-bottom:12px}}details{{padding:20px 22px;margin-bottom:14px}}summary{{font-weight:1000;cursor:pointer}}details p{{color:#cbd5e1}}.contact-box{{display:grid;grid-template-columns:1fr .9fr;gap:28px;padding:34px}}input,textarea{{width:100%;padding:15px 16px;margin-bottom:12px;border-radius:16px;border:1px solid rgba(255,255,255,.13);background:rgba(2,8,20,.72);color:#fff}}textarea{{min-height:112px}}footer{{padding:32px 0;color:#94a3b8;border-top:1px solid rgba(255,255,255,.09)}}@media(max-width:900px){{.hero,.contact-box{{grid-template-columns:1fr}}.product-grid,.feature-grid,.review-grid,.gallery-grid{{grid-template-columns:1fr}}.hero-card img,.gallery-grid img,.gallery-grid img:first-child{{height:auto}}.links{{display:none}}}}'''
    return f'''<!DOCTYPE html><html lang="en"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1.0"><title>{e(p['brand'])}</title><style>{css}</style></head><body><main class="site"><nav class="nav" data-simo-section="navigation"><div class="wrap"><div class="brand" data-simo-editable="brand"><span class="mark"></span>{e(p['brand'])}</div><div class="links"><a href="#products">Offers</a><a href="#gallery">Gallery</a><a href="#features">Details</a><a href="#reviews">Reviews</a><a href="#contact">Start</a></div></div></nav><section class="hero wrap" data-simo-section="top section"><div><span class="eyebrow" data-simo-editable="eyebrow">{e(p['eyebrow'])}</span><h1 data-simo-editable="headline">{e(p['headline'])}</h1><p class="lead" data-simo-editable="intro text">{e(p['sub'])}</p><div class="actions"><a href="#contact" class="btn primary" data-simo-editable="primary button">{e(p['primary'])}</a><a href="#products" class="btn secondary" data-simo-editable="secondary button">{e(p['secondary'])}</a></div></div><div class="hero-card" data-simo-editable="main image"><img src="{hero}" alt="{e(p['brand'])} visual"><div class="hero-label"><b>{e(p['brand'])}</b><span>{e(p['hero_note'])}</span></div></div></section><section id="products" class="wrap" data-simo-section="products pricing"><div class="section-title"><div><h2>Find your perfect option</h2><p class="muted">Real product or service cards with subject-matched visuals and useful visitor details.</p></div></div><div class="product-grid">{cards}</div></section><section id="gallery" class="wrap" data-simo-section="gallery"><div class="section-title"><div><h2>Visual examples</h2><p class="muted">No blank image boxes. These generated visuals are matched to the subject and can be replaced later.</p></div></div><div class="gallery-grid">{gallery}</div></section><section id="features" class="wrap" data-simo-section="features"><div class="section-title"><div><h2>Built for real visitors</h2><p class="muted">Clear details, trust signals, and strong next steps make this feel close to ready.</p></div></div><div class="feature-grid">{features}</div></section><section id="reviews" class="wrap" data-simo-section="reviews"><div class="section-title"><div><h2>Customer reviews</h2><p class="muted">Example proof that can be replaced with real testimonials.</p></div></div><div class="review-grid">{reviews}</div></section><section id="questions" class="wrap" data-simo-section="questions"><div class="section-title"><div><h2>Questions people ask</h2><p class="muted">Helpful answers for buyers, clients, visitors, or booking requests.</p></div></div>{faq}</section><section id="contact" class="wrap" data-simo-section="contact"><div class="contact-box"><div><span class="eyebrow">Ready to publish</span><h2>Start with {e(p['brand'])}</h2><p class="muted">Replace this with the real phone, email, address, links, booking page, and business details before launch.</p></div><form data-simo-editable="contact form" onsubmit="event.preventDefault();this.querySelector('button').textContent='Message captured';"><input placeholder="Name"><input placeholder="Email or phone"><textarea placeholder="What are you looking for?"></textarea><button class="btn primary" type="submit">Send Request</button></form></div></section><footer><div class="wrap">2026 {e(p['brand'])} — Built with Simo.</div></footer></main></body></html>'''

def _simo_northstar_generate_endpoint_v4():
    try:
        data = request.get_json(silent=True) or {}
        prompt = str(data.get('prompt') or data.get('message') or data.get('text') or '').strip()
        kind = str(data.get('kind') or 'website')
        if not prompt:
            return jsonify({'ok': False, 'error': 'Missing prompt'}), 400
        html = _simo_v4_html(prompt)
        title = _simo_v4_profile(prompt).get('brand') or _simo_v4_clean_prompt(prompt).title()
        return jsonify({'ok': True, 'title': title, 'html': html, 'kind': kind, 'subject': _simo_v4_clean_prompt(prompt), 'phase': 'SIMO_NORTHSTAR_V4_SUBJECT_PREMIUM_NO_BLANK_CARDS_2026_06_22', 'source': 'subject_premium_renderer_v4'})
    except Exception as err:
        return jsonify({'ok': False, 'error': str(err), 'phase': 'SIMO_NORTHSTAR_V4_ERROR'}), 500

try:
    app.view_functions['api_simo_website_v3_generate'] = _simo_northstar_generate_endpoint_v4
    print('[SIMO NORTH STAR V4] Subject-premium route active: no weak fallback, no blank image cards, stronger subject profiles.', flush=True)
except Exception as _simo_v4_route_err:
    print('[SIMO NORTH STAR V4] route override failed: ' + str(_simo_v4_route_err), flush=True)


# =========================================================
# SIMO NORTH STAR V5 — TRUE AI DESIGNER ROUTE
# Purpose: stop one-template renderer. The AI designs the full site.
# Backend fallback does not render generic websites anymore.
# =========================================================

def _simo_v5_plain_subject(prompt: str) -> str:
    raw = str(prompt or '').strip()
    raw = re.sub(r"^(please\s+)?(can you\s+|could you\s+|would you\s+|i want\s+|i need\s+)?(make me|build me|create me|design me|generate me|show me|make|build|create|design|generate|give me)\s+", "", raw, flags=re.I)
    raw = re.sub(r"\b(a|an|the|for me|please|editable|ready to publish|publish ready|website|web site|webpage|web page|landing page|homepage|page|site|app|application|dashboard)\b", " ", raw, flags=re.I)
    raw = re.sub(r"\s+", " ", raw).strip(' .,-')
    return raw[:90] or 'business'


def _simo_v5_photo_query(subject: str, role: str = '') -> str:
    base = re.sub(r"[^a-zA-Z0-9 ]+", " ", str(subject or '')).strip() or 'business website'
    role = re.sub(r"[^a-zA-Z0-9 ]+", " ", str(role or '')).strip()
    return (base + (' ' + role if role else '')).strip().replace(' ', ',')


def _simo_v5_designer_system_prompt(prompt: str, kind: str = 'website') -> str:
    subject = _simo_v5_plain_subject(prompt)
    return f"""
You are Simo's WEBSITE DESIGNER ENGINE, not a template filler.
Your job is to create a unique, 90-100% ready publishable {kind} for the user's exact request.

USER REQUEST SUBJECT: {subject}
RAW USER REQUEST: {prompt}

CRITICAL NORTH STAR:
- Think like a senior human web designer creating a fresh ChatGPT-style artifact.
- First infer the business, audience, mood, visual world, offers, sections, and visitor goals.
- Choose a UNIQUE layout for this subject. Do NOT reuse a universal dark hero + cards template.
- Every subject must feel different: layout, colors, typography scale, section order, imagery, copy, cards, and CTA flow.
- A music studio must feel like recording booths, mixing consoles, artists, session booking, audio packages, demos, and creative energy.
- A computer monitor site must feel like screens, gaming/creator/product specs, display comparisons, ports, refresh rates, and ecommerce cards.
- A church/Bible study must feel warm, welcoming, ministry/community, service times, prayer, sermons, groups.
- A flooring site must feel like wood texture, interiors, before/after work, estimates, installation, finishes.
- A sunglasses store must feel like fashion, lifestyle, product collection, lookbook, seasonal drops.
- For any unknown curveball, invent the correct visual direction from the subject itself.

OUTPUT RULES:
- Return ONE complete HTML document only. No markdown. No explanation.
- Include all CSS inside <style>. No external CSS/JS dependencies.
- Must be responsive and look premium in a browser immediately.
- Include at least 6 subject-relevant image elements using Unsplash Source URLs like:
  https://source.unsplash.com/1600x1000/?{_simo_v5_photo_query(subject, 'hero')}
  and vary the query words per image.
- Do not use empty image boxes, broken placeholder rectangles, lorem ipsum, generic filler, or repeated sections.
- Do not include phrases like "A sharper website for", "Visual Examples", "Find your perfect option", "Built for real visitors", or "Real-looking example images".
- Write real subject-specific copy, services/products, pricing/examples, FAQ, reviews, and contact flow.
- Add data-simo-section and data-simo-editable attributes on major sections/elements so the editor can select and edit them.
- Buttons can link to section anchors.
- Keep it safe: no tracking scripts, no external JavaScript.

QUALITY BAR:
The result should look closer to a premium custom website mockup than a generic website-builder template.
""".strip()


def _simo_v5_extract_text(resp) -> str:
    try:
        return extract_first_text_from_openai_response(resp)
    except Exception:
        pass
    try:
        if hasattr(resp, 'output_text') and resp.output_text:
            return str(resp.output_text).strip()
    except Exception:
        pass
    try:
        return str(resp.choices[0].message.content or '').strip()
    except Exception:
        return ''


def _simo_v5_extract_html(text: str) -> str:
    raw = str(text or '').strip()
    raw = re.sub(r"^```(?:html)?\s*", "", raw, flags=re.I).strip()
    raw = re.sub(r"\s*```$", "", raw).strip()
    try:
        doc = extract_html_document(raw)
        if doc:
            return doc
    except Exception:
        pass
    lo = raw.lower()
    i = lo.find('<!doctype html')
    if i < 0:
        i = lo.find('<html')
    if i >= 0:
        return raw[i:].strip()
    return raw


def _simo_v5_is_bad_html(html: str, prompt: str) -> tuple:
    h = str(html or '')
    lo = h.lower()
    subject = _simo_v5_plain_subject(prompt).lower()
    if '<html' not in lo or '<style' not in lo or '</html>' not in lo:
        return True, 'not a complete styled html document'
    if len(h) < 12000:
        return True, 'too short for a premium ready website'
    banned = [
        'a sharper website for',
        'visual examples',
        'find your perfect option',
        'built for real visitors',
        'real-looking example images',
        'replace these with your own photos anytime',
        'subject-aware layout',
        'universal subject intelligence',
        'lorem ipsum',
        'placeholder image',
        'via.placeholder',
        'placehold.co',
        'placekitten',
        'dummyimage',
    ]
    for b in banned:
        if b in lo:
            return True, 'contains old/template phrase: ' + b
    # Require subject words to appear throughout the real page.
    words = [w for w in re.sub(r'[^a-z0-9 ]+', ' ', subject).split() if len(w) > 3]
    if words:
        hits = sum(lo.count(w) for w in words)
        if hits < max(4, min(12, len(words) * 3)):
            return True, 'not enough subject-specific copy'
    img_count = len(re.findall(r'<img\b', lo)) + len(re.findall(r'background-image\s*:', lo)) + len(re.findall(r'url\(', lo))
    if img_count < 5:
        return True, 'not enough subject-relevant imagery'
    if re.search(r'<img[^>]+src=["\']\s*["\']', h, re.I):
        return True, 'empty image src'
    return False, ''


def _simo_v5_repair_prompt(prompt: str, bad_html: str, reason: str) -> str:
    return f"""
The previous HTML failed Simo North Star quality check: {reason}.
Regenerate from scratch. Do not revise the old layout.
Make the design visibly different from a generic dark hero/card template.
Return one complete HTML document only.

Original request: {prompt}
""".strip()


def _simo_v5_generate_endpoint():
    try:
        data = request.get_json(silent=True) or {}
        prompt = str(data.get('prompt') or data.get('message') or data.get('text') or '').strip()
        kind = str(data.get('kind') or 'website').strip() or 'website'
        if not prompt:
            return jsonify({'ok': False, 'error': 'Missing prompt'}), 400
        client = get_client()
        if not client:
            return jsonify({
                'ok': False,
                'error': 'OPENAI_API_KEY is missing. Simo did not render a generic fallback because North Star requires AI-designed websites.',
                'phase': 'SIMO_NORTHSTAR_V5_AI_DESIGNER_NO_TEMPLATE_FALLBACK'
            }), 500
        model = (os.getenv('SIMO_WEBSITE_MODEL') or os.getenv('OPENAI_MODEL') or OPENAI_MODEL or 'gpt-4o-mini').strip()
        html = ''
        ai_error = ''
        messages = [
            {'role': 'system', 'content': _simo_v5_designer_system_prompt(prompt, kind)},
            {'role': 'user', 'content': prompt},
        ]
        for attempt in range(2):
            try:
                resp = client.chat.completions.create(
                    model=model,
                    messages=messages,
                    temperature=0.92 if attempt == 0 else 0.98,
                    max_tokens=14000,
                )
                html = _simo_v5_extract_html(_simo_v5_extract_text(resp))
            except Exception as err:
                ai_error = str(err)
                break
            bad, reason = _simo_v5_is_bad_html(html, prompt)
            if not bad:
                title = _simo_v5_plain_subject(prompt).title()
                m = re.search(r'<title[^>]*>(.*?)</title>', html, flags=re.I|re.S)
                if m and re.sub(r'\s+', ' ', m.group(1)).strip():
                    title = re.sub(r'\s+', ' ', m.group(1)).strip()[:80]
                return jsonify({
                    'ok': True,
                    'title': title,
                    'html': html,
                    'kind': kind,
                    'subject': _simo_v5_plain_subject(prompt),
                    'phase': 'SIMO_NORTHSTAR_V5_TRUE_AI_DESIGNER_2026_06_22',
                    'source': 'openai_full_page_designer',
                    'model': model,
                })
            messages = [
                {'role': 'system', 'content': _simo_v5_designer_system_prompt(prompt, kind)},
                {'role': 'user', 'content': _simo_v5_repair_prompt(prompt, html, reason)},
            ]
        return jsonify({
            'ok': False,
            'error': 'The AI response was rejected because it still looked generic or incomplete. No fallback template was shown. Try again or use a stronger SIMO_WEBSITE_MODEL such as gpt-4o.',
            'reason': reason if 'reason' in locals() else ai_error,
            'phase': 'SIMO_NORTHSTAR_V5_REJECTED_GENERIC_OUTPUT',
        }), 502
    except Exception as err:
        return jsonify({'ok': False, 'error': str(err), 'phase': 'SIMO_NORTHSTAR_V5_ERROR'}), 500


try:
    app.view_functions['api_simo_website_v3_generate'] = _simo_v5_generate_endpoint
    print('[SIMO NORTH STAR V5] TRUE AI DESIGNER route active. One-template renderer bypassed; no generic fallback output.', flush=True)
except Exception as _simo_v5_route_err:
    print('[SIMO NORTH STAR V5] route override failed: ' + str(_simo_v5_route_err), flush=True)


