def _simo_v8_clean_subject(prompt: str) -> str:
    raw = str(prompt or '').strip()
    raw = re.sub(r'^(please\s+)?(can you\s+|could you\s+|would you\s+|i want\s+|i need\s+)?(make me|build me|create me|design me|generate me|show me|give me|make|build|create|design|generate)\s+', '', raw, flags=re.I)
    raw = re.sub(r'\b(a|an|the|for me|please|editable|ready to publish|publish ready|website|web site|webpage|web page|landing page|homepage|page|site|app|application|dashboard)\b', ' ', raw, flags=re.I)
    return re.sub(r'\s+', ' ', raw).strip(' .,-')[:80] or 'business'

def _simo_v8_title(v: str) -> str:
    return re.sub(r'\s+', ' ', str(v or '').strip()).title()

def _simo_v8_has(s: str, words) -> bool:
    s = (s or '').lower()
    return any(w in s for w in words)

def _simo_v8_img(url: str) -> str:
    return url + ('&' if '?' in url else '?') + 'auto=format&fit=crop&w=1600&q=86'

