def _simo_v8_extract_html(text: str) -> str:
    raw = str(text or '').strip(); raw = re.sub(r'^```(?:html)?\s*', '', raw, flags=re.I).strip(); raw = re.sub(r'```\s*$', '', raw).strip(); low = raw.lower(); i = low.find('<!doctype html');
    if i < 0: i = low.find('<html')
    return raw[i:].strip() if i >= 0 else ''

def _simo_v8_bad(html: str, prompt: str) -> bool:
    l = str(html or '').lower(); subject = _simo_v8_clean_subject(prompt).lower()
    if len(str(html or '')) < 5000 or '<style' not in l or ('<html' not in l and '<!doctype html' not in l): return True
    if any(b in l for b in ['signature offer','visual examples','find your perfect option','a sharper website for','generic template']): return True
    words = [w for w in re.split(r'[^a-z0-9]+', subject) if len(w) > 3]
    return bool(words and sum(1 for w in words if w in l) == 0)

def _simo_v8_ai_prompt(prompt: str, kind: str) -> str:
    subject = _simo_v8_clean_subject(prompt)
    return "Create a complete unique premium ready-to-publish %s for this exact request: %s. Return ONLY full HTML with CSS in style tags. Choose a subject-specific layout, colors, imagery, sections, offers, reviews, FAQ, and contact flow for %s. Use at least 4 relevant images.unsplash.com image URLs. Do not use generic phrases such as visual examples, find your perfect option, signature offer, or a sharper website for. Add data-simo-select attributes to major editable areas." % (kind, prompt, subject)

