def _simo_v45_e(v):
    import html as _html
    return _html.escape(str(v or ''), quote=True)

def _simo_v45_subject(prompt: str) -> str:
    raw = str(prompt or '').strip()
    raw = re.sub(r'\[SIMO_IMAGE_CONTEXT\][\s\S]*$', ' ', raw, flags=re.I)
    raw = re.sub(r'\s+', ' ', raw).strip()
    raw = re.sub(r"^(please\s+)?(can you\s+|could you\s+|would you\s+|i want\s+|i need\s+)?(make me|build me|create me|design me|generate me|show me|make|build|create|design|generate|give me)\s+", "", raw, flags=re.I)
    raw = re.sub(r"\b(a|an|the|for me|please|editable|ready to publish|publish ready|website|web site|webpage|web page|landing page|homepage|page|site)\b", " ", raw, flags=re.I)
    return re.sub(r"\s+", " ", raw).strip(' .,-')[:90] or 'business'

def _simo_v45_kind(subject: str) -> str:
    s = re.sub(r'[^a-z0-9 ]+', ' ', str(subject or '').lower())
    rules = [
        ('hair_salon', 'hair salon|salon|hair stylist|hairstylist|balayage|hair color|haircut|blowout|extensions'),
        ('battery_store', 'battery|batteries|auto battery|marine battery|power tool battery|backup power'),
        ('bible_study', 'bible study|scripture study|ministry|church group|prayer group|sermon|worship'),
        ('hardwood_flooring', 'hardwood flooring|wood flooring|floor refinishing|floor installation|stain samples|sanding'),
        ('fashion_sunglasses', 'sunglasses|eyewear|frames|shades|designer glasses'),
        ('classic_car', 'classic car|collector car|vintage car|muscle car|car showroom'),
        ('stained_glass', 'stained glass|glass repair|lead came|window restoration|church window'),
        ('auto_repair', 'auto repair|mechanic|oil change|brake repair|engine diagnostics|transmission'),
        ('tire_shop', 'tire|tires|wheel alignment|rims|wheels|tire rotation'),
        ('plumbing', 'plumbing|plumber|drain|pipe|water heater|sewer|leak repair'),
        ('real_estate', 'real estate|realtor|homes for sale|property listings|listing search'),
        ('animal_shelter', 'animal shelter|pet adoption|dog rescue|cat rescue|adopt pets'),
        ('fitness', 'fitness|personal trainer|gym|workout|training program|wellness coach'),
        ('camera_store', 'camera|photography gear|lenses|mirrorless|dslr'),
        ('computer_store', 'computer|laptop|desktop|gaming pc|pc repair|monitor'),
        ('education', 'tutor|tutoring|lessons|teacher|school|sat|act'),
        ('ecommerce', 'store|shop|boutique|marketplace|product|products'),
    ]
    for kind, pat in rules:
        if re.search(r'\b(' + pat + r')\b', s):
            return kind
    return 'custom'

