# =========================================================
# SIMO RC3 CHAT SAFETY WRAPPER — keep normal chat from hard-failing on quota
# This does not replace AI chat when the API works. It only turns OpenAI/billing
# failure JSON into a simple local response so the send/Enter path is not dead.
# =========================================================
try:
    _simo_rc3_old_api_chat = app.view_functions.get("api_chat")
    def api_chat_rc3_safe_wrapper():
        try:
            resp = _simo_rc3_old_api_chat() if _simo_rc3_old_api_chat else None
            try:
                data = resp.get_json(silent=True) if hasattr(resp, "get_json") else None
            except Exception:
                data = None
            # If old chat returned a known quota/API failure, return a useful local response instead of a broken UI error.
            raw = json.dumps(data or {}, default=str).lower()
            if data and ("insufficient_quota" in raw or "429" in raw or "exceeded your current quota" in raw):
                payload = request.get_json(silent=True) or {}
                msg = str(payload.get("message") or payload.get("text") or "").strip()
                return jsonify({"ok": True, "reply": "I can see your message. The AI API quota is currently failing, so live AI chat is limited until billing/quota is fixed. Your SIMO app controls are working; website generation will use the protected Website Builder route or its subject-specific backup."})
            return resp
        except Exception as e:
            return jsonify({"ok": True, "reply": "Simo is running, but the AI chat call failed locally: " + str(e)[:180]})
    if _simo_rc3_old_api_chat:
        app.view_functions["api_chat"] = api_chat_rc3_safe_wrapper
        print("[SIMO RC3] chat safety wrapper active", flush=True)
except Exception as _simo_rc3_chat_wrap_err:
    print("[SIMO RC3] chat safety wrapper failed: " + str(_simo_rc3_chat_wrap_err), flush=True)


# =========================================================
# SIMO WEBSITE BUILDER 2.0 RC5 — FINAL AI OWNER OVERRIDE
# This override is appended last on purpose: it becomes the final owner of
# /api/simo-website-v3/generate and /api/simo-website-v3/edit.
# =========================================================
def _simo_rc2_clean_subject(prompt: str) -> str:
    """Resolve the actual website subject before any design/image work begins.

    This must never return placeholders such as "that business" when the request
    already contains an explicit or recently-resolved subject.
    """
    text = str(prompt or "")
    normalized = re.sub(r"\r\n?", "\n", text).strip()

    # RC11/RC13 structured requests intentionally put the resolved subject first.
    # Pull that subject before generic cleanup/truncation can dilute it.
    patterns = [
        r"^\s*build\s+(?:a|an)\s+(?:premium,\s*)?(?:publish-ready\s+)?website\s+for\s+(?:a|an)\s+([^\n.]{3,120})",
        r"^\s*build\s+(?:a|an)\s+website\s+for\s+(?:a|an)\s+([^\n.]{3,120})",
        r"^\s*(?:create|make|design|build)\s+(?:me\s+)?(?:a|an)\s+(?:premium\s+)?website\s+for\s+(?:a|an)\s+([^\n.]{3,120})",
        r"^\s*(?:create|make|design|build)\s+(?:me\s+)?(?:a|an)\s+website\s+(?:for\s+)?([^\n.]{3,120})",
    ]
    for pat in patterns:
        m = re.search(pat, normalized, flags=re.I)
        if m:
            candidate = re.sub(r"\s+", " ", m.group(1)).strip(" .,-—:")
            # Stop before common instruction tails accidentally captured on one line.
            candidate = re.split(
                r"\b(?:with|including|using|make it|make the|that includes|featuring)\b",
                candidate,
                maxsplit=1,
                flags=re.I,
            )[0].strip(" .,-—:")
            if candidate and not re.fullmatch(r"(?:that|this|the)\s+(?:business|idea|company|brand|service|product)", candidate, flags=re.I):
                return candidate[:120].lower()

    # If a literal follow-up plus conversation context reaches the server, resolve it here too.
    context_match = re.search(r"\[SIMO RECENT CONVERSATION CONTEXT\]([\s\S]+)", normalized, flags=re.I)
    if context_match:
        ctx = context_match.group(1)
        simo_lines = re.findall(r"(?im)^\s*Simo:\s*(.+)$", ctx)
        if simo_lines:
            recent = simo_lines[-1]
            context_patterns = [
                r"\b(?:consider\s+)?(?:starting|start|try)\s+(?:an?\s+)?([a-z0-9][a-z0-9&'\/\-\s]{1,80}?\b(?:business|agency|service|store|shop|studio|company|brand|practice|coaching|tutoring))\b",
                r"\bhow\s+about\s+(?:starting\s+)?(?:an?\s+)?([a-z0-9][a-z0-9&'\/\-\s]{1,80}?\b(?:business|agency|service|store|shop|studio|company|brand|practice|coaching|tutoring))\b",
            ]
            for pat in context_patterns:
                m = re.search(pat, recent, flags=re.I)
                if m:
                    candidate = re.sub(r"\s+", " ", m.group(1)).strip(" .,-—:")
                    if candidate:
                        return candidate[:120].lower()

    raw = re.sub(r"\s+", " ", normalized).strip()
    raw = re.sub(
        r"^(please\s+)?(can you\s+|could you\s+|would you\s+|i want\s+|i need\s+|okay\s+|ok\s+)?"
        r"(make me|build me|create me|design me|generate me|show me|make|build|create|design|generate|give me)\s+",
        "",
        raw,
        flags=re.I,
    ).strip()

    # Remove website framing words, but keep meaningful business nouns.
    raw = re.sub(
        r"\b(a|an|the|for me|please|editable|ready to publish|publish ready|premium|publish-ready|"
        r"website|web site|webpage|web page|landing page|homepage|page|site)\b",
        " ",
        raw,
        flags=re.I,
    )

    # A bare referential phrase is not a valid subject.
    raw = re.sub(r"^\s*for\s+", "", raw, flags=re.I)
    raw = re.sub(r"\s+", " ", raw).strip(" .,-—:")

    compound_aliases = {
        "brickpaving": "brick paving",
        "brickpaver": "brick paver",
        "hairsalon": "hair salon",
        "waters bottle": "water bottle",
        "waterbottle": "water bottle",
        "realestate": "real estate",
        "webapp": "web app",
        "print on demand": "print-on-demand",
    }
    lowered = raw.lower()
    for joined, spaced in compound_aliases.items():
        lowered = re.sub(r"\b" + re.escape(joined) + r"\b", spaced, lowered)

    lowered = re.sub(r"\s+", " ", lowered).strip(" .,-—:")
    if re.fullmatch(r"(?:that|this|the)\s+(?:business|idea|company|brand|service|product)", lowered, flags=re.I):
        return "business"
    return lowered[:120] or "business"


def _simo_subject_lock_contract(prompt: str) -> str:
    """Universal semantic lock used by creative brief, HTML generation, and imagery."""
    subject = _simo_rc2_clean_subject(prompt) or "business"
    s = subject.lower()

    if re.search(r"\b(tutor|tutoring|coach|coaching|lesson|teacher|education)\b", s):
        return (
            f"EXACT SUBJECT LOCK: {subject}. "
            "This is an education/tutoring/coaching website. "
            "Use tutoring-specific content and visuals: teacher or coach helping a learner, "
            "video lesson on a laptop, study workspace, notebooks, learning materials, scheduling, "
            "progress, subject expertise, lesson packages, and student outcomes. "
            "FORBIDDEN DRIFT: kitchens, sinks, faucets, plumbing, home repair, generic contractors, "
            "restaurant scenes, unrelated retail products, or generic 'bespoke services' imagery."
        )
    if re.search(r"\b(print[\s-]*on[\s-]*demand|merchandise|custom merch|t-?shirt|hoodie|mug|phone case)\b", s):
        return (
            f"EXACT SUBJECT LOCK: {subject}. "
            "This is a print-on-demand/custom merchandise business. "
            "Use custom shirts, hoodies, mugs, phone cases, product mockups, heat press/printing, "
            "packaging, ecommerce product displays, and branded merchandise. "
            "FORBIDDEN DRIFT: kitchens, sinks, faucets, plumbing, home repair, unrelated consulting, "
            "or generic contractor/service imagery."
        )
    if re.search(r"\b(virtual assistant|administrative assistant|remote assistant)\b", s):
        return (
            f"EXACT SUBJECT LOCK: {subject}. "
            "Use remote-work and virtual-assistant content and visuals: laptop workspace, calendar, "
            "email/inbox management, client calls, task organization, scheduling, and digital workflows. "
            "FORBIDDEN DRIFT: kitchens, plumbing, construction, unrelated products, or generic trades."
        )
    if re.search(r"\b(dropship|e-?commerce|online store)\b", s):
        return (
            f"EXACT SUBJECT LOCK: {subject}. "
            "Use ecommerce/dropshipping content and visuals: curated products, storefront, packages, "
            "shipping/fulfillment, product listings, orders, and customer delivery. "
            "FORBIDDEN DRIFT: kitchens, plumbing, construction, or unrelated service-business scenes."
        )

    return (
        f"EXACT SUBJECT LOCK: {subject}. "
        "Every headline, offer, section, CTA, testimonial, FAQ, and image must unmistakably belong to "
        "this exact subject. Never substitute a generic consulting/service business. "
        "Never use kitchen, faucet, plumbing, contractor, restaurant, or unrelated stock imagery unless "
        "that is actually the requested subject."
    )


def _simo_rc2_title(prompt: str) -> str:
    subject = _simo_rc2_clean_subject(prompt)
    return re.sub(r"\b\w", lambda m: m.group(0).upper(), subject)


def _simo_rc2_kind(prompt: str) -> str:
    s = _simo_rc2_clean_subject(prompt).lower()
    checks = [
        ("salon", r"hair|salon|beauty|stylist|spa|makeup|lashes|nails"),
        ("razor", r"razor|shav|blade|groom"),
        ("studio", r"recording|music studio|audio|producer|mixing|mastering|podcast"),
        ("stained_glass", r"stained glass|glass repair|church window|lead came|restoration glass"),
        ("camera", r"camera|lens|photography gear|mirrorless|dslr"),
        ("church", r"bible|church|ministry|study|prayer|worship"),
        ("restaurant", r"restaurant|cafe|bakery|food|menu|bistro|coffee"),
        ("education", r"tutor|tutoring|coach|coaching|lesson|teacher|education|learning|course"),
        ("service", r"virtual assistant|administrative assistant|remote assistant|consulting|consultant"),
        ("store", r"print[\s-]*on[\s-]*demand|merchandise|custom merch|t-?shirt|hoodie|mug|phone case|dropship|ecommerce|e-commerce|online store"),
        ("store", r"(?:cell\s*phone|mobile|iphone|android|smartphone|phone)\s+(?:case|cases|cover|covers|accessor(?:y|ies))"),
        ("trade", r"plumb|electric|hvac|floor|paint|roof|repair|contractor|tire|auto"),
        ("store", r"store|shop|marketplace|ecommerce|retail|boutique|watch|furniture|computer|monitor"),
        ("app", r"app|dashboard|portal|booking system|web tool|platform")
    ]
    for name, pat in checks:
        if re.search(pat, s):
            return name
    return "custom"


def _simo_rc2_query(prompt: str) -> str:
    subject = _simo_rc2_clean_subject(prompt).lower()
    kind = _simo_rc2_kind(prompt)
    q = {
        "salon": "luxury hair salon interior stylist beauty",
        "razor": "luxury shaving razor grooming black gold",
        "studio": "recording studio mixing console microphone",
        "stained_glass": "stained glass restoration artisan window",
        "camera": "used camera store lenses photography gear",
        "church": "bible study community church warm fellowship",
        "restaurant": subject + " food interior",
        "education": subject + " online lesson teacher student laptop study workspace",
        "service": subject + " professional remote workspace client workflow",
        "trade": subject + " professional service work",
        "store": subject + " product merchandise ecommerce display packaging",
        "app": subject + " dashboard interface"
    }.get(kind, subject + " professional premium")
    return re.sub(r"[^a-z0-9 ,]+", " ", q).strip()


def _simo_rc2_ai_prompt(prompt: str, kind: str) -> str:
    subject = _simo_rc2_clean_subject(prompt)
    query = _simo_rc2_query(prompt)
    diversity_seed = secrets.token_hex(6)
    return f"""
You are SIMO Website Builder, an autonomous premium creative director, business strategist, UX architect, copywriter, art director, and frontend developer.

USER REQUEST: {prompt!r}
DETECTED SUBJECT: {subject!r}
DETECTED TYPE: {kind!r}
IMAGE QUERY THEME: {query!r}
DESIGN DIVERSITY SEED: {diversity_seed!r} (use only to vary creative decisions; never print it)

Return ONLY one complete HTML document starting with <!DOCTYPE html>. No markdown. No notes.

ABSOLUTE NORTH STAR:
Create a premium, beautiful, nearly ready-to-publish website that feels uniquely designed for this exact request. Do not begin from a standard landing-page shell. Do not reuse a familiar SIMO layout with only names, colors, and images changed.

Before writing HTML, silently build a request-specific design brief covering the real audience, business model, user journey, conversion goal, content hierarchy, visual language, imagery plan, and interaction pattern. Then create the page from that brief. Do not output the brief.

STRUCTURAL UNIQUENESS CONTRACT:
- Select a composition that naturally fits this subject: editorial, catalog, immersive story, service proof, product launch, portfolio, local-trust, menu, marketplace, booking, community, dashboard, or another fitting structure.
- Vary navigation treatment, hero composition, section count, section order, grid rhythm, card geometry, typography scale, content density, CTA placement, and footer structure.
- Never force every request through hero + three cards + gallery + reviews + FAQ + contact.
- Do not use the word “Studio” unless the requested organization would naturally use it.
- A second generation of the same prompt must be a genuinely different art direction, not a recolor.

QUALITY RULES:
- Make the page feel like a custom creative director designed it for the subject.
- Infer the business model, audience, offers, proof, images, tone, colors, layout, and CTAs.
- Use one <style> tag with all CSS. No external CSS.
- Use subject-specific content. No placeholders, no lorem ipsum, no "signature offer", no "what visitors care about", no "custom help", no generic fallback language.
- Subject imagery is mandatory when imagery is appropriate. Use multiple subject-specific image treatments and meaningful alt text. Use stable HTTPS image URLs only; never use blank placeholders, unrelated stock imagery, cartoons, or generic office photos. Add graceful CSS fallbacks so the design remains polished if a remote image is unavailable.
- Choose the information architecture from the request instead of following a fixed checklist. Use only sections that genuinely fit; vary section count, order, density, hero structure, card treatment, and CTA path between unrelated requests.
- Pricing, reviews, FAQ, galleries, product grids, booking, menus, portfolios, comparison tables, timelines, maps, dashboards, and lead forms are optional. Include only what fits the exact request.
- Add realistic editable contact examples only when a contact path belongs on the page.
- Forms must be preview-safe and not submit to a real endpoint.
- Add data-simo-section to each major section.
- Add data-simo-editable to headlines, text, images/visual blocks, buttons, cards, pricing, FAQ, reviews, and contact details.

VISUAL DIFFERENTIATION REQUIREMENT:
A hair salon, recording studio, stained glass repair company, used camera marketplace, and razor product page must look like completely different brands, not like cousins.

OUTPUT ONLY THE HTML DOCUMENT.
"""


def _simo_rc2_extract_text(resp) -> str:
    try:
        txt = getattr(resp, "output_text", "")
        if txt:
            return txt
    except Exception:
        pass
    try:
        return resp.choices[0].message.content or ""
    except Exception:
        pass
    try:
        out = []
        for item in getattr(resp, "output", []) or []:
            for c in getattr(item, "content", []) or []:
                v = getattr(c, "text", None)
                if v:
                    out.append(v)
        return "\n".join(out)
    except Exception:
        return ""


def _simo_rc2_extract_html(text: str) -> str:
    raw = str(text or "").strip()
    raw = re.sub(r"^```(?:html)?\s*", "", raw, flags=re.I).strip()
    raw = re.sub(r"\s*```$", "", raw).strip()
    low = raw.lower()
    start = low.find("<!doctype html")
    if start < 0:
        start = low.find("<html")
    if start >= 0:
        raw = raw[start:]
    end = raw.lower().rfind("</html>")
    if end >= 0:
        raw = raw[:end+7]
    return raw.strip()


def _simo_rc2_html_good(html: str, prompt: str) -> bool:
    raw = str(html or "").strip(); low = raw.lower()
    # Premium pages can be concise. Require a complete, styled document with
    # enough substance, but do not reject a valid AI page solely for being
    # under the previous 4,500-character threshold.
    if len(raw) < 2200 or "<html" not in low or "</html>" not in low or "<style" not in low or "<body" not in low:
        return False
    bad = [
        "lorem ipsum", "signature offer", "what visitors care about", "custom help", "starter path",
        "placeholder text", "built around the details visitors care about",
        "what do you want to build today", "simo is online", "builder library", "image upload & analysis",
        "business plans & startups", "stock market & portfolios", "settings & voice", "clear history",
        "chatgpt", "your best friend"
    ]
    if any(x in low for x in bad):
        return False
    # Never allow the SIMO application shell/dashboard to be embedded as a generated website.
    app_shell_hits = sum(1 for x in ["app-shell", "chatmessages", "simo is online", "builder library", "settings & voice", "website & app builder"] if x in low)
    if app_shell_hits >= 2:
        return False
    words = [w for w in re.sub(r"[^a-z0-9 ]+", " ", _simo_rc2_clean_subject(prompt).lower()).split() if len(w) > 3]
    return not words or any(w in low for w in words[:6])


def _simo_rc2_html_quality_reason(html: str, prompt: str) -> str:
    raw = str(html or "").strip(); low = raw.lower()
    missing = []
    if len(raw) < 2200: missing.append(f"response too short ({len(raw)} characters)")
    if "<html" not in low: missing.append("missing <html>")
    if "</html>" not in low: missing.append("missing </html>")
    if "<style" not in low: missing.append("missing embedded CSS")
    if "<body" not in low: missing.append("missing <body>")
    if missing:
        return "; ".join(missing)
    bad = [
        "lorem ipsum", "signature offer", "what visitors care about", "custom help", "starter path",
        "placeholder text", "built around the details visitors care about",
        "what do you want to build today", "simo is online", "builder library", "image upload & analysis",
        "business plans & startups", "stock market & portfolios", "settings & voice", "clear history",
        "chatgpt", "your best friend"
    ]
    hit = next((x for x in bad if x in low), "")
    if hit:
        return "blocked generic/application-shell phrase: " + hit
    app_shell_hits = [x for x in ["app-shell", "chatmessages", "simo is online", "builder library", "settings & voice", "website & app builder"] if x in low]
    if len(app_shell_hits) >= 2:
        return "application shell detected: " + ", ".join(app_shell_hits)
    words = [w for w in re.sub(r"[^a-z0-9 ]+", " ", _simo_rc2_clean_subject(prompt).lower()).split() if len(w) > 3]
    if words and not any(w in low for w in words[:6]):
        return "generated page did not mention the requested subject"
    return "unknown validation failure"


