def _simo_v86_composition_engine(html: str, prompt: str, variant: int = 0) -> str:
    """Universal post-design composition guard for actual browser output."""
    raw = str(html or "").strip()
    if not raw or "</html>" not in raw.lower() or "simo-v86-composition-engine" in raw.lower():
        return raw
