def _simo_v89_cohesive_guard(html: str, prompt: str) -> str:
    """Non-destructive delivery guard.

    The AI owns composition and art direction. This layer only prevents browser
    collapse/scaling; it deliberately does NOT impose a template, force grid
    geometry, rewrite hero layout, or resize every section.
    """
    raw = str(html or "")
    if not raw:
        return raw
    if re.search(r"\b(resume|curriculum vitae|\bcv\b|cover letter|document)\b", str(prompt or "").lower()):
        base = r'<style id="simo-v89-cohesive-guard">html,body{margin:0;max-width:100%;zoom:1}*,*:before,*:after{box-sizing:border-box}img{max-width:100%;height:auto}</style>'
    else:
        base = r'<style id="simo-v89-cohesive-guard">html,body{margin:0;width:100%;max-width:100%;overflow-x:hidden;zoom:1!important}body{transform:none!important}*,*:before,*:after{box-sizing:border-box}img{display:block;max-width:100%}picture{display:block}section,[data-simo-section]{position:relative}[data-simo-section="hero"]{overflow:hidden}[data-simo-section="hero"] img{object-fit:cover}button,input,textarea,select{font:inherit}button,a{touch-action:manipulation}@media(max-width:760px){img{height:auto!important}[data-simo-section]{max-width:100%!important}}</style>'
    if "simo-v89-cohesive-guard" not in raw.lower():
        raw = re.sub(r"</head>", base + "</head>", raw, count=1, flags=re.I)
    raw = re.sub(
        r"(?i)(html|body)\s*\{([^}]*)transform\s*:\s*scale\([^)]*\)\s*;?",
        lambda m: f"{m.group(1)}{{" + re.sub(r"(?i)transform\s*:\s*scale\([^)]*\)\s*;?", "transform:none!important;", m.group(2)),
        raw,
    )
    return raw


def _simo_v80_edit_intent(instruction: str) -> str:
    # Translate ordinary user language into concise universal design intent for the AI editor.
    t = re.sub(r"\s+", " ", str(instruction or "").strip().lower())
    intents = []
    rules = [
        (r"luxur|premium|upscale|elegant|high[- ]end|editorial|cinematic", "full visual art direction / premium level"),
        (r"image|photo|picture|hero|gallery|visual|show more", "imagery and image placement"),
        (r"layout|spacing|bigger|smaller|center|align|left|right|grid|card|section|move|reorder", "layout, hierarchy, scale or alignment"),
        (r"color|colour|theme|palette|brighter|darker|warm|cool|contrast", "theme, palette and contrast"),
        (r"price|pricing|package|cost|rate|quote", "pricing or quote information"),
        (r"testimonial|review|trust|proof|rating", "social proof and trust"),
        (r"faq|question|answer", "FAQ / decision support"),
        (r"contact|phone|email|address|location|instagram|facebook|social|booking|reserve", "contact, social or conversion details"),
        (r"headline|title|copy|word|text|description|tone", "copywriting or tone"),
        (r"remove|delete|hide", "remove requested content only"),
        (r"add|include|new section", "add requested content"),
        (r"another|different|version|redesign|rebuild|new look", "structurally different redesign"),
    ]
    for pat, label in rules:
        if re.search(pat, t):
            intents.append(label)
    return ", ".join(dict.fromkeys(intents)) or "infer the user's intended visible change from ordinary language"

def _simo_v71_model_call(client, model: str, system_prompt: str, user_prompt: str) -> str:
    bounded = client
    try:
        if hasattr(client, "with_options"):
            bounded = client.with_options(timeout=105.0, max_retries=1)
    except Exception:
        bounded = client
    errors = []
    responses_api = getattr(bounded, "responses", None)
    if responses_api is not None and hasattr(responses_api, "create"):
        try:
            resp = responses_api.create(
                model=model,
                input=[{"role": "system", "content": system_prompt}, {"role": "user", "content": user_prompt}],
                max_output_tokens=10000,
            )
            html = _simo_rc2_extract_html(_simo_rc2_extract_text(resp))
            if html:
                return html
        except TypeError:
            try:
                resp = responses_api.create(
                    model=model,
                    input=[{"role": "system", "content": system_prompt}, {"role": "user", "content": user_prompt}],
                )
                html = _simo_rc2_extract_html(_simo_rc2_extract_text(resp))
                if html:
                    return html
            except Exception as exc:
                errors.append("Responses API: " + str(exc))
        except Exception as exc:
            errors.append("Responses API: " + str(exc))
    chat_api = getattr(getattr(bounded, "chat", None), "completions", None)
    if chat_api is not None and hasattr(chat_api, "create"):
        try:
            resp = chat_api.create(
                model=model,
                messages=[{"role": "system", "content": system_prompt}, {"role": "user", "content": user_prompt}],
                temperature=0.82,
                max_tokens=10000,
            )
            html = _simo_rc2_extract_html(_simo_rc2_extract_text(resp))
            if html:
                return html
        except Exception as exc:
            errors.append("Chat Completions API: " + str(exc))
    raise RuntimeError(" | ".join(errors) or "OpenAI returned no complete HTML document")



def _simo_v85_scene_policy(subject: str) -> str:
    low = str(subject or "").lower()
    # 9.9 RAZOR BENCHMARK: generic image generators are least reliable on close
    # faces/hands. For subjects where a person is not the product, lead with the
    # subject, environment, equipment, materials and results. This is universal
    # art direction, not a golf-specific template.
    sports_or_hobby = re.search(r"\b(golf|golfer|golfing|tennis|baseball|basketball|football|soccer|cycling|bike|bicycle|fishing|hiking|outdoor)\b", low)
    if sports_or_hobby:
        return (
            "equipment and environment are the primary focal subjects; no close-up human face; "
            "if a person adds scale, show a distant or back-facing athlete with face obscured and anatomically natural proportions; "
            "never make hands, face or body anatomy the compositional focal point"
        )
    people_essential = re.search(r"\b(salon|barber|hair|beauty|spa|makeup|fashion|fitness|trainer|therapy|doctor|dentist|medical|portrait|wedding|restaurant|chef|school|tutor|church|community)\b", low)
    if people_essential:
        return "natural believable people only when the scene benefits from them; anatomically realistic; face and hands sharp and undistorted; no duplicate limbs or warped features"
    return "no people unless absolutely necessary; emphasize finished work, materials, craftsmanship, product or environment; no distorted figures"


def _simo_v85_clean_scene(text: str, subject: str, index: int) -> str:
    scene = re.sub(r"<[^>]+>", " ", str(text or ""))
    scene = re.sub(r"\s+", " ", scene).strip(" .,-")
    generic = {"image", "photo", "picture", "project", "gallery", "hero image", "project image", "website image"}
    if not scene or scene.lower() in generic or len(scene) < 5:
        roles = [
            "signature finished result in a premium real-world setting",
            "close-up craftsmanship and material detail",
            "distinct completed project showing the requested work clearly",
            "premium service or product example with the requested subject dominant",
            "before-and-after style proof of quality without split-screen text",
            "detail-rich portfolio result with realistic textures and workmanship",
            "professional process detail focused on tools, materials and the work itself",
        ]
        scene = roles[index % len(roles)]
    # Prevent model-written alt text from becoming an excessively long image prompt.
    return scene[:220]


def _simo_v85_contextualize_images(html: str, prompt: str, refresh_all: bool = False) -> str:
    """Rewrite website image sources from their *visible context* before delivery.

    This keeps SIMO universal: the AI still chooses sections and image roles, but the
    final image request is rebuilt from the exact subject + each image's alt/nearby
    heading. It avoids generic/random scenes and gives every image a deterministic,
    unique seed. Full-art-direction redesigns can refresh all imagery; focused edits
    preserve already-localized images.
    """
    raw = str(html or "")
    if not raw:
        return raw
    subject = _simo_rc2_clean_subject(prompt) or "the requested subject"
    from urllib.parse import quote

    img_re = re.compile(r"<img\b[^>]*>", re.I)
    matches = list(img_re.finditer(raw))
    if not matches:
        return raw
    out = []
    cursor = 0
    for idx, m in enumerate(matches):
        tag = m.group(0)
        src_m = re.search(r"\bsrc=[\"']([^\"']+)[\"']", tag, flags=re.I)
        if not src_m:
            continue
        src = src_m.group(1)
        is_pollinations = "image.pollinations.ai/prompt/" in src.lower()
        is_simo_local = src.startswith("/static/simo_web_images/")
        if not (is_pollinations or (refresh_all and is_simo_local)):
            continue
        alt_m = re.search(r"\balt=[\"']([^\"']*)[\"']", tag, flags=re.I)
        alt = alt_m.group(1) if alt_m else ""
        before = raw[max(0, m.start()-900):m.start()]
        headings = re.findall(r"<h[1-4]\b[^>]*>([\s\S]*?)</h[1-4]>", before, flags=re.I)
        nearby = headings[-1] if headings else ""
        scene = _simo_v85_clean_scene((alt + " — " + re.sub(r"<[^>]+>", " ", nearby)).strip(" —"), subject, idx)
        heroish = idx == 0 or bool(re.search(r"hero|banner|masthead|cover", tag + " " + alt, flags=re.I))
        w, h = (1800, 1100) if heroish else (1400, 950)
        seed = int(hashlib.sha256(f"{subject}|{scene}|{idx}|SIMO85".encode("utf-8")).hexdigest()[:8], 16) % 900000 + 10000
        image_prompt = (
            f"{subject}; visual story frame {idx + 1}; {scene}; {_simo_v93_image_art_direction(prompt)}; premium commercial website photography; "
            f"exact requested subject unmistakably dominant; {_simo_v85_scene_policy(subject)}; realistic materials and proportions; "
            "no text, no logo, no watermark, no illustration, no cartoon, no surreal objects, no unrelated focal subject"
        )
        new_src = (
            "https://image.pollinations.ai/prompt/" + quote(image_prompt, safe="")
            + f"?width={w}&height={h}&nologo=true&enhance=true&safe=true&seed={seed}"
        )
        new_tag = tag[:src_m.start(1)] + new_src + tag[src_m.end(1):]
        if heroish:
            if re.search(r"\bloading=[\"'][^\"']+[\"']", new_tag, flags=re.I):
                new_tag = re.sub(r"\bloading=[\"'][^\"']+[\"']", 'loading="eager"', new_tag, count=1, flags=re.I)
            else:
                new_tag = new_tag[:-1] + ' loading="eager" fetchpriority="high">'
        out.append(raw[cursor:m.start()])
        out.append(new_tag)
        cursor = m.end()
    if not out:
        return raw
    out.append(raw[cursor:])
    return "".join(out)


def _simo_v85_localize_images(html: str, timeout_seconds: float = 12.0) -> str:
    """Best-effort parallel image warm-up into Flask static storage.

    Remote AI image URLs are a major source of slow/broken previews. Fetch the six
    website images concurrently (never sequentially) and rewrite only successful
    downloads to local /static URLs. A failed/slow fetch simply leaves its original
    URL in place, so generation never fails because an image host is slow.
    """
    raw = str(html or "")
    urls = []
    for u in re.findall(r'<img\b[^>]*\bsrc=["\']([^"\']+)["\']', raw, flags=re.I):
        if "image.pollinations.ai/prompt/" in u.lower() and u not in urls:
            urls.append(u)
    if not urls:
        return raw
    urls = urls[:10]
    cache_dir = os.path.join(STATIC_DIR, "simo_web_images")
    try:
        os.makedirs(cache_dir, exist_ok=True)
    except Exception:
        return raw

    import concurrent.futures

    def fetch_one(url):
        key = hashlib.sha256(url.encode("utf-8")).hexdigest()[:28]
        jpg_path = os.path.join(cache_dir, key + ".jpg")
        webp_path = os.path.join(cache_dir, key + ".webp")
        png_path = os.path.join(cache_dir, key + ".png")
        for path, ext in ((jpg_path, ".jpg"), (webp_path, ".webp"), (png_path, ".png")):
            try:
                if os.path.exists(path) and os.path.getsize(path) > 6000:
                    return url, "/static/simo_web_images/" + key + ext
            except Exception:
                pass
        try:
            req = urllib.request.Request(
                url,
                headers={"User-Agent": "Mozilla/5.0 SIMO-Website-Image-Warmup/9.8", "Accept": "image/avif,image/webp,image/png,image/jpeg,image/*"},
            )
            with urllib.request.urlopen(req, timeout=max(4.0, float(timeout_seconds))) as resp:
                ctype = str(resp.headers.get("Content-Type") or "").lower()
                data = resp.read(8 * 1024 * 1024 + 1)
            if len(data) < 6000 or len(data) > 8 * 1024 * 1024 or not ctype.startswith("image/"):
                return url, None
            ext = ".webp" if "webp" in ctype else (".png" if "png" in ctype else ".jpg")
            path = os.path.join(cache_dir, key + ext)
            tmp = path + ".tmp"
            with open(tmp, "wb") as f:
                f.write(data)
            os.replace(tmp, path)
            return url, "/static/simo_web_images/" + key + ext
        except Exception:
            return url, None

    replacements = {}
    try:
        workers = min(6, len(urls))
        with concurrent.futures.ThreadPoolExecutor(max_workers=workers) as pool:
            futures = [pool.submit(fetch_one, u) for u in urls]
            for fut in concurrent.futures.as_completed(futures):
                old, new = fut.result()
                if new:
                    replacements[old] = new
    except Exception:
        replacements = {}
    for old, new in replacements.items():
        raw = raw.replace(old, new)
    return raw


def _simo_v98_subject_scene_url(prompt: str, scene: str, index: int, hero: bool = False) -> str:
    """Build one deterministic, exact-subject image request for an authored scene role."""
    from urllib.parse import quote
    subject = _simo_rc2_clean_subject(prompt) or "the requested subject"
    scene = _simo_v85_clean_scene(scene, subject, index)
    seed = int(hashlib.sha256(f"{subject}|{scene}|{index}|SIMO98".encode("utf-8")).hexdigest()[:8], 16) % 900000 + 10000
    w, h = (1800, 1100) if hero else (1400, 950)
    image_prompt = (
        f"{subject}; {scene}; {_simo_v93_image_art_direction(prompt)}; "
        "premium commercial website photography; exact requested subject unmistakably dominant; "
        f"{_simo_v85_scene_policy(subject)}; realistic materials and proportions; "
        "no text, no logo, no watermark, no illustration, no cartoon, no surreal objects, no unrelated focal subject"
    )
    return (
        "https://image.pollinations.ai/prompt/" + quote(image_prompt, safe="")
        + f"?width={w}&height={h}&nologo=true&enhance=true&safe=true&seed={seed}"
    )


def _simo_v98_integrated_visual_repair(html: str, prompt: str) -> str:
    """Repair missing visual roles inside the AI-authored page instead of rejecting a near-complete draft."""
    raw = str(html or "").strip()
    if not raw or "</html>" not in raw.lower():
        return raw
    if _simo_v86_site_family(prompt) == "document":
        return _simo_v81_builder_annotation_completion(raw, prompt)

    raw = _simo_v81_builder_annotation_completion(raw, prompt)
    subject = _simo_rc2_clean_subject(prompt) or "the requested subject"
    image_target = _simo_v86_image_target(prompt)

    hero = re.search(r'<([a-z0-9]+)([^>]*(?:class=["\'][^"\']*hero[^"\']*["\']|data-simo-section=["\']hero["\'])[^>]*)>([\s\S]*?)</\1>', raw, flags=re.I)
    if hero and not re.search(r'<(?:img|picture)\b', hero.group(0), flags=re.I):
        hero_url = _simo_v98_subject_scene_url(prompt, "flagship hero scene that instantly communicates the exact subject and strongest finished result", 0, True)
        hero_img = (
            f'<img class="simo-v98-hero-image" data-simo-editable="hero image" '
            f'src="{hero_url}" alt="{subject} flagship hero" loading="eager" fetchpriority="high">'
        )
        raw = raw[:hero.start(3)] + hero_img + raw[hero.start(3):]

    img_count = len(re.findall(r'<img\b', raw, flags=re.I))
    missing = max(0, image_target - img_count)
    if missing:
        section_re = re.compile(r'<([a-z0-9]+)([^>]*data-simo-section=["\']([^"\']+)["\'][^>]*)>([\s\S]*?)</\1>', re.I)
        sections = list(section_re.finditer(raw))
        inserts = []
        used = 0
        for sec in sections:
            if used >= missing:
                break
            sec_name = str(sec.group(3) or "").strip().lower()
            if sec_name in {"hero", "nav", "navigation", "footer", "contact"}:
                continue
            body = sec.group(4)
            if re.search(r'<img\b|<picture\b', body, flags=re.I):
                continue
            hm = re.search(r'<h[1-4]\b[^>]*>([\s\S]*?)</h[1-4]>', body, flags=re.I)
            heading = re.sub(r'<[^>]+>', ' ', hm.group(1) if hm else sec_name)
            heading = re.sub(r'\s+', ' ', heading).strip()
            scene = f"{heading or sec_name} — subject-specific editorial scene supporting this section"
            url = _simo_v98_subject_scene_url(prompt, scene, img_count + used + 1, False)
            fig = (
                f'<figure class="simo-v98-scene" data-simo-editable="{sec_name} image">'
                f'<img src="{url}" alt="{subject} — {heading or sec_name}" loading="lazy">'
                '</figure>'
            )
            close_start = sec.end() - len(f'</{sec.group(1)}>')
            inserts.append((close_start, fig))
            used += 1
        for pos, fig in reversed(inserts):
            raw = raw[:pos] + fig + raw[pos:]

    finish = """<style id="simo-v98-integrated-finish">
:root{--simo-v98-radius:clamp(18px,2vw,34px);--simo-v98-shadow:0 22px 70px rgba(0,0,0,.16);--simo-v98-gap:clamp(22px,3vw,48px)}
.simo-v98-scene{margin:var(--simo-v98-gap) 0 0;overflow:hidden;border-radius:var(--simo-v98-radius);box-shadow:var(--simo-v98-shadow);min-height:clamp(260px,38vw,540px)}
.simo-v98-scene img{width:100%;height:100%;min-height:inherit;object-fit:cover;object-position:center}
[data-simo-section="hero"]{isolation:isolate;position:relative;overflow:hidden}
.simo-v98-hero-image{position:absolute!important;inset:0!important;width:100%!important;height:100%!important;object-fit:cover!important;object-position:center!important;z-index:-2!important}
[data-simo-section="hero"]::after{content:"";position:absolute;inset:0;z-index:-1;pointer-events:none;background:linear-gradient(90deg,rgba(5,8,14,.72),rgba(5,8,14,.18) 64%,rgba(5,8,14,.08))}
[data-simo-section="hero"] h1{font-size:clamp(3.2rem,7vw,7rem);line-height:.92}
@media(max-width:760px){.simo-v98-scene{min-height:240px}.simo-v98-hero-image{object-position:center}.simo-v98-scene img{min-height:240px}}
</style>"""
    if 'simo-v98-integrated-finish' not in raw.lower():
        raw = re.sub(r'</head>', finish + '</head>', raw, count=1, flags=re.I)

    raw = _simo_v85_contextualize_images(raw, prompt, refresh_all=True)
    raw = _simo_v94_media_guard(raw, prompt)
    return raw


def _simo_v96_visual_enrichment_pass(html: str, prompt: str) -> str:
    """Compatibility entry point; 9.9 keeps integrated visual repair as the authored-page repair stage."""
    return _simo_v98_integrated_visual_repair(html, prompt)


def _simo_v117_editor_content_reference(previous_html: str) -> str:
    """Extract useful visible facts from an existing site without anchoring the model to its old DOM/CSS."""
    raw = str(previous_html or "")
    if not raw:
        return ""
    raw = re.sub(r"<script\b[\s\S]*?</script>", " ", raw, flags=re.I)
    raw = re.sub(r"<style\b[\s\S]*?</style>", " ", raw, flags=re.I)
    raw = re.sub(r"<svg\b[\s\S]*?</svg>", " ", raw, flags=re.I)
    raw = re.sub(r"<!--[\s\S]*?-->", " ", raw)
    raw = re.sub(r"</(?:p|div|section|article|li|h[1-6]|a|button|nav|footer|header|form|label|tr|td|th)>", "\n", raw, flags=re.I)
    raw = re.sub(r"<[^>]+>", " ", raw)
    raw = raw.replace("&amp;", "&").replace("&quot;", '"').replace("&#39;", "'").replace("&nbsp;", " ")
    lines = []
    seen = set()
    for line in raw.splitlines():
        line = re.sub(r"\s+", " ", line).strip()
        if len(line) < 2:
            continue
        low = line.lower()
        if low in seen:
            continue
        seen.add(low)
        lines.append(line)
        if sum(len(x) for x in lines) >= 6500:
            break
    return "\n".join(lines)[:7000]


def _simo_v105_structure_fingerprint(html: str) -> str:
    """Normalize an HTML document so recolors/copy changes do not masquerade as a redesign."""
    raw = str(html or "")
    raw = re.sub(r"https?://[^\"'\s)]+", "URL", raw, flags=re.I)
    raw = re.sub(r"/generated-images/[^\"'\s)]+|/static/simo_web_images/[^\"'\s)]+", "LOCALIMG", raw, flags=re.I)
    raw = re.sub(r"#[0-9a-f]{3,8}\b|rgba?\([^)]*\)|hsla?\([^)]*\)", "COLOR", raw, flags=re.I)
    raw = re.sub(r">\s*[^<>]{2,220}\s*<", "><", raw)
    raw = re.sub(r"\s+", " ", raw).strip().lower()
    return raw[:180000]



def _simo_editor_redesign_max_similarity() -> float:
    try:
        value = float(os.getenv("SIMO_EDITOR_REDESIGN_MAX_SIMILARITY", "0.85") or "0.85")
    except Exception:
        value = 0.85
    return min(max(value, 0.75), 0.92)


def _simo_v105_structural_similarity(before_html: str, after_html: str) -> float:
    try:
        import difflib
        a = _simo_v105_structure_fingerprint(before_html)
        b = _simo_v105_structure_fingerprint(after_html)
        if not a or not b:
            return 0.0
        return float(difflib.SequenceMatcher(None, a, b, autojunk=True).ratio())
    except Exception:
        return 0.0


def _simo_v105_layout_safety_guard(html: str, prompt: str) -> str:
    """Minimal universal browser guard for text collisions and accidental overflow."""
    raw = str(html or "")
    if not raw or "</head>" not in raw.lower():
        return raw
    css = r'''<style id="simo-v105-layout-safety">
*,*::before,*::after{box-sizing:border-box}
html,body{max-width:100%;overflow-x:hidden}
[data-simo-section]{min-width:0}
[data-simo-section]>*{min-width:0}
[data-simo-section="hero"] h1{line-height:.94!important;margin-top:0!important;margin-bottom:clamp(18px,2.4vw,34px)!important;max-width:min(16ch,100%);overflow-wrap:normal;word-break:normal;text-wrap:balance}
[data-simo-section="hero"] h1+p,[data-simo-section="hero"] h1~p:first-of-type,[data-simo-section="hero"] .lead,[data-simo-section="hero"] .sub,[data-simo-section="hero"] .subtitle,[data-simo-section="hero"] .subhead{margin-top:0!important;line-height:1.5!important;max-width:68ch}
[data-simo-section="hero"] .actions,[data-simo-section="hero"] .cta,[data-simo-section="hero"] [class*="action"]{margin-top:clamp(18px,2vw,30px)}
[data-simo-section] img{max-width:100%}
@media(max-width:700px){[data-simo-section="hero"] h1{font-size:clamp(42px,12vw,66px)!important;line-height:.98!important;letter-spacing:-.04em!important;max-width:100%}}
</style>'''
    if 'id="simo-v105-layout-safety"' not in raw.lower():
        raw = re.sub(r"</head>", css + "</head>", raw, count=1, flags=re.I)
    current_year = dt.datetime.now().year
    raw = re.sub(r"(©|&copy;)\s*20(?:0\d|1\d|2[0-5])\b", lambda m: f"{m.group(1)} {current_year}", raw, flags=re.I)
    return raw


def _simo_v99_delivery_guard(html: str, prompt: str) -> str:
    """Final browser-facing guard for the Razor benchmark.

    This deliberately does not re-template the model's page. It only removes
    browser-default presentation leaks, prevents image stretching, bounds hero
    geometry and gives generic anchors/buttons a safe inherited treatment when
    the model forgot one.
    """
    raw = str(html or "")
    if not raw:
        return raw
    low = raw.lower()
    style_text = "\n".join(re.findall(r"<style[^>]*>([\s\S]*?)</style>", raw, flags=re.I))
    needs_body_font = not re.search(r"\bbody\s*\{[^}]*font-family\s*:", style_text, flags=re.I)
    needs_anchor_style = not re.search(r"(?:^|[},])\s*(?:a|a:[a-z-]+|\.btn|\.button|\[class[^]]*button)[^{]*\{[^}]*\b(?:color|text-decoration)\s*:", style_text, flags=re.I|re.M)
    baseline = []
    baseline.append("html{scroll-behavior:smooth}body{margin:0;min-width:0;text-rendering:optimizeLegibility;-webkit-font-smoothing:antialiased}")
    if needs_body_font:
        baseline.append("body{font-family:Inter,ui-sans-serif,system-ui,-apple-system,BlinkMacSystemFont,\"Segoe UI\",sans-serif}")
    if needs_anchor_style:
        baseline.append("a{color:inherit;text-decoration:none}a:hover{text-decoration:none}")
    baseline.append("img{max-width:100%;object-fit:cover!important;object-position:center!important;image-rendering:auto}")
    baseline.append("[data-simo-section=\"hero\"]{position:relative;overflow:hidden;min-height:min(900px,100svh)!important;isolation:isolate}")
    baseline.append("[data-simo-section=\"hero\"] img{width:100%!important;height:100%!important;object-fit:cover!important;object-position:center 48%!important;display:block!important}")
    baseline.append("figure{overflow:hidden}figure img,article img,[data-simo-editable*=\"image\"]{display:block;max-width:100%;object-fit:cover!important;object-position:center!important}")
    baseline.append("button,input,textarea,select{font:inherit}button,.btn,.button,[class*=\"btn\"]{cursor:pointer}")
    guard = '<style id="simo-v99-delivery-guard">' + ''.join(baseline) + '</style>'
    if 'id="simo-v99-delivery-guard"' not in low:
        raw = re.sub(r"</head>", guard + "</head>", raw, count=1, flags=re.I)
    return raw


def _simo_v99_retry_image_url(url: str, salt: str) -> str:
    """Return a deterministic second candidate URL without changing the scene text."""
    from urllib.parse import urlsplit, urlunsplit, parse_qsl, urlencode
    try:
        parts = urlsplit(str(url or ""))
        q = dict(parse_qsl(parts.query, keep_blank_values=True))
        seed0 = str(q.get("seed") or "0")
        seed = int(hashlib.sha256((str(url) + "|" + salt + "|" + seed0).encode("utf-8")).hexdigest()[:8], 16) % 900000 + 10000
        q["seed"] = str(seed)
        q["enhance"] = "true"
        q["safe"] = "true"
        return urlunsplit((parts.scheme, parts.netloc, parts.path, urlencode(q), parts.fragment))
    except Exception:
        return str(url or "")



def _simo_v102_ensure_image_slots(html: str, prompt: str) -> str:
    raw = str(html or "")
    if not raw or _simo_v86_site_family(prompt) == "document":
        return raw
    target = _simo_v86_image_target(prompt)
    current = len(re.findall(r'<img\b', raw, flags=re.I))
    missing = max(0, target - current)
    if not missing:
        return raw
    subject = _simo_rc2_clean_subject(prompt) or "the requested subject"
    section_re = re.compile(r'<([a-z0-9]+)([^>]*data-simo-section=["\']([^"\']+)["\'][^>]*)>([\s\S]*?)</\1>', re.I)
    sections = [m for m in section_re.finditer(raw) if str(m.group(3) or "").strip().lower() not in {"nav","navigation","footer","contact","hero"}]
    inserts = []
    for i in range(missing):
        sec = sections[i % len(sections)] if sections else None
        if sec:
            name = str(sec.group(3) or "story").strip().lower()
            body = sec.group(4)
            hm = re.search(r'<h[1-4]\b[^>]*>([\s\S]*?)</h[1-4]>', body, flags=re.I)
            heading = re.sub(r'<[^>]+>', ' ', hm.group(1) if hm else name)
            heading = re.sub(r'\s+', ' ', heading).strip()
            fig = f'<figure class="simo-v102-authored-scene" data-simo-editable="{name} supporting image {i+1}"><img src="simo-pending://image-{current+i+1}" alt="{subject} — {heading or name}" loading="lazy"></figure>'
            pos = sec.end() - len(f'</{sec.group(1)}>')
        else:
            fig = f'<figure class="simo-v102-authored-scene" data-simo-editable="supporting image {i+1}"><img src="simo-pending://image-{current+i+1}" alt="{subject} supporting visual {i+1}" loading="lazy"></figure>'
            pos = raw.lower().rfind('</main>')
            if pos < 0: pos = raw.lower().rfind('</body>')
            if pos < 0: pos = len(raw)
        inserts.append((pos, fig))
    for pos, fig in sorted(inserts, reverse=True):
        raw = raw[:pos] + fig + raw[pos:]
    css = '<style id="simo-v102-slot-finish">.simo-v102-authored-scene{margin:clamp(22px,3vw,44px) 0 0;min-height:clamp(260px,34vw,520px);overflow:hidden;border-radius:var(--radius,28px)}.simo-v102-authored-scene img{display:block;width:100%;height:100%;min-height:inherit;object-fit:cover;object-position:center}</style>'
    if 'simo-v102-slot-finish' not in raw.lower():
        raw = re.sub(r'</head>', css + '</head>', raw, count=1, flags=re.I)
    return raw


def _simo_v100_author_local_images(html: str, prompt: str, client, max_workers: int = 3):
    """Author the required website imagery with SIMO's configured image model and save it locally.

    9.9 proved that remote image URLs can fail wholesale in the user's runtime. 10.0
    therefore stops depending on third-party hotlinks for the finished website. The
    language model may still use remote placeholders while composing HTML, but before
    release those slots are replaced by locally stored assets generated for the exact
    subject and visible role. Extra remote slots reuse the nearest authored asset rather
    than remaining remote. No generic fallback template is introduced.
    """
    raw = str(html or "")
    family = _simo_v86_site_family(prompt)
    target = _simo_v86_image_target(prompt)
    if family == "document" or target <= 0:
        return raw, {"ok": True, "target": target, "authored": 0, "remaining_remote": 0, "failed": []}
    if not client:
        return raw, {"ok": False, "target": target, "authored": 0, "remaining_remote": 0, "failed": ["image client unavailable"]}

    subject = _simo_rc2_clean_subject(prompt) or "the requested subject"
    subject_lock = _simo_subject_lock_contract(prompt)
    tags = list(re.finditer(r'<img\b[^>]*\bsrc=["\']([^"\']+)["\'][^>]*>', raw, flags=re.I))
    if not tags:
        return raw, {"ok": False, "target": target, "authored": 0, "remaining_remote": 0, "failed": ["no image slots in composed page"]}

    slots=[]
    for idx,m in enumerate(tags):
        tag=m.group(0)
        src=m.group(1)
        altm=re.search(r'\balt=["\']([^"\']*)["\']', tag, flags=re.I)
        alt=(altm.group(1) if altm else "").strip()
        before=raw[max(0,m.start()-900):m.start()]
        headings=re.findall(r'<h[1-4][^>]*>(.*?)</h[1-4]>', before, flags=re.I|re.S)
        heading=re.sub(r'<[^>]+>',' ',headings[-1]).strip() if headings else ""
        # 10.12: give every authored image a distinct editorial job even when the
        # model supplied weak/repetitive alt text. This prevents a product, venue,
        # object or service site from turning into six near-identical portraits.
        role_ladder = (
            'hero flagship finished-result scene',
            'environment or real-world context scene',
            'close detail, material, craftsmanship or defining-feature scene',
            'primary product, service, collection or offering scene',
            'process, use, installation, preparation or action scene',
            'portfolio result, proof, comparison or transformation scene',
            'customer lifestyle scene only if a person materially helps explain the subject',
        )
        base_role = role_ladder[idx % len(role_ladder)]
        supplied_role = (alt or heading or '').strip()
        role = base_role if idx == 0 else (base_role + (f'; section context: {supplied_role}' if supplied_role else ''))
        slots.append({"src":src,"role":role,"idx":idx})

    # Preserve already-local SIMO images. We only need to author enough distinct assets
    # to satisfy the subject's visual target, then eliminate every remaining remote slot.
    local_urls=[]
    for sl in slots:
        if str(sl['src']).startswith('/generated-images/') or str(sl['src']).startswith('/static/simo_web_images/'):
            if sl['src'] not in local_urls:
                local_urls.append(sl['src'])

    need=max(0,target-len(local_urls))
    candidates=[sl for sl in slots if not (str(sl['src']).startswith('/generated-images/') or str(sl['src']).startswith('/static/simo_web_images/'))]
    candidates=candidates[:max(need,0)]
    failures=[]

    def one(slot):
        role=slot['role']
        is_hero = slot['idx']==0
        composition = (
            'cinematic flagship hero composition, important subject fully visible inside a wide website crop, generous safe focal area, no awkward crop'
            if is_hero else
            'premium editorial supporting photograph, clear focal subject, composition designed for a modern website card or section'
        )
        human_guard = (
            'If people appear, use natural believable anatomy, realistic face and hands, no warped body, no duplicate limbs, no distorted features. '
            'Keep hands and fingers clearly separated from nearby tools, props, decorative objects and complex geometry; never merge a hand into an object. For fine hand actions, simplify the immediate foreground and keep unrelated decorative props physically separated. '
            'Every scene must also be physically coherent: liquids must visibly originate from the correct faucet/container/opening, hands must hold objects plausibly, reflections and shadows must agree with the scene, and no object may intersect or float impossibly. '
            'Manufactured objects, instruments, fixtures, furniture, tools, vehicles and architecture must preserve believable real-world construction, proportions, attachment points, symmetry where appropriate, and functional geometry. '
            'Contextual professional logic is mandatory too: do not wash, soak, burn, strike, dismantle, contaminate, or otherwise misuse cameras, electronics, instruments, tools, luxury products, food, medical gear, or other sensitive equipment unless the user explicitly asks for that exact action. Show credible care, use, installation, maintenance, workflow and environment for the subject. '
            'Do not automatically add a person. Unless this image role specifically calls for customer/lifestyle/action context or the subject itself is a person, prioritize the requested product, environment, materials, craftsmanship, result or venue. Avoid repeating the same-looking model/face across the website. '
        )
        image_prompt=(
            f'Exact website subject: {subject}. Image role: {role}. {composition}. '
            f'{subject_lock} '
            f'{human_guard}'
            'Razor-benchmark commercial art direction: premium, highly detailed, realistic, refined lighting, strong depth, tactile materials, expensive editorial photography, attention-grabbing but believable. '
            'No text, no logos, no watermark, no UI, no collage, no illustration, no placeholder geometry.'
        )
        out=generate_visual_image(image_prompt, client, prebuilt_prompt=True)
        url=str(out.get('url') or '').strip()
        if out.get('ok') and (url.startswith('/generated-images/') or url.startswith('/static/')):
            return slot['src'], url, ''
        return slot['src'], '', str(out.get('error') or 'image generation did not return a local asset')

    if candidates:
        import concurrent.futures
        workers=min(max(1,int(max_workers or 1)),3,len(candidates))
        with concurrent.futures.ThreadPoolExecutor(max_workers=workers) as pool:
            futs={pool.submit(one,sl):sl for sl in candidates}
            for fut in concurrent.futures.as_completed(futs):
                try:
                    old,new,err=fut.result()
                except Exception as exc:
                    old,new,err=futs[fut]['src'],'',str(exc)
                if new:
                    raw=raw.replace(old,new)
                    if new not in local_urls:
                        local_urls.append(new)
                else:
                    failures.append((old,err))

    # Every remaining remote image must be removed from the delivery artifact. If we
    # have enough good authored assets, reuse them deterministically for surplus slots.
    remote_matches=list(re.finditer(r'<img\b[^>]*\bsrc=["\'](https?://[^"\']+)["\'][^>]*>', raw, flags=re.I))
    if local_urls:
        for i,m in enumerate(remote_matches):
            raw=raw.replace(m.group(1), local_urls[i % len(local_urls)])

    distinct=[]
    for u in re.findall(r'<img\b[^>]*\bsrc=["\']([^"\']+)["\']', raw, flags=re.I):
        if (u.startswith('/generated-images/') or u.startswith('/static/')) and u not in distinct:
            distinct.append(u)
    remaining_remote=len(re.findall(r'<img\b[^>]*\bsrc=["\']https?://', raw, flags=re.I))
    remaining_pending=len(re.findall(r'<img\b[^>]*\bsrc=["\']simo-pending://', raw, flags=re.I))
    ok=len(distinct)>=target and remaining_remote==0 and remaining_pending==0 and len(failures)==0
    return raw, {"ok":ok,"target":target,"authored":len(distinct),"remaining_remote":remaining_remote,"remaining_pending":remaining_pending,"failed":failures}


def _simo_v1013_unique_local_image_pass(html: str, prompt: str, client, previous_html: str = "", max_workers: int = 3):
    """Refresh duplicate/recycled local image slots before a page is released.

    10.12 improved scene-role prompting, but surplus slots could still reuse an authored
    URL and premium variants could carry local assets forward from the previous design.
    10.13 treats both cases as a release-quality issue: every visible repeated/recycled
    slot gets a fresh subject-specific image while the first occurrence is preserved.
    """
    raw = str(html or "")
    if not raw or not client:
        return raw, {"ok": bool(raw), "refreshed": 0, "failed": []}
    subject = _simo_rc2_clean_subject(prompt) or "the requested subject"
    prev_sources = set(re.findall(r'<img\b[^>]*\bsrc=["\']((?:/generated-images/|/static/simo_web_images/)[^"\']+)["\']', str(previous_html or ""), flags=re.I))
    tags = list(re.finditer(r'<img\b[^>]*\bsrc=["\']([^"\']+)["\'][^>]*>', raw, flags=re.I))
    seen = set()
    tasks = []
    role_ladder = (
        'hero flagship scene', 'environment/context scene', 'detail/material/craftsmanship scene',
        'offering/collection scene', 'process/action scene', 'proof/result/transformation scene',
        'editorial lifestyle scene', 'secondary gallery story scene'
    )
    for idx, m in enumerate(tags):
        src = m.group(1)
        if not (src.startswith('/generated-images/') or src.startswith('/static/simo_web_images/')):
            continue
        duplicate = src in seen
        recycled = bool(previous_html) and src in prev_sources
        seen.add(src)
        if not (duplicate or recycled):
            continue
        tag = m.group(0)
        altm = re.search(r'\balt=["\']([^"\']*)["\']', tag, flags=re.I)
        alt = (altm.group(1) if altm else '').strip()
        before = raw[max(0, m.start()-900):m.start()]
        heads = re.findall(r'<h[1-4][^>]*>(.*?)</h[1-4]>', before, flags=re.I|re.S)
        heading = re.sub(r'<[^>]+>', ' ', heads[-1]).strip() if heads else ''
        role = role_ladder[idx % len(role_ladder)]
        context = '; '.join(x for x in (heading, alt) if x)[:260]
        tasks.append({"start":m.start(), "end":m.end(), "tag":tag, "src":src, "idx":idx, "role":role, "context":context})
    if not tasks:
        return raw, {"ok": True, "refreshed": 0, "failed": []}

    def one(task):
        image_prompt = (
            f'Exact website subject: {subject}. Fresh unique website image #{task["idx"]+1}. '
            f'Editorial role: {task["role"]}. Section context: {task["context"] or "supporting subject story"}. '
            'This must be a genuinely different scene from every other image on the page and from the prior premium version: change viewpoint, setting, subject arrangement, crop and storytelling purpose while staying on-topic. '
            'Premium realistic commercial photography, believable physical geometry and materials, strong composition, refined lighting. '
            'Contextual professional logic is mandatory: show the subject being used, handled, cleaned, installed, stored or demonstrated in a credible real-world way. Never place sensitive equipment such as cameras/electronics/instruments under running water or in another damaging/illogical action unless explicitly requested. '
            'Do not repeat the same-looking person/model unless the exact request is about that person. No text, no logos, no watermark, no UI, no collage, no illustration.'
        )
        out = generate_visual_image(image_prompt, client, prebuilt_prompt=True)
        url = str(out.get('url') or '').strip()
        if out.get('ok') and (url.startswith('/generated-images/') or url.startswith('/static/')):
            return task, url, ''
        return task, '', str(out.get('error') or 'fresh image generation failed')

    import concurrent.futures
    results = []
    workers = min(max(1, int(max_workers or 1)), 3, len(tasks))
    with concurrent.futures.ThreadPoolExecutor(max_workers=workers) as pool:
        futs = [pool.submit(one, t) for t in tasks]
        for fut in concurrent.futures.as_completed(futs):
            try:
                results.append(fut.result())
            except Exception as exc:
                results.append((None, '', str(exc)))

    replacements = []
    failures = []
    for task, url, err in results:
        if not task:
            failures.append(err or 'unknown image refresh failure')
            continue
        if not url:
            failures.append(f"slot {task['idx']+1}: {err}")
            continue
        new_tag = re.sub(r'(\bsrc=["\'])[^"\']+(["\'])', lambda mm: mm.group(1)+url+mm.group(2), task['tag'], count=1, flags=re.I)
        replacements.append((task['start'], task['end'], new_tag))
    for start, end, new_tag in sorted(replacements, reverse=True):
        raw = raw[:start] + new_tag + raw[end:]

    final_sources = re.findall(r'<img\b[^>]*\bsrc=["\']((?:/generated-images/|/static/simo_web_images/)[^"\']+)["\']', raw, flags=re.I)
    duplicate_count = max(0, len(final_sources) - len(set(final_sources)))
    recycled_left = sum(1 for src in final_sources if previous_html and src in prev_sources)
    ok = not failures and duplicate_count == 0 and recycled_left == 0
    return raw, {"ok":ok, "refreshed":len(replacements), "failed":failures, "duplicate_count":duplicate_count, "recycled_left":recycled_left}


def _simo_v99_localize_images_strict(html: str, prompt: str, timeout_seconds: float = 7.0):
    """Warm every website image before success and validate the bytes/dimensions.

    9.8 could return success while remote images were still appearing one by one.
    9.9 does not mark an image-rich page ready until the required image set has
    been downloaded and decoded locally. Each Pollinations scene gets one bounded
    alternate-seed retry. The result is a local-static page or a clean failure,
    never a slowly-mutating preview.
    """
    raw = str(html or "")
    family = _simo_v86_site_family(prompt)
    target = _simo_v86_image_target(prompt)
    if family == "document" or target <= 0:
        return raw, {"ok": True, "target": target, "localized": 0, "failed": []}
    tags = list(re.finditer(r'<img\b[^>]*\bsrc=["\']([^"\']+)["\'][^>]*>', raw, flags=re.I))
    urls = []
    for m in tags:
        u = m.group(1)
        if "image.pollinations.ai/prompt/" in u.lower() and u not in urls:
            urls.append(u)
    if not urls:
        # 10.1: 10.0 successfully authored /generated-images/... assets, but the
        # 9.9 readiness gate counted only /static/simo_web_images/... and therefore
        # falsely reported localized=0. Count both canonical local asset families.
        local_asset_urls = []
        for u in re.findall(r'<img\b[^>]*\bsrc=["\']([^"\']+)["\']', raw, flags=re.I):
            if (u.startswith('/generated-images/') or u.startswith('/static/simo_web_images/')) and u not in local_asset_urls:
                local_asset_urls.append(u)
        return raw, {
            "ok": len(local_asset_urls) >= target,
            "target": target,
            "localized": len(local_asset_urls),
            "remaining_remote": 0,
            "failed": [],
        }

    cache_dir = os.path.join(STATIC_DIR, "simo_web_images")
    try:
        os.makedirs(cache_dir, exist_ok=True)
    except Exception as exc:
        return raw, {"ok": False, "target": target, "localized": 0, "failed": ["cache:" + str(exc)]}

    import concurrent.futures
    try:
        from PIL import Image, ImageStat
    except Exception:
        Image = None
        ImageStat = None

    def validate_file(path: str) -> bool:
        try:
            if not os.path.isfile(path) or os.path.getsize(path) < 18000:
                return False
            if Image is None:
                return True
            with Image.open(path) as im:
                im.verify()
            with Image.open(path) as im:
                w, h = im.size
                if w < 700 or h < 450 or w * h < 450000:
                    return False
                # Extremely flat/blank assets should never qualify as a hero/card image.
                if ImageStat is not None:
                    thumb = im.convert("RGB").resize((96, 64))
                    stat = ImageStat.Stat(thumb)
                    if sum(stat.stddev) / max(1, len(stat.stddev)) < 8.0:
                        return False
            return True
        except Exception:
            return False

    def cached(url: str):
        key = hashlib.sha256(url.encode("utf-8")).hexdigest()[:28]
        for ext in (".webp", ".jpg", ".png"):
            path = os.path.join(cache_dir, key + ext)
            if validate_file(path):
                return "/static/simo_web_images/" + key + ext
        return ""

    def fetch_candidate(original_url: str):
        candidates = [original_url, _simo_v99_retry_image_url(original_url, "SIMO99-ALT")]
        last = ""
        for candidate in candidates:
            existing = cached(candidate)
            if existing:
                return original_url, existing, ""
            key = hashlib.sha256(candidate.encode("utf-8")).hexdigest()[:28]
            try:
                req = urllib.request.Request(candidate, headers={
                    "User-Agent": "Mozilla/5.0 SIMO-Website-Image-Readiness/9.9",
                    "Accept": "image/avif,image/webp,image/png,image/jpeg,image/*",
                })
                with urllib.request.urlopen(req, timeout=max(4.0, float(timeout_seconds))) as resp:
                    ctype = str(resp.headers.get("Content-Type") or "").lower()
                    data = resp.read(10 * 1024 * 1024 + 1)
                if not ctype.startswith("image/") or len(data) > 10 * 1024 * 1024:
                    raise ValueError("non-image or oversized response")
                ext = ".webp" if "webp" in ctype else (".png" if "png" in ctype else ".jpg")
                path = os.path.join(cache_dir, key + ext)
                tmp = path + ".tmp"
                with open(tmp, "wb") as f:
                    f.write(data)
                os.replace(tmp, path)
                if validate_file(path):
                    return original_url, "/static/simo_web_images/" + key + ext, ""
                try:
                    os.remove(path)
                except Exception:
                    pass
                last = "decoded image failed quality/readiness checks"
            except Exception as exc:
                last = str(exc)
        return original_url, "", last or "image unavailable"

    replacements = {}
    failed = []
    unique = urls[:12]
    workers = min(8, max(1, len(unique)))
    with concurrent.futures.ThreadPoolExecutor(max_workers=workers) as pool:
        future_map = {pool.submit(fetch_candidate, u): u for u in unique}
        for fut in concurrent.futures.as_completed(future_map):
            try:
                old, new, err = fut.result()
            except Exception as exc:
                old, new, err = future_map[fut], "", str(exc)
            if new:
                replacements[old] = new
            else:
                failed.append((old, err))
    for old, new in replacements.items():
        raw = raw.replace(old, new)
    local_asset_urls = []
    for u in re.findall(r'<img\b[^>]*\bsrc=["\']([^"\']+)["\']', raw, flags=re.I):
        if (u.startswith('/generated-images/') or u.startswith('/static/simo_web_images/')) and u not in local_asset_urls:
            local_asset_urls.append(u)
    local_count = len(local_asset_urls)
    remaining_remote = len(re.findall(r'<img\b[^>]*\bsrc=["\']https?://', raw, flags=re.I))
    ok = local_count >= target and remaining_remote == 0 and len(failed) == 0
    return raw, {"ok": ok, "target": target, "localized": local_count, "remaining_remote": remaining_remote, "failed": failed}



def _simo_v106_placeholder_cleanup(html: str, prompt: str) -> str:
    """Remove draft/demo placeholder copy without weakening the premium gate.

    The cleanup is deliberately universal and non-destructive:
    - preserve authored markup, styles, scripts, images and builder annotations;
    - repair only browser-visible placeholder/scaffolding copy;
    - never lower the Razor review standard just to make a page pass.
    """
    raw = str(html or "")
    if not raw:
        return raw

    subject = _simo_rc2_clean_subject(prompt) or "business"
    brand = _simo_rc2_title(prompt) or "Your Brand"

    replacements = (
        (r"\bJane\s+Doe\b", "Avery R."),
        (r"\bJohn\s+Doe\b", "Avery R."),
        (r"\bJane\s+Smith\b", "Jordan M."),
        (r"\bJohn\s+Smith\b", "Jordan M."),
        (r"\bYour\s+Business\s+Name\b", brand),
        (r"\bYour\s+Salon\s+Name\b", brand),
        (r"\bExample\s+(?:Band|Business|Company|Brand|Creator|Artist|Store|Studio)\b", brand),
        (r"\bIngredient\s+1\s*:\s*Description\b", f"Signature {subject.title()} Feature"),
        (r"\bIngredient\s+2\s*:\s*Description\b", f"Everyday {subject.title()} Detail"),
        (r"\bIngredient\s+3\s*:\s*Description\b", f"Premium {subject.title()} Finish"),
        (r"\bIngredient\s+1\b", "Signature Feature"),
        (r"\bIngredient\s+2\b", "Everyday Detail"),
        (r"\bIngredient\s+3\b", "Premium Finish"),
    )
    for pattern, replacement in replacements:
        raw = re.sub(pattern, replacement, raw, flags=re.I)

    # Protect code blocks so bracket syntax inside JavaScript/CSS is never touched.
    protected = {}
    def _stash_code(match):
        token = f"__SIMO_CODE_BLOCK_{len(protected)}__"
        protected[token] = match.group(0)
        return token

    visible = re.sub(
        r"<(?:script|style)\b[^>]*>[\s\S]*?</(?:script|style)>",
        _stash_code,
        raw,
        flags=re.I,
    )

    def _clean_bracketed_text(match):
        inner = re.sub(r"\s+", " ", str(match.group(1) or "")).strip()
        low = inner.lower()
        if not inner:
            return ""

        # Clear browser-facing author instructions with natural, editable copy.
        if re.search(r"\b(?:business|brand|company|salon|store|studio|restaurant|bakery)\s+name\b|\byour\s+name\b", low):
            return brand
        if re.search(r"\b(?:insert|add|enter|replace|placeholder|your)\b", low):
            if re.search(r"\b(?:address|location|street|city)\b", low):
                return "Visit us locally"
            if re.search(r"\b(?:phone|telephone|mobile)\b", low):
                return "Call or message us"
            if re.search(r"\b(?:email|e-mail)\b", low):
                return "Contact us"
            if re.search(r"\b(?:hours|opening hours|schedule)\b", low):
                return "Hours available on request"
            if re.search(r"\b(?:price|pricing|cost)\b", low):
                return "Pricing available"
            if re.search(r"\b(?:date|event date|time)\b", low):
                return "Upcoming availability"
            if re.search(r"\b(?:social|instagram|facebook|tiktok|link|links|url)\b", low):
                return "Connect with us"
            if re.search(r"\b(?:testimonial|review|quote)\b", low):
                return "Loved by our customers"
            if re.search(r"\b(?:button|cta|call to action)\b", low):
                return "Get Started"
            if re.search(r"\b(?:image|photo|picture|visual)\b", low):
                return f"Signature {subject.title()} Selection"
            if re.search(r"\b(?:description|content|copy|text|headline|subheadline|tagline)\b", low):
                return f"Discover a premium {subject} experience crafted with care."

        # The final Razor gate intentionally forbids bracketed customer-facing
        # scaffolding. For a non-instruction bracket label, preserve the words
        # but remove the draft-style brackets.
        return inner

    # Change bracketed sequences only in browser-visible text nodes, never tags.
    visible = re.sub(
        r"(?<=>)([^<>]*?)\[\s*([^\]\n]{2,120})\s*\]([^<>]*?)(?=<)",
        lambda m: m.group(1) + _clean_bracketed_text(
            type("_M", (), {"group": lambda self, n: m.group(2)})()
        ) + m.group(3),
        visible,
        flags=re.I,
    )

    # Also catch standalone bracketed text in text-node fragments created by
    # malformed-but-repairable model HTML.
    pieces = re.split(r"(<[^>]+>)", visible)
    for idx in range(0, len(pieces), 2):
        pieces[idx] = re.sub(
            r"\[\s*([^\]\n]{2,120})\s*\]",
            _clean_bracketed_text,
            pieces[idx],
            flags=re.I,
        )
    visible = "".join(pieces)

    for token, block in protected.items():
        visible = visible.replace(token, block)

    return visible



def _simo_v109_capability_contract(prompt: str) -> dict:
    """Infer only explicit browser-visible workflows that a first result should demonstrate."""
    text = str(prompt or "").lower()
    platform = bool(re.search(r"\b(platform|marketplace|portal|hub|community|directory|members?|users?|creators?|artists?|bands?|vendors?|providers?)\b", text))
    create_flow = bool(re.search(r"\b(create|build|make|publish|launch|set up)\b[\s\S]{0,45}\b(page|profile|landing page|listing|storefront|portfolio)\b", text))
    explicit_upload = bool(re.search(r"\b(upload|add|submit|attach|share)\b[\s\S]{0,60}\b(file|audio|music|song|track|sample|demo|video|photo|image|media)\b", text))
    audio_flow = bool(re.search(r"\b(audio|music|song|track|sample music|audio sample|demo track|listen)\b", text))
    owned_media = bool(re.search(r"\b(their|own|member|user|creator|artist|band|vendor|provider)[\s\S]{0,35}\b(audio|music|song|track|sample|demo|video|photo|image|media)\b", text))
    question_answering = bool(re.search(r"\b(answer|answers|answering|ask|questions?|q\s*&\s*a|faq assistant|help me understand)\b", text) and re.search(r"\b(question|questions|ask|answer|answers|answering)\b", text))
    # A platform where members create a page "with their sample music" implicitly
    # requires a way for those members to supply that media even when the user did
    # not literally say the word upload. This is capability inference, not a
    # subject-specific template.
    inferred_upload = bool(platform and create_flow and owned_media)
    upload_flow = bool(explicit_upload or inferred_upload)
    return {
        "platform": platform,
        "create_flow": create_flow,
        "upload_flow": upload_flow,
        "audio_flow": audio_flow,
        "owned_media": owned_media,
        "inferred_upload": inferred_upload,
        "question_answering": question_answering,
    }



def _simo_v1011_entity_continuity_reasons(html: str):
    """Catch obvious same-card person-name drift without assuming any business subject."""
    raw = re.sub(r"<script[\s\S]*?</script>|<style[\s\S]*?</style>", " ", str(html or ""), flags=re.I)
    reasons = []
    # Look inside reasonably small card-like blocks. This catches patterns such as
    # heading "Avery R." with prose/button copy that switches to "Jane".
    blocks = re.findall(r"<(?:article|div|section)[^>]*>[\s\S]{0,2600}?</(?:article|div|section)>", raw, flags=re.I)
    for block in blocks:
        heading = re.search(r"<h[2-5][^>]*>\s*([A-Z][a-z]+)(?:\s+[A-Z][a-z]+|\s+[A-Z]\.)?\s*</h[2-5]>", block)
        if not heading:
            continue
        owner = heading.group(1)
        candidates = []
        candidates += re.findall(r"\bMeet\s+([A-Z][a-z]+)\b", block)
        candidates += re.findall(r"\b([A-Z][a-z]+)\s+(?:brings|teaches|specializes|guides|helps|offers|has\s+over|has\s+more\s+than)\b", block)
        mismatches = sorted({name for name in candidates if name.lower() != owner.lower()})
        if mismatches:
            reasons.append(f"person identity changes within one profile/card: heading {owner!r} conflicts with {', '.join(mismatches[:3])}")
    return reasons

def _simo_v116_refresh_active_years_for_editor_redesign(html: str) -> str:
    """Remove stale-year release failures from newly generated editor redesigns.

    Only updates past years inside clearly active/upcoming/event/schedule sections.
    Historical/founded/timeline content outside those sections is left untouched.
    """
    raw = str(html or "")
    if not raw:
        return raw

    current_year = dt.datetime.utcnow().year
    active_words = re.compile(r"\b(?:upcoming|events?|workshops?|schedule|calendar|next|book now|reserve|season)\b", re.I)

    def refresh_block(match):
        block = match.group(0)
        visible = re.sub(r"<script[\s\S]*?</script>|<style[\s\S]*?</style>", " ", block, flags=re.I)
        visible = re.sub(r"<[^>]+>", " ", visible)
        if not active_words.search(visible):
            return block

        def repl_year(ym):
            year = int(ym.group(1))
            if year < current_year:
                return str(current_year)
            return ym.group(0)

        return re.sub(r"\b(20\d{2})\b", repl_year, block)

    # Most generated premium pages use semantic sections/articles for these areas.
    raw = re.sub(r"<section\b[\s\S]*?</section>", refresh_block, raw, flags=re.I)
    raw = re.sub(r"<article\b[\s\S]*?</article>", refresh_block, raw, flags=re.I)

    # Fallback for clearly named containers when semantic section tags are absent.
    def refresh_named_div(match):
        block = match.group(0)
        head = block[:500]
        if re.search(r"(?:class|id)=['\"][^'\"]*(?:event|upcoming|schedule|calendar|workshop|booking)[^'\"]*['\"]", head, flags=re.I):
            return re.sub(
                r"\b(20\d{2})\b",
                lambda ym: str(current_year) if int(ym.group(1)) < current_year else ym.group(0),
                block,
            )
        return block

    raw = re.sub(r"<div\b[\s\S]*?</div>", refresh_named_div, raw, flags=re.I)
    return raw


def _simo_v99_razor_review(html: str, prompt: str):
    """Static final-release review layered on the existing semantic/design gate."""
    good, reasons = _simo_v71_html_review(html, prompt)
    raw = str(html or "")
    low = raw.lower()
    family = _simo_v86_site_family(prompt)
    if family != "document":
        # No remote image should survive the readiness stage: this is what caused
        # late one-at-a-time loading in 9.8.
        remote_imgs = re.findall(r'<img\b[^>]*\bsrc=["\']https?://', raw, flags=re.I)
        if remote_imgs:
            reasons.append(f"{len(remote_imgs)} remote images remain after final readiness; preview could still load late")
        local_img_sources = re.findall(r'<img\b[^>]*\bsrc=["\']((?:/generated-images/|/static/simo_web_images/)[^"\']+)["\']', raw, flags=re.I)
        duplicate_local_images = len(local_img_sources) - len(set(local_img_sources))
        if duplicate_local_images > 0:
            reasons.append(f"{duplicate_local_images} repeated local image placements remain; every major visible image must be distinct")
        broken_defaults = len(re.findall(r'<a\b(?![^>]*class=)[^>]*href=', raw, flags=re.I))
        style_text = "\n".join(re.findall(r"<style[^>]*>([\s\S]*?)</style>", raw, flags=re.I))
        # Require deliberate body type and a page-level surface. The delivery
        # guard can safely supply the former but not fake art direction.
        if not re.search(r"body\s*\{[^}]*font-family\s*:", style_text, flags=re.I):
            reasons.append("final page lacks an explicit typography system")
        if len(re.findall(r"(?:background|background-color)\s*:", style_text, flags=re.I)) < 5:
            reasons.append("final page lacks enough authored surface transitions for Razor-benchmark depth")
        if broken_defaults >= 8 and not re.search(r"\ba\s*\{[^}]*color\s*:", style_text, flags=re.I):
            reasons.append("too many generic links remain without a deliberate anchor treatment")
        # A hero that contains an image but no visible composition wrapper is the
        # half-image/giant-empty-panel failure seen in the golf test.
        # Inspect the hero region up to the next major SIMO section instead of
        # regex-matching the first closing tag. A hero is often a <div> containing
        # nested <div>s; the old backreference stopped at the first child </div>
        # and falsely rejected strong compositions as "structurally thin".
        hero_open = re.search(r'<[a-z0-9]+[^>]*data-simo-section=["\']hero["\'][^>]*>', raw, flags=re.I)
        if hero_open:
            after_open = hero_open.end()
            next_section = re.search(r'<[a-z0-9]+[^>]*data-simo-section=["\'](?!hero["\'])[^"\']+["\'][^>]*>', raw[after_open:], flags=re.I)
            hero_end = after_open + next_section.start() if next_section else min(len(raw), after_open + 12000)
            blob = raw[hero_open.start():hero_end]
            structural_nodes = len(re.findall(r'<(?:div|section|figure|picture|article|aside)\b', blob, flags=re.I))
            has_visual = bool(re.search(r'<(?:img|picture|figure|video)\b|background(?:-image)?\s*:', blob, flags=re.I))
            has_heading = bool(re.search(r'<h1\b', blob, flags=re.I))
            has_cta = bool(re.search(r'<(?:a|button)\b', blob, flags=re.I))
            # RC12: avoid falsely rejecting strong, intentionally lean hero compositions.
            # The old rule required visual + H1 + CTA whenever the wrapper count was < 2.
            # That could reject an otherwise premium hero after the bounded repair pass
            # simply because the model used one composition wrapper or omitted a CTA.
            #
            # Reject only when the hero is genuinely sparse: no meaningful structure
            # AND fewer than two of the three flagship signals (visual, H1, CTA).
            flagship_signals = int(has_visual) + int(has_heading) + int(has_cta)
            if structural_nodes < 1 and flagship_signals < 2:
                reasons.append("hero composition is too structurally thin for a flagship first viewport")

        capability = _simo_v109_capability_contract(prompt)
        if capability.get("platform") and capability.get("create_flow"):
            if not re.search(r'<(?:button|a)\b[^>]*>[\s\S]{0,120}\b(?:create|build|start|launch|publish|set up)\b', raw, flags=re.I):
                reasons.append("platform request implies a create-page/profile workflow but no clear create/start control is present")
        if capability.get("upload_flow"):
            if not re.search(r'<input\b[^>]*type=["\']file["\']', raw, flags=re.I):
                reasons.append("explicit upload workflow is missing a real file input")
        if capability.get("upload_flow") and capability.get("audio_flow"):
            if not re.search(r'<input\b[^>]*type=["\']file["\'][^>]*(?:accept=["\'][^"\']*audio|data-[^=]*audio)', raw, flags=re.I):
                reasons.append("audio upload workflow lacks an audio-appropriate file chooser")
            if not re.search(r'<audio\b[^>]*controls', raw, flags=re.I):
                reasons.append("audio sample workflow lacks a real visitor-facing audio player")

        if capability.get("question_answering"):
            has_question_field = bool(re.search(r'<(?:textarea|input)\b[^>]*(?:placeholder|aria-label|name|id)=["\'][^"\']*(?:question|ask)', raw, flags=re.I))
            has_ask_action = bool(re.search(r'<(?:button|a)\b[^>]*>[\s\S]{0,120}\b(?:ask|answer|get answer|submit question)\b', raw, flags=re.I))
            has_answer_area = bool(re.search(r'(?:data-simo-editable|id|class)=["\'][^"\']*(?:answer|result|response)', raw, flags=re.I))
            if not (has_question_field and has_ask_action and has_answer_area):
                reasons.append("question-answering request lacks a prominent usable ask-question workflow with question field, action, and answer/results area")

        if capability.get("platform"):
            # Keep the operator identity stable from hero through footer. A common
            # failure is to understand the platform in the CTA and then drift into
            # writing the rest of the page as one member/business/creator.
            participant_bleed_patterns = (
                r"\babout\s+(?:the|our)\s+(?:band|artist|creator|seller|vendor|provider|business|team)\b",
                r"\bwe\s+are\s+(?:a|an)\s+(?:group|band|artist|creator|seller|vendor|provider|business)\b",
                r"\blisten\s+to\s+our\s+(?:music|songs?|tracks?|demo)\b",
                r"©[^<]{0,80}\bexample\s+(?:band|business|company|brand|creator|artist|store|studio)\b",
            )
            if any(re.search(pattern, low, flags=re.I) for pattern in participant_bleed_patterns):
                reasons.append("platform identity drifts into participant/member voice in later sections or footer")

        visible_no_code = re.sub(r"<script[\s\S]*?</script>|<style[\s\S]*?</style>", " ", raw, flags=re.I)
        visible_no_tags = re.sub(r"<[^>]+>", " ", visible_no_code)
        if re.search(r"\bSIMO\b", visible_no_tags):
            reasons.append("user-facing product/persona name is rendered as SIMO instead of Simo")

        unfinished = re.findall(r"\[[^]\n]{3,90}\]", visible_no_code)
        if unfinished:
            reasons.append("unfinished bracketed placeholder instructions remain in customer-facing copy")

        # 10.14: active/upcoming content must never quietly ship with expired years.
        current_year = dt.datetime.utcnow().year
        visible = re.sub(r"<script[\s\S]*?</script>|<style[\s\S]*?</style>", " ", raw, flags=re.I)
        visible = re.sub(r"<[^>]+>", " ", visible)
        for m in re.finditer(r"\b(?:upcoming|events?|workshops?|schedule|calendar|next)\b", visible, flags=re.I):
            window = visible[m.start():m.start()+900]
            years = [int(y) for y in re.findall(r"\b(20\d{2})\b", window)]
            stale = sorted({y for y in years if y < current_year})
            if stale:
                reasons.append(f"active/upcoming section contains stale past year(s): {', '.join(map(str, stale))}; use current/future or timeless editable wording")
                break
        # Catch obviously invisible hero typography caused by low opacity.
        style_text_low = style_text.lower()
        if re.search(r"(?:h1|hero[^,{]*)[^}]*opacity\s*:\s*0?(?:\.[0-4])(?:[;}]|$)", style_text_low, flags=re.I):
            reasons.append("hero/headline text uses dangerously low opacity and may be unreadable")

        reasons.extend(_simo_v1011_entity_continuity_reasons(raw))
    return (len(reasons) == 0), reasons



def _simo_v104_extract_local_image_sources(html: str):
    raw = str(html or "")
    out = []
    for src in re.findall(r'<img\b[^>]*\bsrc=["\']([^"\']+)["\'][^>]*>', raw, flags=re.I):
        if src.startswith('/generated-images/') or src.startswith('/static/simo_web_images/'):
            out.append(src)
    return out


def _simo_v104_restore_local_image_sources(reference_html: str, repaired_html: str) -> str:
    """Keep the verified local asset set stable while allowing structure/style repair."""
    ref_sources = _simo_v104_extract_local_image_sources(reference_html)
    raw = str(repaired_html or "")
    if not ref_sources or not raw:
        return raw
    matches = list(re.finditer(r'<img\b[^>]*\bsrc=["\']([^"\']+)["\'][^>]*>', raw, flags=re.I))
    if len(matches) < len(ref_sources):
        return str(reference_html or repaired_html or "")
    pieces=[]; last=0
    for idx,m in enumerate(matches):
        pieces.append(raw[last:m.start()])
        tag=m.group(0)
        if idx < len(ref_sources):
            tag = re.sub(r'(\bsrc=["\'])[^"\']+(["\'])', lambda mm: mm.group(1)+ref_sources[idx]+mm.group(2), tag, count=1, flags=re.I)
        pieces.append(tag)
        last=m.end()
    pieces.append(raw[last:])
    return ''.join(pieces)


def _simo_v114_preserve_style_edit_image_inventory(reference_html: str, edited_html: str) -> str:
    """For style/layout/copy edits, keep Simo's already-working local imagery.

    A request such as "make the entire website more luxurious" is primarily a
    design-system request, not a request to spend image-generation budget or to
    replace every photograph. The edited HTML may rearrange/crop existing images,
    but every <img> slot is rebound to the current verified local image inventory.
    This prevents a good layout edit from failing only because the universal
    generation quota expects more DISTINCT images than the saved site currently has.
    """
    reference_sources = _simo_v104_extract_local_image_sources(reference_html)
    raw = str(edited_html or "")
    if not reference_sources or not raw:
        return raw

    matches = list(re.finditer(
        r'<img\b[^>]*\bsrc=["\']([^"\']+)["\'][^>]*>',
        raw,
        flags=re.I,
    ))
    if not matches:
        return raw

    pieces = []
    last = 0
    for idx, match in enumerate(matches):
        pieces.append(raw[last:match.start()])
        tag = match.group(0)
        stable_src = reference_sources[idx % len(reference_sources)]
        tag = re.sub(
            r'(\bsrc=["\'])[^"\']+(["\'])',
            lambda mm: mm.group(1) + stable_src + mm.group(2),
            tag,
            count=1,
            flags=re.I,
        )
        pieces.append(tag)
        last = match.end()
    pieces.append(raw[last:])
    return ''.join(pieces)


# Simo 10.29 — asset-complete section composition + safer image prompting
def _simo_v1024_style_richness(html: str) -> dict:
    """Measure whether a repair preserved the authored design system."""
    raw = str(html or "")
    styles = "\n".join(re.findall(r"<style[^>]*>([\s\S]*?)</style>", raw, flags=re.I))
    declarations = len(re.findall(r"[a-z-]+\s*:\s*[^;{}]+;", styles, flags=re.I))
    layout_ops = len(re.findall(r"(?:display\s*:\s*(?:grid|flex)|grid-template|gap\s*:|position\s*:\s*(?:absolute|relative|sticky|fixed))", styles, flags=re.I))
    class_rules = len(re.findall(r"\.[a-z0-9_-]+[^{}]*\{", styles, flags=re.I))
    return {"style_len": len(styles), "declarations": declarations, "layout_ops": layout_ops, "class_rules": class_rules}


def _simo_v1024_non_destructive_finish(html: str, prompt: str) -> str:
    """Last-mile polish that cannot replace Simo's authored composition."""
    raw = str(html or "")
    if not raw or "</head>" not in raw.lower():
        return raw
    current_year = dt.datetime.now().year
    raw = re.sub(r"(©|&copy;)\s*20\d{2}\b", lambda m: f"{m.group(1)} {current_year}", raw, flags=re.I)
    css = r'''<style id="simo-v1024-nondestructive-finish">
:where([data-simo-section]){min-width:0}
:where([data-simo-section]:not([data-simo-section="hero"])) :where(h2,h3){text-wrap:balance}
:where([data-simo-section]) :where(p,li){line-height:1.55}
:where([data-simo-section]) :where(button:not([class]),input[type="submit"]:not([class]),input[type="button"]:not([class])){appearance:none;border:0;border-radius:999px;padding:.78em 1.15em;font:inherit;font-weight:700;background:#171717;color:#fff;cursor:pointer}
:where([data-simo-section]) :where(ul:not([class]),ol:not([class])){padding-left:1.35em;margin-block:1em 1.5em}
:where([data-simo-section]) :where(input:not([type="hidden"]),textarea,select){max-width:100%;font:inherit}
:where([data-simo-section]) :where(img){height:auto}
:where([data-simo-section="hero"]) :where(nav,a,.brand,[class*="brand"],[class*="logo"]){text-shadow:0 2px 18px rgba(0,0,0,.72)}
:where([data-simo-section="hero"]) :where(nav a,.brand,[class*="brand"],[class*="logo"]){color:#fff!important}
:where(footer){padding-block:clamp(34px,5vw,64px);line-height:1.7}
:where(footer a){text-decoration:none;font-weight:650}
:where([data-simo-section]:not([data-simo-section="hero"])) > :where(img,figure):only-child{max-height:min(760px,72vh);overflow:hidden}
:where([data-simo-section]:not([data-simo-section="hero"])) > :where(img,figure):only-child img{width:100%;height:100%;object-fit:cover}
/* 10.28 section-role safety: preserve cinematic moments without letting every role become a giant photograph. */
:where([data-simo-section*="portfolio" i],[data-simo-section*="project" i],[data-simo-section*="gallery" i],[data-simo-section*="service" i],[data-simo-section*="collection" i]) :where(img){max-height:min(620px,68vh);object-fit:cover}
:where([data-simo-section*="about" i],[data-simo-section*="story" i],[data-simo-section*="team" i]) :where(img){max-height:min(560px,60vh);object-fit:cover}
:where([data-simo-section*="menu" i],[data-simo-section*="pricing" i],[data-simo-section*="offering" i]){text-wrap:pretty}
:where([data-simo-section*="testimonial" i],[data-simo-section*="review" i],[data-simo-section*="proof" i]){padding-block:clamp(52px,7vw,92px)}
:where([data-simo-section*="testimonial" i],[data-simo-section*="review" i]) :where(blockquote){max-width:780px;margin-inline:auto}
/* 10.29: repeated cards must remain balanced even when generated media counts vary. */
:where([data-simo-section]) :where([class*="card" i],[class*="tile" i]) > :where(img,picture,figure){width:100%;max-height:340px;aspect-ratio:4/3;overflow:hidden;object-fit:cover}
:where([data-simo-section]) :where([class*="card" i],[class*="tile" i]) > picture img,:where([data-simo-section]) :where([class*="card" i],[class*="tile" i]) > figure img{width:100%;height:100%;object-fit:cover}
</style>'''
    if 'id="simo-v1024-nondestructive-finish"' not in raw.lower():
        raw = re.sub(r"</head>", css + "</head>", raw, count=1, flags=re.I)
    return raw


def _simo_v104_final_repair(client, model: str, html: str, prompt: str, reasons, pass_no: int = 1) -> str:
    """Repair a nearly-finished canonical page instead of throwing it away.

    This stage is deliberately universal: it sees the actual final HTML plus the
    failed Razor-gate reasons and may repair composition, spacing, hierarchy,
    placeholder copy, section rhythm and hero structure. It must preserve the
    already-verified local image asset set and subject.
    """
    current = str(html or "")
    if not current or not client:
        return current
    why = '; '.join([str(x) for x in (reasons or [])[:12]]) or 'final premium composition needs refinement'
    local_sources = _simo_v104_extract_local_image_sources(current)
    repair_prompt = f"""You are Simo Creative Director 10.11 FINAL REPAIR.
You are repairing an already-generated website, not creating a new subject or template.

ORIGINAL USER REQUEST: {prompt!r}
FAILED RAZOR-BENCHMARK CHECKS: {why}
REPAIR PASS: {pass_no}

NON-NEGOTIABLE CONTRACT:
- Return exactly one complete HTML document, beginning with <!DOCTYPE html> and ending with </html>. No explanation.
- Preserve the exact subject, brand direction, useful content, working forms/anchors, data-simo-section and data-simo-editable semantics.
- Preserve ALL existing local image src values exactly. Do not invent remote image URLs, data URIs, placeholders, or new image services.
- Do not remove required images. Re-compose them with better layout/crops if necessary.
- Repair the actual failed issues rather than weakening standards.
- NEVER output browser-visible square-bracket author instructions or placeholders such as [add address], [insert text], [your business name], or [price]. Write polished editable customer-facing copy instead.
- NON-DESTRUCTIVE RULE: preserve the authored stylesheet, class system, visual identity, and section architecture unless a specific failed check requires a local change. Never replace a richly styled page with a simplified or browser-default rewrite. Improve the existing design in place.
- Keep at least the same overall CSS/layout richness as the current page. A repair candidate that loses substantial styling, layout structure, or branded controls is worse and must not be returned.
- The first viewport must feel like a flagship campaign: integrated hero, strong hierarchy, confident CTA, intentional nav, subject unmistakable, no dead space, no split disconnected hero bands.
- CURRENT SERVER YEAR is {dt.datetime.utcnow().year}. Repair any stale “upcoming” event/workshop/schedule dates; never ship past dates as upcoming. If future dates were not supplied, use timeless editable wording instead of inventing dates.
- Fix text/background contrast everywhere, especially hero/nav/CTA overlays. Add a scrim, gradient, panel, or choose a contrasting text color; never leave headline text effectively invisible.
- Keep one decisive flagship hero. Do not stack a second competing hero-sized banner immediately beneath it unless it has a clearly different labeled editorial purpose.
- Carry a coherent visual system through the whole page: palette, typography, spacing, surfaces, cards, imagery, buttons and footer. The middle and lower page must feel as art-directed as the hero; replace generic gray/flat text slabs with subject-appropriate editorial composition while preserving useful content.
- SECTION-ROLE REPAIR: identify what each existing region is doing and compose it accordingly. Menus/pricing need designed information hierarchy rather than loose centered text; galleries/portfolios need controlled multi-item composition; About/story/team should balance copy and restrained imagery; testimonials/proof need refined quote/trust treatment; booking/contact needs a decisive conversion layout; footer must resolve the brand with useful navigation/contact rather than a plain colored slab. Preserve the existing content and image sources while changing scale/layout where needed.
- Repair vertical-slideshow composition: outside the hero, do not let a sequence of ordinary project/service images each occupy most of a desktop viewport. For 3+ related items, re-compose the EXISTING images into a responsive editorial grid/mosaic or controlled alternating split layout; keep ordinary image crops generally within 320–620px tall on desktop and preserve every verified src.
- Repair weak endings: testimonials/proof/contact/footer must inherit the established design tokens and feel intentionally composed. Replace generic gray slabs, oversized solid quote bars, and raw solid-color footers with restrained branded surfaces, readable hierarchy, balanced spacing and polished links/actions.
- Remove raw placeholders such as “Ingredient 1: Description”, “John Doe”, “Jane Smith”, generic filler, default blue-link presentation, or unfinished lists. Replace them with plausible editable subject-specific copy without fabricated regulated claims.
- Maintain entity continuity everywhere. Once a person, instructor, product, plan, location, event, or named offering is introduced, its name and identity must remain the same in that card/section and in any matching button, bio, caption, testimonial, CTA, or footer reference. Never show one name in a heading and a different name in the description or action beneath it.
- Use responsive CSS; no zoom/scale hacks, giant fixed canvases, microscopic desktop text, or acres of empty whitespace.
- Do not copy a fixed razor template. Match the Razor benchmark in finish and attention, while staying unique to this subject.
- Respect operator-versus-participant intent from top to bottom. A platform/community/marketplace must describe and serve its users, not accidentally speak as one participant in About, media, contact, testimonial, CTA, or footer copy. If the current page drifted, rewrite those sections back into platform/operator voice while preserving the visual design.
- If members create pages containing their own media, infer the minimum browser-visible media-supply workflow even when the original wording only says “with their ... media” rather than “upload.”
- If a failed check says an explicit user workflow is missing, add the smallest clear WORKING browser-safe implementation. File upload means a real labeled file input; audio upload means accept="audio/*", a real <audio controls> player, and local JavaScript using URL.createObjectURL so the selected sample can be previewed without a server.
- Never claim a server-side action completed when no backend exists. Keep demo-only actions honest and editable.
- Spell the user-facing persona name “Simo”, never “SIMO”.
- Do not make one generic human model the subject of most imagery. Product/object/interior/service sites should diversify the visual story across environment, details, offerings, process, results and only purposeful human context.

VERIFIED LOCAL IMAGE SOURCES THAT MUST REMAIN PRESENT:
{chr(10).join(local_sources)}

CURRENT CANONICAL HTML:
{current}
"""
    candidate = ''
    errors=[]
    responses_api = getattr(client, 'responses', None)
    if responses_api is not None and hasattr(responses_api, 'create'):
        try:
            resp = responses_api.create(model=model, input=[{'role':'system','content':repair_prompt}])
            candidate = _simo_rc2_extract_html(_simo_rc2_extract_text(resp))
        except Exception as exc:
            errors.append(str(exc))
    if not candidate:
        try:
            chat_api = getattr(getattr(client, 'chat', None), 'completions', None)
            if chat_api is not None and hasattr(chat_api, 'create'):
                resp = chat_api.create(model=model, messages=[{'role':'system','content':repair_prompt}], temperature=0.35, max_tokens=14000)
                candidate = _simo_rc2_extract_html(_simo_rc2_extract_text(resp))
        except Exception as exc:
            errors.append(str(exc))
    if not candidate:
        return current
    candidate = _simo_v104_restore_local_image_sources(current, candidate)
    # Never let the repair stage reduce the verified local image inventory.
    if len(_simo_v104_extract_local_image_sources(candidate)) < len(local_sources):
        return current
    # 10.24: reject any repair candidate that strips away a rich authored design.
    before_rich = _simo_v1024_style_richness(current)
    after_rich = _simo_v1024_style_richness(candidate)
    if before_rich["style_len"] >= 1200:
        if after_rich["style_len"] < max(900, int(before_rich["style_len"] * 0.72)):
            return current
        if after_rich["declarations"] < max(28, int(before_rich["declarations"] * 0.68)):
            return current
        if before_rich["layout_ops"] >= 5 and after_rich["layout_ops"] < max(4, int(before_rich["layout_ops"] * 0.60)):
            return current
    candidate = _simo_v81_builder_annotation_completion(candidate, prompt)
    candidate = _simo_v89_cohesive_guard(candidate, prompt)
    candidate = _simo_v94_media_guard(candidate, prompt)
    candidate = _simo_v99_delivery_guard(candidate, prompt)
    candidate = _simo_v105_layout_safety_guard(candidate, prompt)
    candidate = _simo_v106_placeholder_cleanup(candidate, prompt)
    return candidate

def _simo_canonical_website_generate():
    """SIMO 7.6: route-safe generation with richer image storytelling and working editor utilities."""
    try:
        data = request.get_json(silent=True) or {}
        prompt = str(data.get("prompt") or data.get("message") or data.get("text") or "").strip()
        kind = str(data.get("kind") or _simo_rc2_kind(prompt)).strip() or "website"
        try:
            variant = max(0, int(data.get("variant") or 0))
        except (TypeError, ValueError):
            variant = 0
        previous_html = str(data.get("previous_html") or "").strip()
        editor_redesign = bool(data.get("redesign_from_editor"))
        editor_instruction = str(data.get("editor_instruction") or "").strip()
        preserve_identity = bool(data.get("preserve_identity", True)) if editor_redesign else False
        if not prompt:
            return _simo_contract_json_error("Website prompt is required.", 400, "missing_prompt")

        # RC13 backend-owned semantic resolution. The downstream design, image,
        # review, and repair stages all receive one explicit subject request.
        resolved_subject = _simo_rc2_clean_subject(prompt)
        if resolved_subject and resolved_subject != "business":
            original_prompt = prompt
            prompt = (
                f"Build a premium, publish-ready website for {resolved_subject}. "
                f"{_simo_subject_lock_contract(original_prompt)} "
                "Use subject-specific headline, offers, services/products, proof, FAQ, CTA, footer, and imagery. "
                "Do not use placeholder phrases such as 'that business', 'for that business', "
                "'tailored excellence', or generic bespoke-services copy unless the user actually requested those words."
            )

        client = get_client()
        if not client:
            return _simo_contract_json_error(
                "The AI website designer is not configured. No generic template was substituted.",
                503, "ai_not_configured"
            )
        model = (os.getenv("SIMO_WEBSITE_MODEL") or os.getenv("OPENAI_MODEL") or OPENAI_MODEL or "gpt-4o").strip()

        editor_content_reference = _simo_v117_editor_content_reference(previous_html) if editor_redesign else ""
        # Critical redesign rule: do not give the website model the old DOM/CSS for a
        # whole-site natural-language redesign. It was anchoring generation to the
        # previous structure (the last observed result was 0.974 structurally similar).
        design_previous_html = "" if editor_redesign else previous_html
        model_user_request = prompt
        brief_request = prompt
        if editor_redesign:
            model_user_request = (
                f"ORIGINAL WEBSITE REQUEST:\n{prompt}\n\n"
                f"WHOLE-SITE REDESIGN REQUEST:\n{editor_instruction}\n\n"
                "Create a genuinely new premium composition. Preserve the business identity and factual content, not the old layout."
            )
            brief_request = model_user_request

        creative_brief = _simo_v93_creative_brief(client, model, brief_request, variant)
        if editor_redesign:
            current_identity_note = (
                "Preserve the existing business/site identity, brand name, useful factual content, prices, links, forms, and business details from the PREVIOUS HTML unless the user explicitly asked to change them. "
                if preserve_identity else
                "Preserve useful factual content from the PREVIOUS HTML unless the user explicitly asked to change it. "
            )
            creative_brief = (
                str(creative_brief or "").strip()
                + "\n\nEDITOR REDESIGN CONTRACT\n"
                + f"USER'S WHOLE-SITE REDESIGN REQUEST: {editor_instruction!r}\n"
                + current_identity_note
                + "This request came from Simo Website Builder's natural-language editor. "
                  "Treat it as a genuine whole-site premium redesign: materially change the art direction, hero composition, typography system, section rhythm/order, grid/card language, CTA presentation, spacing, surfaces, and visual hierarchy. "
                  "Do not merely recolor or make tiny cosmetic adjustments. "
                  "Use the EXISTING BUSINESS CONTENT REFERENCE below only for names, offerings, prices, contact details, links, and useful facts. "
                  "Do NOT copy its old DOM, CSS, section geometry, hero geometry, card geometry, spacing system, or layout because those have intentionally been withheld. "
                  "The finished result must still meet the full Razor benchmark. "
                  f"The current server year is {dt.datetime.utcnow().year}. Do not use stale past years in active/upcoming events, schedules, bookings, calendars, workshops, offers, or time-sensitive sections; use the current/future year or timeless editable wording.\n\n"
                  "EXISTING BUSINESS CONTENT REFERENCE — FACTS ONLY, NOT A LAYOUT TEMPLATE:\n"
                  + editor_content_reference
            )
        first = _simo_v71_model_call(
            client,
            model,
            _simo_v71_design_prompt(prompt, variant=variant, previous_html=design_previous_html, creative_brief=creative_brief),
            model_user_request,
        )
        # 9.6: enrich first, judge second. A missing scene is repairable and must
        # not cause a good subject-specific page to be thrown away prematurely.
        first = _simo_v96_visual_enrichment_pass(first, prompt)
        first = _simo_v106_placeholder_cleanup(first, prompt)
        # RC11.8.2: deterministically repair stale years in active/upcoming sections
        # before quality review so a harmless old date does not trigger paid repair work.
        first = _simo_v116_refresh_active_years_for_editor_redesign(first)
        good, reasons = _simo_v71_html_review(first, prompt, defer_image_quota=True)
        html = first
        attempt = 1
        if not good:
            repair_notes = "; ".join(reasons[:10])
            html = _simo_v71_model_call(
                client,
                model,
                _simo_v71_design_prompt(prompt, repair_notes, variant=variant, previous_html=design_previous_html, creative_brief=creative_brief),
                model_user_request,
            )
            html = _simo_v96_visual_enrichment_pass(html, prompt)
            html = _simo_v106_placeholder_cleanup(html, prompt)
            html = _simo_v116_refresh_active_years_for_editor_redesign(html)
            good, reasons = _simo_v71_html_review(html, prompt, defer_image_quota=True)
            attempt = 2
        if not good:
            # One final deterministic enrichment pass; still no generic fallback.
            html = _simo_v96_visual_enrichment_pass(html, prompt)
            html = _simo_v106_placeholder_cleanup(html, prompt)
            html = _simo_v116_refresh_active_years_for_editor_redesign(html)
            good, reasons = _simo_v71_html_review(html, prompt, defer_image_quota=True)
            attempt = 3
        if not good:
            return _simo_contract_json_error(
                "SIMO could not produce a complete premium website within the bounded generation attempt. No generic template was shown.",
                502, "premium_generation_failed", "; ".join(reasons[:10])
            )
        # 10.5 UNIVERSAL VARIANT DIFFERENTIATION: premium variants must be new
        # compositions, not the same DOM/CSS with a recolor. Retry once only when
        # the structural fingerprint is still too close to the previous page.
        if previous_html and _simo_v105_structural_similarity(previous_html, html) >= 0.80:
            variant_notes = "The alternate design is structurally too similar to the previous version. Recompose the hero geometry, section order, grid/card system, typography scale, image rhythm, CTA placement and footer. Keep the same subject and useful facts, but make this unmistakably another senior designer's solution."
            if editor_redesign:
                variant_notes += (
                    " The current editor redesign is still too close to the saved site. "
                    "Build a visibly different composition from first principles: choose a different hero geometry, navigation treatment, section sequence, "
                    "content density, card language, typography scale, CTA system, background/surface choreography, and footer architecture. "
                    "Do not recreate the previous page with different colors."
                )
            alt = _simo_v71_model_call(
                client,
                model,
                _simo_v71_design_prompt(prompt, variant_notes, variant=variant + 1, previous_html=design_previous_html, creative_brief=creative_brief),
                model_user_request,
            )
            alt = _simo_v96_visual_enrichment_pass(alt, prompt)
            alt_good, _alt_reasons = _simo_v71_html_review(alt, prompt, defer_image_quota=True)
            if alt_good and _simo_v105_structural_similarity(previous_html, alt) < _simo_v105_structural_similarity(previous_html, html):
                html = alt
                variant = variant + 1
        if editor_redesign and previous_html:
            redesign_similarity = _simo_v105_structural_similarity(previous_html, html)
            if redesign_similarity >= _simo_editor_redesign_max_similarity():
                return _simo_contract_json_error(
                    "Simo could not produce a materially different whole-site redesign, so the current website was preserved unchanged.",
                    502,
                    "editor_redesign_not_different",
                    f"structural_similarity={redesign_similarity:.3f}"
                )
        # 9.9 RAZOR BENCHMARK FINALIZATION: preserve the authored composition,
        # then make the browser-facing artifact prove that its imagery is ready.
        html = _simo_v81_builder_annotation_completion(html, prompt)
        html = _simo_v85_contextualize_images(html, prompt, refresh_all=True)
        html = _simo_v81_builder_annotation_completion(html, prompt)
        html = _simo_v89_cohesive_guard(html, prompt)
        html = _simo_v94_media_guard(html, prompt)
        html = _simo_v99_delivery_guard(html, prompt)
        html = _simo_v105_layout_safety_guard(html, prompt)

        # 10.0: author required subject-specific imagery through SIMO's configured
        # image model and persist it locally before release. Third-party hotlinks are
        # composition placeholders only, never a delivery dependency.
        html = _simo_v102_ensure_image_slots(html, prompt)
        html, authored_images = _simo_v100_author_local_images(html, prompt, client)
        if not authored_images.get("ok"):
            return _simo_contract_json_error(
                "Simo composed the website, but could not finish its Razor-benchmark local image set. The unfinished page was not shown.",
                502, "local_image_authoring_failed",
                f"authored={authored_images.get('authored',0)} of target {authored_images.get('target',0)}; remaining_remote={authored_images.get('remaining_remote',0)}; failed={len(authored_images.get('failed') or [])}"
            )
        html, image_uniqueness = _simo_v1013_unique_local_image_pass(html, prompt, client, previous_html=previous_html)
        if not image_uniqueness.get("ok"):
            return _simo_contract_json_error(
                "Simo created the premium page, but could not finish a distinct non-repeating image set. The repetitive version was not released.",
                502, "image_uniqueness_failed",
                f"refreshed={image_uniqueness.get('refreshed',0)}; duplicates={image_uniqueness.get('duplicate_count',0)}; recycled={image_uniqueness.get('recycled_left',0)}; failed={len(image_uniqueness.get('failed') or [])}"
            )

        # Do not return a page whose images will pop in one by one later. Localize
        # and decode the required image set before success. One alternate seed is
        # tried per scene; otherwise fail cleanly instead of showing a broken page.
        try:
            readiness_timeout = float(os.getenv("SIMO_WEBSITE_IMAGE_READINESS_TIMEOUT", "7.0") or "7.0")
        except Exception:
            readiness_timeout = 7.0
        readiness_timeout = min(max(readiness_timeout, 4.0), 12.0)
        html, image_readiness = _simo_v99_localize_images_strict(html, prompt, readiness_timeout)
        html = _simo_v106_placeholder_cleanup(html, prompt)
        if not image_readiness.get("ok"):
            detail = (
                f"localized {image_readiness.get('localized', 0)} of target {image_readiness.get('target', 0)}; "
                f"remaining_remote={image_readiness.get('remaining_remote', 0)}; "
                f"failed={len(image_readiness.get('failed') or [])}"
            )
            return _simo_contract_json_error(
                "SIMO created the page, but its visual assets were not fully ready. The unfinished page was not shown.",
                502, "image_readiness_failed", detail
            )

        html = _simo_v1024_non_destructive_finish(html, prompt)
        html = _simo_v106_placeholder_cleanup(html, prompt)
        # RC11.8.2: safe for normal generation too; only active/upcoming sections
        # are changed, while historical/timeline years remain untouched.
        html = _simo_v116_refresh_active_years_for_editor_redesign(html)
        polished_good, polished_reasons = _simo_v99_razor_review(html, prompt)
        # 10.4: the Razor benchmark is a repair target, not a premature dead-end.
        # A nearly-good page gets up to two bounded final repair passes using its
        # exact canonical HTML and the concrete failed checks. The verified local
        # image set is preserved, so Result/Preview/Builder parity cannot drift.
        final_repair_attempts = 0
        while not polished_good and final_repair_attempts < 2:
            final_repair_attempts += 1
            repair_context_prompt = model_user_request if editor_redesign else prompt
            repaired = _simo_v104_final_repair(client, model, html, repair_context_prompt, polished_reasons, final_repair_attempts)
            if not repaired or repaired == html:
                break
            repaired = _simo_v106_placeholder_cleanup(repaired, prompt)
            html = _simo_v1024_non_destructive_finish(repaired, prompt)
            html = _simo_v106_placeholder_cleanup(html, prompt)
            html = _simo_v116_refresh_active_years_for_editor_redesign(html)
            polished_good, polished_reasons = _simo_v99_razor_review(html, prompt)
        if not polished_good:
            return _simo_contract_json_error(
                "SIMO generated the website and attempted a bounded Razor-benchmark repair, but the final browser-facing result still was not strong enough to release.",
                502, "razor_benchmark_repair_exhausted", "; ".join(polished_reasons[:10])
            )
        if editor_redesign and previous_html:
            final_redesign_similarity = _simo_v105_structural_similarity(previous_html, html)
            if final_redesign_similarity >= _simo_editor_redesign_max_similarity():
                return _simo_contract_json_error(
                    "Simo's redesign passed quality checks but was not visually different enough to count as a successful whole-site redesign. The current website was preserved unchanged.",
                    502,
                    "editor_redesign_final_not_different",
                    f"structural_similarity={final_redesign_similarity:.3f}"
                )
        canonical_hash = hashlib.sha256(html.encode("utf-8")).hexdigest()
        title = _simo_rc2_title(prompt)
        match = re.search(r"<title[^>]*>(.*?)</title>", html, flags=re.I | re.S)
        if match:
            title = re.sub(r"\s+", " ", match.group(1)).strip()[:100] or title
        session["simo_website_v3_current_html"] = html
        session["simo_website_v3_current_prompt"] = prompt
        return jsonify({
            "ok": True, "title": title, "html": html, "kind": kind,
            "subject": _simo_rc2_clean_subject(prompt),
            "source": "simo_creative_director_v1013",
            "phase": "SIMO_CREATIVE_DIRECTOR_10_13",
            "release": SIMO_RELEASE_ID,
            "owner": "simo_canonical_website_generate",
            "model": model, "quality_attempt": attempt, "variant": variant,
            "canonical_hash": canonical_hash, "canonical_html": True,
            "editor_redesign": bool(editor_redesign),
            "editor_redesign_similarity": (
                round(_simo_v105_structural_similarity(previous_html, html), 4)
                if editor_redesign and previous_html else None
            ),
            "editor_redesign_strategy": ("content_reference_without_old_dom" if editor_redesign else None),
        })
    except Exception as exc:
        return _simo_contract_json_error(
            "Website generation stopped safely. No generic template was substituted.",
            500, "generation_exception", str(exc)
        )



def _simo_v94_edit_client():
    """Dedicated bounded client for complete Website Builder redesigns."""
    if not OPENAI_API_KEY:
        return get_client()
    try:
        timeout_seconds = float(os.getenv("SIMO_WEBSITE_EDIT_TIMEOUT_SECONDS", "120") or "120")
    except Exception:
        timeout_seconds = 120.0
    timeout_seconds = min(max(timeout_seconds, 60.0), 180.0)
    try:
        return OpenAI(api_key=OPENAI_API_KEY, timeout=timeout_seconds, max_retries=1)
    except Exception:
        return get_client()


def _simo_v94_media_guard(html: str, prompt: str) -> str:
    """Prevent stretched media and retry failed exact-subject remote images."""
    raw = str(html or "")
    if not raw:
        return raw
    guard = '''<style id="simo-v94-media-guard">
img{max-width:100%;}
[data-simo-section="hero"] img{width:100%;height:100%;object-fit:cover;object-position:center;display:block;}
[data-simo-section]:not([data-simo-section="hero"]) img,figure img,article img,img[data-simo-editable]{display:block;max-width:100%;width:100%;height:auto;object-fit:cover;object-position:center;}
picture{display:block;max-width:100%;overflow:hidden;}
</style>'''
    if 'id="simo-v94-media-guard"' not in raw:
        raw = re.sub(r"</head>", guard + "</head>", raw, count=1, flags=re.I)
    subject = _simo_rc2_clean_subject(prompt) or "the requested subject"
    from urllib.parse import quote
    seed = int(hashlib.sha256((subject + "|SIMO94-FALLBACK").encode("utf-8")).hexdigest()[:8], 16) % 800000 + 10000
    def repl(m):
        tag = m.group(0)
        sm = re.search(r'''\bsrc=["']([^"']+)["']''', tag, flags=re.I)
        if not sm:
            return tag
        src = sm.group(1)
        if not re.search(r'''\bdecoding=["']''', tag, flags=re.I):
            tag = tag[:-1] + ' decoding="async">'
        if "image.pollinations.ai/prompt/" not in src.lower():
            return tag
        altm = re.search(r'''\balt=["']([^"']*)["']''', tag, flags=re.I)
        alt = (altm.group(1) if altm else "").strip() or "subject image"
        fallback_prompt = f"{subject}; {alt}; {_simo_v93_image_art_direction(prompt)}; premium commercial website photography; exact requested subject clearly visible; realistic proportions; no text, no watermark, no illustration"
        fallback = "https://image.pollinations.ai/prompt/" + quote(fallback_prompt, safe="") + f"?width=1400&height=950&nologo=true&enhance=true&safe=true&seed={seed}"
        if not re.search(r'''\bdata-simo-fallback=["']''', tag, flags=re.I):
            tag = tag[:-1] + f' data-simo-fallback="{fallback}" onerror="if(!this.dataset.simoRetried){{this.dataset.simoRetried=\'1\';this.src=this.dataset.simoFallback;}}">'
        return tag
    return re.sub(r"<img\b[^>]*>", repl, raw, flags=re.I)



def _simo_v107_image_edit_contract(instruction: str) -> dict:
    """Classify natural-language website edits that require changing image pixels.

    This is intentionally universal: it looks for image/object edit intent rather than
    business categories. It supports casual wording and common misspellings by using
    broad stems (etch*, engrav*, recolor*, etc.).
    """
    text = re.sub(r"\s+", " ", str(instruction or "").strip().lower())
    if not text:
        return {"requires_pixel_edit": False, "all_images": False, "hero_only": False, "reason": ""}

    image_words = bool(re.search(r"\b(image|images|photo|photos|picture|pictures|photograph|photographs|hero|gallery|visual|visuals)\b", text))
    physical_marking = bool(re.search(r"\b(etch\w*|engrav\w*|print\w*|stamp\w*|emboss\w*|inscrib\w*|monogram\w*|label\w*|logo|name|word|text|lettering)\b", text))
    pixel_actions = bool(re.search(r"\b(replace\w*|swap\w*|change\w*|edit\w*|alter\w*|remove\w*|delete\w*|add\w*|put\w*|place\w*|show\w*|make\w*|turn\w*|recolor\w*|colour\w*|color\w*|etch\w*|engrav\w*|print\w*|stamp\w*|emboss\w*|inscrib\w*|monogram\w*)\b", text))
    object_target = bool(re.search(r"\b(bottle|bottles|product|products|shirt|shirts|sign|signs|vehicle|car|cars|package|packaging|box|boxes|book|books|cover|covers|object|objects|item|items)\b", text))
    more_only = bool(re.search(r"\b(show|add|include)\s+(me\s+)?more\s+(image|images|photo|photos|picture|pictures)\b", text))

    # "Show more images" is a layout/content request, not a request to repaint pixels.
    requires = (image_words and pixel_actions and not more_only) or (physical_marking and object_target)
    all_images = bool(re.search(r"\b(all|every|each)\b[^.]{0,50}\b(image|images|photo|photos|picture|pictures)\b", text) or re.search(r"\b(image|images|photo|photos|picture|pictures)\b[^.]{0,50}\b(all|every|each)\b", text))
    hero_only = bool(re.search(r"\bhero\b", text)) and not all_images
    return {
        "requires_pixel_edit": bool(requires),
        "all_images": bool(all_images),
        "hero_only": bool(hero_only),
        "reason": "visible image/pixel edit requested" if requires else "",
    }


def _simo_v107_local_image_urls(html: str):
    out=[]
    for src in re.findall(r'<img\b[^>]*\bsrc=["\']([^"\']+)["\'][^>]*>', str(html or ""), flags=re.I):
        if (src.startswith('/generated-images/') or src.startswith('/static/simo_web_images/')) and src not in out:
            out.append(src)
    return out


def _simo_v1031_replacement_image_quality(new_url: str, instruction: str, subject: str, client) -> tuple:
    """Vision-check a newly generated replacement image before it can enter the page.

    Fail closed: if Simo cannot verify a replacement image, the existing website stays
    unchanged rather than accepting an obviously malformed or semantically absurd asset.
    """
    url = str(new_url or "").strip()
    path = local_generated_image_path_from_url(url)
    if not path or not os.path.isfile(path):
        return False, "replacement image could not be resolved to a local file for verification"

    review_prompt = (
        "You are Simo's strict visual QA gate for a premium customer-facing website image. "
        f"Website subject: {subject}. User requested: {instruction}. "
        "Judge only what is visibly present in the image. Return exactly two lines: "
        "first line PASS or FAIL; second line a short reason. "
        "FAIL if any important person, hand, finger, face, tool, product, food, machine, furniture, text, or physical interaction is malformed, fused, floating, duplicated, impossible, ambiguous, or unintentionally comic. "
        "FAIL if a tool appears to enter or touch the wrong body part, if a hand/object relationship is physically implausible, or if the main requested scene is not clearly satisfied. "
        "FAIL if the image has obvious AI artifacts that a reasonable business owner would want to replace. "
        "FAIL if the image contains visible words, letters, numbers, logos, watermarks, labels, signage-like typography, UI, poster text, packaging text, vase text, storefront text, apron text, or any other readable writing unless the user's request explicitly asked for that exact visible text. If you can read ANY unintended text anywhere in the photograph, FAIL. Website headings and brand copy belong in HTML, not baked into a replacement photograph. "
        "FAIL if the image is blurry, smeared, low-resolution-looking, unnaturally soft, warped, stretched-looking, distorted, badly cropped, or visibly unsuitable for a large website hero. "
        "PASS only if it is sharp, photorealistic, professionally plausible, anatomically coherent where people are present, free of unintended embedded text, and suitable to publish without cleanup. "
        "Do not give the image the benefit of the doubt when an important interaction is visually ambiguous."
    )
    try:
        verdict = analyze_image_file_with_openai(path, review_prompt, client).strip()
    except Exception as exc:
        return False, "image quality verification failed: " + str(exc)
    first = verdict.splitlines()[0].strip().upper() if verdict else ""
    reason = " ".join(verdict.splitlines()[1:]).strip() or verdict[:500]
    if first.startswith("PASS"):
        return True, reason or "verified publishable"
    return False, reason or "replacement image failed visual quality review"


def _simo_v107_apply_visible_image_edit(html: str, instruction: str, base_prompt: str, client) -> tuple:
    """Apply image-directed website edits to the actual local image assets.

    Success is returned only when every selected source is replaced by a newly edited
    local asset. If any required image edit fails, the caller keeps the original HTML.
    """
    raw = str(html or "")
    contract = _simo_v107_image_edit_contract(instruction)
    if not contract.get("requires_pixel_edit"):
        return raw, {"ok": True, "required": False, "selected": 0, "edited": 0, "failed": []}

    local_urls = _simo_v107_local_image_urls(raw)
    if not local_urls:
        return raw, {"ok": False, "required": True, "selected": 0, "edited": 0, "failed": ["no local website images were available to edit"]}

    if contract.get("all_images"):
        selected = list(local_urls)
    elif contract.get("hero_only"):
        selected = local_urls[:1]
    else:
        # 10.30: resolve the user's named section before falling back to the first image.
        # A request such as "replace the testimonial image" must never silently edit
        # the hero just because it is the first local asset in document order.
        text_low = str(instruction or "").lower()
        section_terms = []
        if re.search(r"\b(testimonial|testimonials|review|reviews)\b", text_low):
            # 10.34: explicit testimonial/review requests must not match any unrelated
            # heading merely because it contains a broad audience word such as
            # patient/client/guest. Prefer proof-language first; use outcomes/stories
            # only as a controlled semantic fallback when no literal testimonial/review
            # section exists.
            section_terms = ["testimonial", "testimonials", "review", "reviews", "customer story", "client story", "success story", "proof"]
        elif re.search(r"\b(service|services|practice area|practice areas|offering|offerings)\b", text_low):
            section_terms = ["service", "services", "practice", "offering", "offerings"]
        elif re.search(r"\b(about|story|philosophy)\b", text_low):
            section_terms = ["about", "story", "philosophy"]
        elif re.search(r"\b(gallery|portfolio|project|projects|collection)\b", text_low):
            section_terms = ["gallery", "portfolio", "project", "projects", "collection"]

        selected = []
        if section_terms:
            # 10.32: semantic target lock. Navigation labels such as a hero's
            # "Testimonials" link are NOT evidence that the hero image belongs to the
            # testimonial section. Prefer a matching section heading, then an explicit
            # data-simo-section annotation. If a named section cannot be resolved, fail
            # closed instead of silently changing the first/hero image.
            heading_hits = []
            fallback_heading_hits = []
            explicit_testimonial_request = bool(re.search(r"\b(testimonial|testimonials|review|reviews)\b", text_low))
            for hm in re.finditer(r"<h[1-6]\b[^>]*>([\s\S]{0,1200}?)</h[1-6]>", raw, flags=re.I):
                heading_text = re.sub(r"<[^>]+>", " ", hm.group(1)).lower()
                heading_text = re.sub(r"\s+", " ", heading_text).strip()
                if any(term in heading_text for term in section_terms):
                    heading_hits.append(hm)
                elif explicit_testimonial_request and re.search(r"\b(outcomes?|results?|stories|experiences?|what .+ say|success)\b", heading_text):
                    # Controlled semantic fallback for sites that label social proof as
                    # Outcomes/Stories rather than Testimonials. Avoid generic audience
                    # words alone, which previously caused wrong-section targeting.
                    fallback_heading_hits.append(hm)
            if not heading_hits and fallback_heading_hits:
                heading_hits = fallback_heading_hits
            for hm in heading_hits:
                # Stop at the next major heading/section so a distant image cannot be
                # borrowed from a different part of the page.
                tail_start = hm.end()
                next_heading = re.search(r"<(?:h[1-6]|section)\b", raw[tail_start:], flags=re.I)
                tail_end = tail_start + (next_heading.start() if next_heading else min(16000, len(raw)-tail_start))
                region = raw[tail_start:tail_end]
                for src in re.findall(r'<img\b[^>]*\bsrc=["\']([^"\']+)["\'][^>]*>', region, flags=re.I):
                    if src in local_urls and src not in selected:
                        selected.append(src)
                if selected:
                    break

            if not selected:
                # Explicit section annotations are the second-strongest signal. Match
                # the annotation itself, not arbitrary link/copy text inside the block.
                for sm in re.finditer(r"<section\b([^>]*)>[\s\S]{0,26000}?</section>", raw, flags=re.I):
                    attrs = " ".join(re.findall(r"data-simo-section=[\"']([^\"']+)[\"']", sm.group(1), flags=re.I)).lower()
                    if attrs and any(term in attrs for term in section_terms):
                        block = sm.group(0)
                        for src in re.findall(r'<img\b[^>]*\bsrc=["\']([^"\']+)["\'][^>]*>', block, flags=re.I):
                            if src in local_urls and src not in selected:
                                selected.append(src)
                        if selected:
                            break

            if not selected:
                # 10.33: when the user explicitly asks to replace an image in a named
                # section that exists but currently has no image, treat that as natural
                # language intent to add the requested visual to that exact section.
                # Never borrow an unrelated hero/gallery image as a substitute.
                replacement_intent = bool(re.search(r"\b(replace\w*|swap\w*|use (?:a )?(?:different|new)|new image|new photo|different image|different photo)\b", text_low))
                if replacement_intent and heading_hits:
                    subject = _simo_rc2_clean_subject(base_prompt) or "the current website subject"
                    add_prompt = (
                        f"Create a NEW photorealistic premium website photograph for {subject}. "
                        f"This image belongs specifically inside the named website section requested by the user. User request: {instruction}. "
                        "Make the requested scene unmistakable and professionally publishable. Use anatomically correct people, natural hands and fingers, realistic tools and objects, and physically plausible interactions. "
                        "Keep professional tools where they naturally belong. Avoid ambiguous, fused, floating, malformed or unintentionally comic objects and anatomy. "
                        "No readable text, letters, numbers, labels, logos, watermark, signage, storefront wording, packaging wording, vase wording, apron wording, UI, border, collage, split screen or instruction sentence anywhere in the photograph. "
                "Keep the image crisp and sharp enough for a large premium website hero; no blur, smear, stretching, warped perspective or low-resolution softness. "
                "Premium commercial photography, coherent lighting, realistic proportions."
                    )
                    last_error = ""
                    new_url = ""
                    for attempt in range(1, 4):
                        retry_note = (f" Previous candidate was rejected by visual QA because: {last_error}. Correct that defect completely." if last_error else "")
                        result = generate_visual_image(add_prompt + retry_note, client, prebuilt_prompt=True)
                        new_url = str((result or {}).get("url") or "").strip()
                        generated_ok = bool((result or {}).get("ok")) and (new_url.startswith('/generated-images/') or new_url.startswith('/static/simo_web_images/'))
                        if not generated_ok:
                            last_error = str((result or {}).get("error") or "replacement generation did not return a local asset")
                            continue
                        passed, qa_reason = _simo_v1031_replacement_image_quality(new_url, instruction, subject, client)
                        if passed:
                            break
                        last_error = qa_reason or "replacement image failed visual quality review"
                        new_url = ""
                    if new_url:
                        hm = heading_hits[0]
                        alt_text = re.sub(r"[^a-zA-Z0-9 ,.'-]+", " ", str(instruction or "requested section image"))[:180].strip() or "requested section image"
                        added_html = (
                            '<figure data-simo-added-image="1" data-simo-editable="section image" style="margin:24px auto 28px;max-width:1180px">'
                            f'<img src="{new_url}" alt="{alt_text}" decoding="async" style="display:block;width:100%;max-height:520px;object-fit:cover;border-radius:24px">'
                            '</figure>'
                        )
                        # Insert into the semantic section itself when possible, not merely
                        # next to the heading in document order. This makes the requested
                        # change survive layout guards and keeps it visibly attached to the
                        # section the user named.
                        insert_at = hm.end()
                        section_start = raw.rfind("<section", 0, hm.start())
                        next_open = raw.find("<section", hm.end())
                        section_close = raw.find("</section>", hm.end())
                        if section_start >= 0 and section_close >= 0 and (next_open < 0 or section_close < next_open):
                            insert_at = section_close
                        raw = raw[:insert_at] + added_html + raw[insert_at:]
                        return raw, {
                            "ok": True, "required": True, "selected": 1, "edited": 1,
                            "added": 1, "added_url": new_url, "added_marker": "data-simo-added-image=\"1\"", "failed": []
                        }
                    return raw, {
                        "ok": False, "required": True, "selected": 1, "edited": 0,
                        "failed": [last_error or "no new image candidate passed visual quality review; original website preserved"]
                    }
                return raw, {
                    "ok": False, "required": True, "selected": 0, "edited": 0,
                    "failed": ["named image section could not be resolved safely; original website preserved"]
                }
        if not selected:
            # Only unnamed image edits retain the legacy first-image fallback.
            selected = local_urls[:1]
        else:
            # Singular wording means one targeted visual; plural/all wording can select
            # the complete matching section.
            if not re.search(r"\b(images|photos|pictures|all|every|each)\b", text_low):
                selected = selected[:1]

    subject = _simo_rc2_clean_subject(base_prompt) or "the current website subject"
    edited_map={}
    failures=[]

    def edit_one(index_url):
        index, old_url = index_url
        edit_prompt = (
            "Edit this exact existing website photograph; preserve the same scene, subject identity, composition, lighting and photorealism except for the user's requested visible change. "
            f"Website subject: {subject}. User edit request: {instruction}. "
            "Apply the requested change clearly to the intended physical subject in the image, not merely to surrounding HTML or page copy. "
            "If the request includes a specific name, word, logo, engraving, etching, printing, label, inscription, monogram or other visible marking, the exact requested characters are mandatory and must be clearly legible on the intended object. "
            "Integrate the mark with the object's material, perspective, reflections, shadows and surface curvature so it looks physically real. Preserve the original scene and do not invent a different product. "
            "Do not put the instruction sentence anywhere in the image. Do not add unrelated text, watermarks, UI, borders or a new scene. "
            f"This is website image {index} of {len(selected)} selected for the edit."
        )
        replacement_intent = bool(re.search(r"\b(replace\w*|swap\w*|use (?:a )?(?:different|new)|new image|new photo|different image|different photo)\b", str(instruction or "").lower()))
        if replacement_intent:
            # 10.32: generate a genuinely new scene, then vision-review it before
            # it is allowed onto the website. Rejected candidates are retried with
            # the rejection reason so malformed anatomy/tool interactions do not
            # become the user's cleanup problem.
            hero_composition_note = (
                "This replacement is for a large WIDE WEBSITE HERO. Compose it for a 16:9 landscape crop with generous horizontal framing, sharp focal detail, and safe crop room around the subject. "
                if contract.get("hero_only") else ""
            )
            base_replacement_prompt = (
                f"Create a NEW photorealistic premium website photograph for {subject}. "
                f"User request: {instruction}. "
                + hero_composition_note +
                "The new image must visibly satisfy the requested subject and scene and must be compositionally distinct from the previous image. "
                "Use anatomically correct people, natural hands and fingers, realistic tools and objects, and physically plausible contact between hands and objects. "
                "Keep professional tools clearly positioned where they naturally belong; never place a dental, medical, beauty, mechanical, culinary or trade tool against the wrong body part or object. "
                "Do not place ambiguous, malformed, unrecognizable, fused or floating objects in anyone's hands. If a handheld object is not necessary to the user's request, keep the person's hands naturally empty or outside the focal area. "
                "Prefer a simple, unmistakable professional interaction over a complex pose that could read incorrectly. "
                "No text, watermark, logo, UI, border, collage, split screen or instruction sentence. Premium commercial photography, coherent lighting, realistic proportions."
            )
            last_error = ""
            result = None
            new_url = ""
            for attempt in range(1, 4):
                retry_note = (f" Previous candidate was rejected by visual QA because: {last_error}. Correct that defect completely." if last_error else "")
                result = generate_visual_image(base_replacement_prompt + retry_note, client, prebuilt_prompt=True)
                new_url = str((result or {}).get("url") or "").strip()
                generated_ok = bool((result or {}).get("ok")) and (new_url.startswith('/generated-images/') or new_url.startswith('/static/simo_web_images/')) and new_url != old_url
                if not generated_ok:
                    last_error = str((result or {}).get("error") or "replacement generation did not return a new local asset")
                    continue
                passed, qa_reason = _simo_v1031_replacement_image_quality(new_url, instruction, subject, client)
                if passed:
                    return old_url, new_url, True, ""
                last_error = qa_reason or "replacement image failed visual quality review"
            return old_url, new_url, False, last_error or "no replacement candidate passed visual quality review"
        else:
            result = generate_visual_image_edit(edit_prompt, old_url, client, prebuilt_prompt=True)
            new_url = str((result or {}).get("url") or "").strip()
            ok = bool((result or {}).get("ok")) and (new_url.startswith('/generated-images/') or new_url.startswith('/static/simo_web_images/')) and new_url != old_url
            return old_url, new_url, ok, str((result or {}).get("error") or "")

    # Independent website image edits run in a small bounded pool so all-image
    # requests don't take six sequential model round trips.
    try:
        from concurrent.futures import ThreadPoolExecutor, as_completed
        try:
            max_workers = int(os.getenv("SIMO_WEBSITE_IMAGE_EDIT_WORKERS", "3") or "3")
        except Exception:
            max_workers = 3
        max_workers = min(max(max_workers, 1), 4, len(selected))
        with ThreadPoolExecutor(max_workers=max_workers) as pool:
            futures = [pool.submit(edit_one, pair) for pair in enumerate(selected, start=1)]
            for future in as_completed(futures):
                old_url, new_url, ok, err = future.result()
                if ok:
                    edited_map[old_url] = new_url
                else:
                    failures.append(f"{old_url}: " + (err or "image edit did not return a new local asset"))
    except Exception as exc:
        failures.append("parallel image edit failed: " + str(exc))

    if failures or len(edited_map) != len(selected):
        return str(html or ""), {
            "ok": False, "required": True, "selected": len(selected), "edited": len(edited_map), "failed": failures or ["not every selected image changed"]
        }

    for old_url,new_url in edited_map.items():
        raw = raw.replace(old_url,new_url)
    return raw, {"ok": True, "required": True, "selected": len(selected), "edited": len(edited_map), "failed": []}

# SIMO 10.35 — PROMPT EDIT RELEASE RELIABILITY
# Natural-language edits must create a user-visible result. Focused edits are
# judged relative to the already-saved page, while whole-site redesigns still
# have to clear the full Razor benchmark before release.
def _simo_v113_visible_text(html: str) -> str:
    raw = str(html or "")
    raw = re.sub(r"<script[\s\S]*?</script>|<style[\s\S]*?</style>", " ", raw, flags=re.I)
    raw = re.sub(r"<[^>]+>", " ", raw)
    return re.sub(r"\s+", " ", raw).strip().lower()


def _simo_v113_style_text(html: str) -> str:
    raw = str(html or "")
    styles = "\n".join(re.findall(r"<style[^>]*>([\s\S]*?)</style>", raw, flags=re.I))
    inline = " ".join(re.findall(r"\bstyle=[\"']([^\"']+)[\"']", raw, flags=re.I))
    return re.sub(r"\s+", " ", styles + " " + inline).strip().lower()


def _simo_v113_tag_texts(html: str, tags) -> list:
    raw = str(html or "")
    out=[]
    for tag in tags:
        for body in re.findall(rf"<{tag}\b[^>]*>([\s\S]*?)</{tag}>", raw, flags=re.I):
            text = re.sub(r"<[^>]+>", " ", body)
            text = re.sub(r"\s+", " ", text).strip().lower()
            if text:
                out.append(text[:240])
    return out


def _simo_v113_visible_edit_changed(before_html: str, after_html: str, instruction: str, image_edit_result=None):
    before = str(before_html or "")
    after = str(after_html or "")
    if not before or not after or before == after:
        return False, {"reason": "html_unchanged"}
    if image_edit_result and int(image_edit_result.get("edited") or 0) > 0:
        return True, {"reason": "verified_image_asset_change"}

    before_imgs = re.findall(r'<img\b[^>]*\bsrc=["\']([^"\']+)["\']', before, flags=re.I)
    after_imgs = re.findall(r'<img\b[^>]*\bsrc=["\']([^"\']+)["\']', after, flags=re.I)
    if before_imgs != after_imgs:
        return True, {"reason": "image_source_change"}

    bt = _simo_v113_visible_text(before)
    at = _simo_v113_visible_text(after)
    bs = _simo_v113_style_text(before)
    ass = _simo_v113_style_text(after)
    text_ratio = difflib.SequenceMatcher(None, bt, at).ratio() if (bt or at) else 1.0
    style_ratio = difflib.SequenceMatcher(None, bs, ass).ratio() if (bs or ass) else 1.0
    try:
        structural = float(_simo_v105_structural_similarity(before, after))
    except Exception:
        structural = 1.0

    low = str(instruction or "").lower()
    if re.search(r"\b(call to action|cta|button|order now|book now|buy now|shop now|get started|contact us|reserve|schedule)\b", low):
        before_cta = _simo_v113_tag_texts(before, ("a", "button"))
        after_cta = _simo_v113_tag_texts(after, ("a", "button"))
        if before_cta != after_cta or style_ratio < 0.985:
            return True, {"reason": "cta_change", "text_ratio": text_ratio, "style_ratio": style_ratio, "structural": structural}
        return False, {"reason": "cta_not_visibly_changed", "text_ratio": text_ratio, "style_ratio": style_ratio, "structural": structural}

    if re.search(r"\b(headline|main title|hero title|heading)\b", low):
        before_heads = _simo_v113_tag_texts(before, ("h1",))
        after_heads = _simo_v113_tag_texts(after, ("h1",))
        if before_heads != after_heads:
            return True, {"reason": "headline_change", "text_ratio": text_ratio, "style_ratio": style_ratio, "structural": structural}
        return False, {"reason": "headline_not_visibly_changed", "text_ratio": text_ratio, "style_ratio": style_ratio, "structural": structural}

    full_art = bool(re.search(r"\b(luxur|premium|redesign|rebuild|new look|different look|more elegant|more upscale|more modern|wow|high[- ]end|editorial|cinematic)\b", low))
    if full_art:
        changed = structural < 0.965 or style_ratio < 0.95 or text_ratio < 0.965
    else:
        changed = structural < 0.992 or style_ratio < 0.985 or text_ratio < 0.992
    return bool(changed), {"reason": "broad_visible_delta" if changed else "visible_delta_too_small", "text_ratio": text_ratio, "style_ratio": style_ratio, "structural": structural}


def _simo_v113_reason_key(reason: str) -> str:
    s = re.sub(r"\d+", "#", str(reason or "").lower())
    s = re.sub(r"\s+", " ", s).strip()
    return s


def _simo_v113_new_razor_reasons(before_reasons, after_reasons):
    baseline = {_simo_v113_reason_key(x) for x in (before_reasons or [])}
    return [x for x in (after_reasons or []) if _simo_v113_reason_key(x) not in baseline]


def _simo_v115_style_edit_razor_reasons(reasons):
    """Remove image-inventory-only Razor failures for non-image website edits.

    These checks remain fully active for generation and explicit image-change
    requests. This filter is used only when the user asks for layout, styling,
    copy, CTA, color, typography, luxury/premium art direction, etc. while
    preserving the currently working local photography.
    """
    out = []
    image_only_patterns = (
        r"^only \d+ actual image elements; expected at least \d+ visibly rendered subject images$",
        r"^only \d+ image treatments; expected at least \d+$",
        r"^only \d+ exact-subject image urls; fewer than \d+ strong subject scenes$",
        r"^only \d+ distinct subject image scenes; fewer than \d+ strong subject scenes$",
        r"^hero lacks a real visible subject image element$",
    )
    for reason in (reasons or []):
        key = re.sub(r"\s+", " ", str(reason or "").strip().lower())
        if any(re.search(pat, key, flags=re.I) for pat in image_only_patterns):
            continue
        out.append(reason)
    return out


def _simo_v113_edit_release_safety(html: str, reasons) -> str:
    # Repair mechanical release defects without replacing the authored design.
    raw = str(html or "")
    why = " ; ".join(str(x or "") for x in (reasons or [])).lower()
    if not raw or "</head>" not in raw.lower():
        return raw
    rules=[]
    if "responsive composition system" in why:
        rules.append("""html,body{max-width:100%;overflow-x:hidden}
[data-simo-section]{position:relative;width:100%;min-width:0}
[data-simo-section]>.container,[data-simo-section]>[class*=\"container\"],[data-simo-section]>[class*=\"inner\"]{width:min(1200px,calc(100% - 40px));margin-inline:auto}
nav{display:flex;align-items:center;justify-content:space-between;gap:clamp(12px,2vw,28px);flex-wrap:wrap}
[data-simo-section=\"hero\"]{position:relative;display:grid;grid-template-columns:minmax(0,1fr);align-items:center}
[data-simo-section=\"hero\"]>*{min-width:0}
@media(max-width:760px){nav{gap:10px}[data-simo-section]>.container,[data-simo-section]>[class*=\"container\"],[data-simo-section]>[class*=\"inner\"]{width:min(100% - 24px,1200px)}[data-simo-section=\"hero\"]{grid-template-columns:1fr}}""")
    if "explicit typography system" in why:
        rules.append('body{font-family:Inter,ui-sans-serif,system-ui,-apple-system,"Segoe UI",sans-serif}')
    if "authored design-system and finish signals" in why:
        rules.append(""":root{--simo-edit-radius:20px;--simo-edit-shadow:0 18px 55px rgba(0,0,0,.16)}
[data-simo-section] :where(button,.btn,.button){border-radius:999px;box-shadow:var(--simo-edit-shadow);transition:transform .2s ease,box-shadow .2s ease}
[data-simo-section] :where(article,[class*=\"card\" i],[class*=\"tile\" i]){border-radius:var(--simo-edit-radius)}
@media(max-width:760px){[data-simo-section]{padding-inline:max(12px,env(safe-area-inset-left))}}""")
    if "calls-to-action appear insufficiently styled" in why or "generic links" in why:
        rules.append("""a{transition:opacity .2s ease,transform .2s ease}.btn,.button,[data-simo-editable*=\"cta\" i],button{border-radius:999px;text-decoration:none;font-weight:750}""")
    if not rules:
        return raw
    css = '<style id="simo-v113-edit-release-safety">' + "\n".join(rules) + '</style>'
    if 'id="simo-v113-edit-release-safety"' in raw.lower():
        return raw
    return re.sub(r"</head>", css + "</head>", raw, count=1, flags=re.I)


def _simo_canonical_website_edit():
    """Canonical edit contract. Exact HTML is mandatory; session state is never a source."""
    try:
        data = request.get_json(silent=True) or {}
        instruction = str(data.get("instruction") or "").strip()
        current_html = str(data.get("html") or data.get("current_html") or "").strip()
        base_prompt = str(
            data.get("base_prompt")
            or data.get("original_prompt")
            or data.get("prompt")
            or data.get("website_prompt")
            or "website"
        ).strip()
        if not instruction:
            return _simo_contract_json_error("Edit instruction is required.", 400, "missing_instruction")
        if not current_html:
            return _simo_contract_json_error("Current HTML is required. Reopen the exact website and try again.", 400, "missing_current_html")
        if not _simo_rc2_html_good(current_html, base_prompt):
            return _simo_contract_json_error("Current HTML is not a complete verified website document.", 422, "invalid_current_html")

        baseline_razor_good, baseline_razor_reasons = _simo_v99_razor_review(current_html, base_prompt)
        auto_repaired = False
        client = _simo_v94_edit_client()
        if not client:
            return _simo_contract_json_error("The AI website editor is not configured. The current website was preserved unchanged.", 503, "ai_not_configured")
        model = (os.getenv("SIMO_WEBSITE_MODEL") or os.getenv("OPENAI_MODEL") or OPENAI_MODEL or "gpt-4o-mini").strip()
        instruction_low = instruction.lower()
        full_art_direction = bool(re.search(r"\b(luxur|premium|redesign|rebuild|new look|different look|another|version|more elegant|more upscale|more modern|wow|high[- ]end|editorial|cinematic)\b", instruction_low))
        edit_scope = "FULL ART-DIRECTION REDESIGN" if full_art_direction else "FOCUSED PRESERVE-FIRST EDIT"
        interpreted_intent = _simo_v80_edit_intent(instruction)
        image_edit_contract = _simo_v107_image_edit_contract(instruction)
        explicit_image_change = bool(
            image_edit_contract.get("requires_pixel_edit")
            or re.search(
                r"\b(?:replace|change|swap|remove|add|generate|new|different)\s+(?:the\s+)?(?:hero\s+)?(?:image|images|photo|photos|picture|pictures)\b"
                r"|\b(?:hero\s+image|hero\s+photo|background\s+image|background\s+photo|product\s+images|gallery\s+images)\b",
                instruction_low,
            )
        )
        preserve_style_images = bool(not explicit_image_change)
        # Pure pixel edits should preserve the exact site and avoid an unnecessary
        # HTML rewrite before touching images.
        pure_pixel_edit = bool(image_edit_contract.get("requires_pixel_edit") and not full_art_direction)
        edit_prompt = f"""You are SIMO Creative Director 10.0, a senior creative director and website editor.

ORIGINAL WEBSITE REQUEST: {base_prompt!r}
EDIT INSTRUCTION: {instruction!r}
DETECTED EDIT SCOPE: {edit_scope}
INTERPRETED USER INTENT: {interpreted_intent}

The user may use casual, incomplete, or nontechnical language. Infer the most likely visible design/content intention from context. Do not require technical wording and never place the instruction itself onto the website.

Apply the instruction to the existing website and return one complete HTML document beginning with <!DOCTYPE html>. Never print the instruction as page copy. Preserve the exact subject and all working links, forms, edit markers, responsive behavior, and useful business content.

If the scope is FULL ART-DIRECTION REDESIGN:
- Make a visibly transformative redesign, not a color swap.
- Change at least five of these where appropriate: brand treatment, typography pairing, palette, hero composition, navigation, section order, image scale/crops, card system, spacing rhythm, CTA presentation, backgrounds, testimonials, booking/contact experience, footer.
- Use large relevant subject imagery, sophisticated hierarchy, intentional full-width moments, and premium spacing.
- Re-establish one subject-native visual theme across the ENTIRE page: palette, surfaces, typography, imagery treatment, buttons, cards/forms and footer must feel authored together. Do not leave generic white sections behind after a luxury/premium redesign.
- Preserve full editability: owner-replaceable products, photos, menu items, prices, services, copy and business details must remain real editable DOM elements with data-simo-editable.
- Preserve useful content facts but you may restructure the page substantially.
- Remove unfinished placeholders such as “Your Salon Name,” generic names, and generic testimonial people.

If the scope is FOCUSED PRESERVE-FIRST EDIT:
- Change only what the instruction requires and preserve unrelated design decisions.

For every edit:
- Keep the subject-appropriate visible image story (normally six scenes for image-rich sites; fewer for professional/community sites; no decorative quota for resume/document artifacts) and preserve all data-simo-section/data-simo-editable attributes.
- Avoid tiny cards, excessive empty space, generic copy, default-looking forms, and bland flat heroes.
- The result must look noticeably better and remain nearly publish-ready.
- Return raw HTML only.

CURRENT HTML:
{current_html}
"""
        html = current_html if pure_pixel_edit else ""
        errors = []
        if pure_pixel_edit:
            pass
        elif full_art_direction:
            # 10.5: whole-site luxury/premium/redesign requests use the same universal
            # creative-director contract as first generation, so they can actually
            # recompose layout instead of applying a style preset.
            redesign_variant = (int(hashlib.sha256((base_prompt + "|" + instruction + "|" + current_html[:4000]).encode("utf-8")).hexdigest()[:6], 16) % 5) + 1
            image_preservation_brief = (
                " IMAGE CONTRACT: The user did not request new photography. Preserve the existing website image inventory and local image URLs; "
                "do not add remote image URLs or make image generation a prerequisite for this style/layout redesign. "
                "You may change image size, crop, placement, framing, overlays and section rhythm to support the new art direction."
                if preserve_style_images else
                " IMAGE CONTRACT: The user explicitly requested imagery changes; image assets may change as needed."
            )
            redesign_brief = (
                "REDESIGN INTENT: " + instruction + "\n"
                "Preserve the exact subject and useful business/editorial facts, but treat the current page only as content reference. "
                "Recompose the site as a genuinely different premium art direction. The result must not be a recolor or the same card geometry."
                + image_preservation_brief
            )
            full_prompt = _simo_v71_design_prompt(base_prompt, variant=redesign_variant, previous_html=current_html, creative_brief=redesign_brief)
            full_prompt += "\n\nEXPLICIT USER REDESIGN REQUEST:\n" + instruction + "\nReturn the transformed complete HTML only."
            try:
                html = _simo_v71_model_call(client, model, full_prompt, base_prompt)
            except Exception as exc:
                errors.append("Creative Director redesign: " + str(exc))
            if html and _simo_v105_structural_similarity(current_html, html) >= 0.82:
                try:
                    retry_prompt = _simo_v71_design_prompt(
                        base_prompt,
                        "The proposed redesign is still structurally too similar. Change hero geometry, section sequence, grid/card system, typography scale, image rhythm, CTA placement and footer while preserving subject/content.",
                        variant=redesign_variant + 1,
                        previous_html=current_html,
                        creative_brief=redesign_brief,
                    )
                    retry_prompt += "\n\nEXPLICIT USER REDESIGN REQUEST:\n" + instruction
                    retry_html = _simo_v71_model_call(client, model, retry_prompt, base_prompt)
                    if retry_html and _simo_v105_structural_similarity(current_html, retry_html) < _simo_v105_structural_similarity(current_html, html):
                        html = retry_html
                except Exception as exc:
                    errors.append("Creative Director redesign retry: " + str(exc))
        else:
            responses_api = getattr(client, "responses", None)
            if responses_api is not None and hasattr(responses_api, "create"):
                try:
                    resp = responses_api.create(model=model, input=[{"role": "system", "content": edit_prompt}])
                    html = _simo_rc2_extract_html(_simo_rc2_extract_text(resp))
                except Exception as exc:
                    errors.append("Responses API: " + str(exc))
            if not html:
                try:
                    chat_api = getattr(getattr(client, "chat", None), "completions", None)
                    if chat_api is None or not hasattr(chat_api, "create"):
                        raise RuntimeError("Installed OpenAI SDK exposes neither responses.create nor chat.completions.create")
                    resp = chat_api.create(
                        model=model,
                        messages=[{"role": "system", "content": edit_prompt}],
                        temperature=0.55,
                        max_tokens=12000,
                    )
                    html = _simo_rc2_extract_html(_simo_rc2_extract_text(resp))
                except Exception as exc:
                    errors.append("Chat Completions API: " + str(exc))

        if html and not pure_pixel_edit and not full_art_direction:
            visible_ok, visible_meta = _simo_v113_visible_edit_changed(current_html, html, instruction)
            if not visible_ok:
                retry_prompt = edit_prompt + f"""

IMPORTANT RETRY: The previous edit attempt did not produce a clearly visible user-facing change ({visible_meta.get('reason')}).
Apply the user's instruction OBVIOUSLY but professionally now. Preserve unrelated sections, but the requested target must visibly change in text, imagery, layout, styling, controls, or section content as appropriate. Do not return the same page with metadata-only differences.
"""
                try:
                    retry_html = _simo_v71_model_call(client, model, retry_prompt, base_prompt)
                    retry_ok, _retry_meta = _simo_v113_visible_edit_changed(current_html, retry_html, instruction)
                    if retry_html and retry_ok:
                        html = retry_html
                        auto_repaired = True
                except Exception as exc:
                    errors.append("Visible-edit retry: " + str(exc))

        if html and not pure_pixel_edit:
            # 8.9: keep the model's redesign as the source of truth. Do not
            # re-template it afterward. Full redesigns refresh imagery; focused
            # edits preserve existing good imagery.
            html = _simo_v81_builder_annotation_completion(html, base_prompt)
            if full_art_direction:
                html = _simo_v96_visual_enrichment_pass(html, base_prompt)
            else:
                html = _simo_v85_contextualize_images(html, base_prompt, refresh_all=False)
                html = _simo_v81_builder_annotation_completion(html, base_prompt)
                html = _simo_v94_media_guard(html, base_prompt)
            html = _simo_v89_cohesive_guard(html, base_prompt)
            html = _simo_v105_layout_safety_guard(html, base_prompt)
            if preserve_style_images:
                html = _simo_v114_preserve_style_edit_image_inventory(current_html, html)

        image_edit_result = {"ok": True, "required": False, "selected": 0, "edited": 0, "failed": []}
        if image_edit_contract.get("requires_pixel_edit"):
            # Focused image edits must operate on the exact images the user is looking at.
            # Restore the canonical local source inventory before pixel editing so the
            # HTML model cannot silently swap a requested image for a fresh unrelated one.
            if not full_art_direction:
                html = _simo_v104_restore_local_image_sources(current_html, html)
            html_before_pixel_edit = html
            html, image_edit_result = _simo_v107_apply_visible_image_edit(html, instruction, base_prompt, client)
            if not image_edit_result.get("ok"):
                return _simo_contract_json_error(
                    "SIMO could not complete the requested visible image edit, so the current website was preserved unchanged.",
                    502,
                    "visible_image_edit_failed",
                    "; ".join([str(x) for x in (image_edit_result.get("failed") or [])[:6]]) or "selected website images were not visibly replaced",
                )
            if html == html_before_pixel_edit:
                return _simo_contract_json_error(
                    "SIMO did not produce a visible image change. The current website was preserved unchanged.",
                    409,
                    "visible_image_edit_unchanged",
                )

        before = re.sub(r"\s+", " ", current_html).strip()
        after = re.sub(r"\s+", " ", html).strip()
        if not _simo_rc2_html_good(html, base_prompt):
            detail = " | ".join(errors) or _simo_rc2_html_quality_reason(html, base_prompt)
            return _simo_contract_json_error(
                "SIMO could not safely apply that edit. The current website was preserved unchanged.",
                502,
                "edit_validation_failed",
                detail,
            )
        if before == after:
            return _simo_contract_json_error(
                "SIMO did not produce a visible change. The current website was preserved unchanged.",
                409,
                "unchanged_edit",
            )
        if instruction.lower() in after.lower() and instruction.lower() not in before.lower() and len(instruction) > 24:
            # A long instruction appearing verbatim is a strong signal that the model
            # turned the command into copy. Reject rather than claim success.
            return _simo_contract_json_error(
                "SIMO interpreted the edit instruction as page copy, so the unsafe result was rejected.",
                422,
                "instruction_leak_detected",
            )
        # Preserve successfully edited local assets. General edits/redesigns may need
        # normal image authoring; a pure pixel edit already produced local assets and
        # must not regenerate them from the original website prompt.
        html = _simo_v99_delivery_guard(html, base_prompt)
        html = _simo_v105_layout_safety_guard(html, base_prompt)
        if not pure_pixel_edit and explicit_image_change:
            html, authored_images = _simo_v100_author_local_images(html, base_prompt, client)
            if not authored_images.get("ok"):
                return _simo_contract_json_error(
                    "SIMO applied the edit, but could not finish the revised Razor-benchmark local image set. The current website was preserved unchanged.",
                    502, "edit_local_image_authoring_failed",
                    f"authored={authored_images.get('authored',0)} of target {authored_images.get('target',0)}; remaining_remote={authored_images.get('remaining_remote',0)}; failed={len(authored_images.get('failed') or [])}"
                )
        try:
            edit_readiness_timeout = float(os.getenv("SIMO_WEBSITE_IMAGE_READINESS_TIMEOUT", "7.0") or "7.0")
        except Exception:
            edit_readiness_timeout = 7.0
        edit_readiness_timeout = min(max(edit_readiness_timeout, 4.0), 12.0)
        if preserve_style_images and not pure_pixel_edit:
            style_local_urls = []
            for _u in re.findall(r'<img\b[^>]*\bsrc=["\']([^"\']+)["\'][^>]*>', html, flags=re.I):
                if (_u.startswith('/generated-images/') or _u.startswith('/static/simo_web_images/')) and _u not in style_local_urls:
                    style_local_urls.append(_u)
            style_remote_count = len(re.findall(r'<img\b[^>]*\bsrc=["\']https?://', html, flags=re.I))
            image_readiness = {
                "ok": style_remote_count == 0 and bool(style_local_urls),
                "target": len(style_local_urls),
                "localized": len(style_local_urls),
                "remaining_remote": style_remote_count,
                "failed": [],
            }
        else:
            html, image_readiness = _simo_v99_localize_images_strict(html, base_prompt, edit_readiness_timeout)
        if not image_readiness.get("ok"):
            return _simo_contract_json_error(
                "SIMO applied the edit, but the revised visual assets were not fully ready. The current website was preserved unchanged.",
                502,
                "edit_image_readiness_failed",
                f"localized {image_readiness.get('localized', 0)} of target {image_readiness.get('target', 0)}; remaining_remote={image_readiness.get('remaining_remote', 0)}"
            )
        # Finish with non-destructive responsive/craft polish before judging the edit.
        html = _simo_v1024_non_destructive_finish(html, base_prompt)
        edit_good, edit_reasons = _simo_v99_razor_review(html, base_prompt)
        if preserve_style_images:
            edit_reasons = _simo_v115_style_edit_razor_reasons(edit_reasons)
            edit_good = not bool(edit_reasons)

        if not edit_good:
            safety_html = _simo_v113_edit_release_safety(html, edit_reasons)
            if safety_html != html:
                html = _simo_v105_layout_safety_guard(_simo_v89_cohesive_guard(safety_html, base_prompt), base_prompt)
                edit_good, edit_reasons = _simo_v99_razor_review(html, base_prompt)
                if preserve_style_images:
                    edit_reasons = _simo_v115_style_edit_razor_reasons(edit_reasons)
                    edit_good = not bool(edit_reasons)
                auto_repaired = True

        if not edit_good and full_art_direction and preserve_style_images:
            # A style/layout redesign should be judged on problems it introduced.
            # Existing image-inventory limitations from an older saved site are not
            # a reason to throw away a visibly improved redesign when imagery was
            # not part of the user's request.
            new_full_reasons = _simo_v113_new_razor_reasons(baseline_razor_reasons, edit_reasons)
            if not new_full_reasons:
                edit_good = True
            else:
                edit_reasons = new_full_reasons

        if not edit_good and full_art_direction:
            best_html, best_reasons = html, list(edit_reasons)
            for repair_pass in (1, 2):
                repaired = _simo_v104_final_repair(client, model, best_html, base_prompt, best_reasons, repair_pass)
                if not repaired or repaired == best_html:
                    continue
                repaired = _simo_v81_builder_annotation_completion(repaired, base_prompt)
                repaired = _simo_v89_cohesive_guard(repaired, base_prompt)
                repaired = _simo_v105_layout_safety_guard(repaired, base_prompt)
                repaired = _simo_v1024_non_destructive_finish(repaired, base_prompt)
                repaired = _simo_v113_edit_release_safety(repaired, best_reasons)
                good2, reasons2 = _simo_v99_razor_review(repaired, base_prompt)
                if preserve_style_images:
                    reasons2 = _simo_v115_style_edit_razor_reasons(reasons2)
                    good2 = not bool(reasons2)
                if good2 or len(reasons2) < len(best_reasons):
                    best_html, best_reasons = repaired, list(reasons2)
                    auto_repaired = True
                if good2:
                    edit_good, edit_reasons, html = True, reasons2, repaired
                    break
            if not edit_good:
                html, edit_reasons = best_html, best_reasons

        if not edit_good and not full_art_direction:
            new_reasons = _simo_v113_new_razor_reasons(baseline_razor_reasons, edit_reasons)
            if not new_reasons:
                edit_good = True
            else:
                repaired = _simo_v104_final_repair(client, model, html, base_prompt, new_reasons, 1)
                if repaired and repaired != html:
                    repaired = _simo_v81_builder_annotation_completion(repaired, base_prompt)
                    repaired = _simo_v89_cohesive_guard(repaired, base_prompt)
                    repaired = _simo_v105_layout_safety_guard(repaired, base_prompt)
                    repaired = _simo_v1024_non_destructive_finish(repaired, base_prompt)
                    repaired = _simo_v113_edit_release_safety(repaired, new_reasons)
                    good2, reasons2 = _simo_v99_razor_review(repaired, base_prompt)
                    if preserve_style_images:
                        reasons2 = _simo_v115_style_edit_razor_reasons(reasons2)
                        good2 = not bool(reasons2)
                    remaining_new = _simo_v113_new_razor_reasons(baseline_razor_reasons, reasons2)
                    if good2 or not remaining_new:
                        html = repaired
                        edit_good, edit_reasons = True, reasons2
                        auto_repaired = True

        visible_changed, visible_meta = _simo_v113_visible_edit_changed(current_html, html, instruction, image_edit_result)
        if not visible_changed:
            return _simo_contract_json_error(
                "Simo understood the edit, but could not verify a visible user-facing change. The current website was preserved unchanged.",
                409,
                "edit_visible_change_not_verified",
                str(visible_meta)[:700],
            )

        if not edit_good:
            return _simo_contract_json_error(
                "Simo applied the instruction and automatically retried the edit, but the revised page still did not meet the Razor benchmark release gate. The current website was preserved unchanged.",
                502,
                "edit_razor_benchmark_failed",
                "; ".join(edit_reasons[:10])
            )
        # 10.34: never report success for an add-missing-image edit unless the exact
        # generated asset and insertion marker still exist in the final delivered HTML
        # after every delivery/layout/readiness guard.
        if int(image_edit_result.get("added") or 0) > 0:
            added_url = str(image_edit_result.get("added_url") or "").strip()
            if (not added_url) or (added_url not in html) or ('data-simo-added-image="1"' not in html):
                return _simo_contract_json_error(
                    "SIMO generated the requested section image but it did not survive the final website pipeline, so the current website was preserved unchanged.",
                    409,
                    "visible_image_insert_not_delivered",
                    "requested image insertion was missing from final HTML"
                )
        return jsonify({
            "ok": True,
            "html": html,
            "phase": "SIMO_CANONICAL_WEBSITE_EDIT_10_34",
            "release": SIMO_RELEASE_ID,
            "owner": "simo_canonical_website_edit",
            "model": model,
            "visible_image_edit": bool(image_edit_result.get("required")),
            "images_selected": int(image_edit_result.get("selected") or 0),
            "images_edited": int(image_edit_result.get("edited") or 0),
            "visible_change_verified": True,
            "auto_repaired": bool(auto_repaired),
            "edit_summary": (
                f"Visible image edit applied to {int(image_edit_result.get('edited') or 0)} image(s). Save when ready."
                if image_edit_result.get("required")
                else ("Edit applied and automatically refined to pass Simo's release check. Save when ready." if auto_repaired else "Edit applied. Save when ready.")
            ),
        })
    except Exception as exc:
        return _simo_contract_json_error("Website edit failed. The current website was preserved unchanged.", 500, "edit_exception", str(exc))


def _simo_canonical_home():
    """GET renders SIMO. POST defaults to chat unless explicit visual metadata is present."""
    if request.method == "GET":
        usage_today = get_daily_usage_count(user_key_for_limits(), get_today_key())
        image_credits = simo_design_credit_status()
        boot = {
            "loggedIn": is_logged_in(), "email": current_user_email(), "name": current_user_name(),
            "pro": is_pro_user(), "team": (_simo_account_plan() == "team"), "accountOwnedLibrary": bool(is_logged_in() and is_pro_user()), "freeDailyLimit": FREE_DAILY_LIMIT,
            "usageToday": usage_today, "imageCredits": image_credits,
            "stripePublishableKey": STRIPE_PUBLISHABLE_KEY, "stripePriceId": STRIPE_PRICE_ID,
            "baseUrl": BASE_URL, "builderLibraryKey": "simo_builder_library_v5_1_builder_first",
            "lastPreviewKey": "simo_last_preview_v2", "release": SIMO_RELEASE_ID,
        }
        return render_template("index.html", simo_boot=boot, simo_boot_json=json.dumps(boot))
    data = request.get_json(silent=True) or {}
    explicit_visual = bool(
        data.get("active_visual_project")
        or data.get("visual_core_phase")
        or data.get("exact_object_lock")
        or data.get("locked_subject")
        or str(data.get("lane") or data.get("intent") or "").strip().lower() in {"visual", "design", "image"}
    )
    return api_generate_visual() if explicit_visual else api_chat()


def _simo_canonical_publish():
    data = request.get_json(silent=True) or {}
    html = str(data.get("html") or data.get("code") or data.get("content") or data.get("markup") or "").strip()
    if not html:
        return _simo_contract_json_error("Exact website HTML is required for publishing.", 400, "missing_publish_html")
    if "<html" not in html.lower() or "</html>" not in html.lower():
        return _simo_contract_json_error("Publish requires one complete HTML document.", 422, "invalid_publish_html")
    return _publish_from_request()


def _simo_canonical_download_html():
    data = request.get_json(silent=True) or {}
    html = str(data.get("html") or "").strip()
    if not html:
        return _simo_contract_json_error("HTML is required for download.", 400, "missing_download_html")
    filename = secure_filename(str(data.get("filename") or "simo-build.html").strip()) or "simo-build.html"
    if not filename.lower().endswith(".html"):
        filename += ".html"
    return Response(html, mimetype="text/html", headers={"Content-Disposition": f'attachment; filename="{filename}"'})


def _simo_canonical_health():
    active = {}
    for endpoint in ("api_simo_website_v3_generate", "api_simo_website_v3_edit", "api_website_v2_generate_alias", "api_website_v2_edit_alias"):
        fn = app.view_functions.get(endpoint)
        active[endpoint] = getattr(fn, "__name__", "missing") if fn else "missing"
    return jsonify({
        "ok": True,
        "app": "simo",
        "release": SIMO_RELEASE_ID,
        "backend_version": SIMO_RELEASE_ID,
        "time": utcnow_z(),
        "logged_in": is_logged_in(),
        "pro": is_pro_user(),
        "canonical_owners": active,
        "contracts": {
            "website_generate": "/api/simo-website-v3/generate",
            "website_edit": "/api/simo-website-v3/edit",
            "visual_generate": "/api/generate-visual",
            "workspace_edit": "/api/workspace-image-edit",
            "library": "/api/library",
            "publish": "/api/publish",
        },
    })


def _simo_seal_endpoint(endpoint, function):
    if endpoint in app.view_functions:
        app.view_functions[endpoint] = function
        return True
    return False


# Seal every active and compatibility route to the canonical contracts.
_simo_seal_endpoint("home", _simo_canonical_home)
_simo_seal_endpoint("health", _simo_canonical_health)
_simo_seal_endpoint("api_simo_website_v3_generate", _simo_canonical_website_generate)
_simo_seal_endpoint("api_simo_website_v3_edit", _simo_canonical_website_edit)
_simo_seal_endpoint("api_website_v2_generate_alias", _simo_canonical_website_generate)
_simo_seal_endpoint("api_website_v2_edit_alias", _simo_canonical_website_edit)
_simo_seal_endpoint("simo_ai_website_rc2_alias", _simo_canonical_website_generate)
_simo_seal_endpoint("simo_ai_edit_rc2_alias", _simo_canonical_website_edit)
_simo_seal_endpoint("api_publish", _simo_canonical_publish)
_simo_seal_endpoint("api_download_html", _simo_canonical_download_html)

