def _simo_tree_bytes(path: str) -> int:
    total = 0
    try:
        root = os.path.abspath(str(path or ""))
        if not root or not os.path.isdir(root):
            return 0
        for dirpath, _, filenames in os.walk(root):
            for filename in filenames:
                try:
                    total += os.path.getsize(os.path.join(dirpath, filename))
                except OSError:
                    pass
    except Exception:
        return total
    return total


def _simo_media_storage_status() -> dict:
    """Return live media-storage safety without charging legacy media against users.

    Two independent protections are supported:
    1) minimum real filesystem headroom (always on);
    2) optional global media-tree hard cap (off by default).

    Per-account Library limits are enforced separately by _simo_library_quota().
    """
    try:
        disk = shutil.disk_usage(BASE_DIR)
        disk_total = int(disk.total)
        disk_used = int(disk.used)
        disk_free = int(disk.free)
    except Exception:
        disk_total = disk_used = 0
        # Fail closed only when we have positive evidence that storage is exhausted.
        # A platform that cannot report disk usage should not make every generation fail.
        disk_free = 2**63 - 1

    required_headroom = SIMO_MEDIA_MIN_HEADROOM_MB * 1024 * 1024
    disk_ok = disk_free >= required_headroom

    media_used = 0
    hard_cap_bytes = SIMO_MEDIA_HARD_CAP_MB * 1024 * 1024
    hard_cap_ok = True
    if hard_cap_bytes > 0:
        # Optional operator-configured ceiling. This is intentionally disabled by
        # default so pre-existing development/library media does not become a billable
        # user's new-storage usage on upgrade.
        candidates = []
        try:
            candidates.extend(generated_image_storage_dirs())
        except Exception:
            pass
        candidates.extend([UPLOAD_DIR, os.path.join(STATIC_DIR, "simo_web_images")])
        seen = set()
        for path in candidates:
            try:
                real = os.path.realpath(os.path.abspath(str(path or "")))
            except Exception:
                continue
            if not real or real in seen:
                continue
            seen.add(real)
            media_used += _simo_tree_bytes(real)
        hard_cap_ok = media_used < hard_cap_bytes

    return {
        "disk_total_bytes": disk_total,
        "disk_used_bytes": disk_used,
        "disk_free_bytes": disk_free if disk_free < 2**63 - 1 else None,
        "required_headroom_bytes": required_headroom,
        "media_used_bytes": media_used if hard_cap_bytes > 0 else None,
        "hard_cap_bytes": hard_cap_bytes if hard_cap_bytes > 0 else None,
        "legacy_media_counted_against_user": False,
        "ok_for_new_media": bool(disk_ok and hard_cap_ok),
    }


def _simo_media_preflight(action_type: str):
    media_actions = {
        "generate_visual", "book_cover", "workspace_image_edit",
        "website_generate", "website_image_edit", "website_redesign",
        "website_premium_variant",
    }
    if str(action_type or "") not in media_actions:
        return True, None
    status = _simo_media_storage_status()
    if status.get("ok_for_new_media"):
        return True, None
    return False, (jsonify({
        "ok": False,
        "error": "Simo storage protection stopped this generation before the provider call because the host does not have enough safe disk headroom for new media. No provider call was made.",
        "code": "simo_storage_cap_reached",
        "storage": status,
    }), 507)


def _simo_library_quota(email: str, build_id: str = "", incoming_bytes: int = 0):
    email = str(email or "").strip().lower()
    plan = _simo_account_plan(email)
    if plan == "team":
        max_items = SIMO_TEAM_LIBRARY_MAX_ITEMS
        max_bytes = SIMO_TEAM_LIBRARY_MAX_MB * 1024 * 1024
    else:
        max_items = SIMO_PRO_LIBRARY_MAX_ITEMS
        max_bytes = SIMO_PRO_LIBRARY_MAX_MB * 1024 * 1024
    conn = get_db()
    try:
        rows = conn.execute(
            "SELECT id, COALESCE(LENGTH(html),0) + COALESCE(LENGTH(source_text),0) AS bytes FROM saved_builds WHERE lower(trim(user_email)) = ?",
            (email,),
        ).fetchall()
    finally:
        conn.close()
    count = len(rows)
    used = sum(int(r["bytes"] or 0) for r in rows)
    replacing = None
    for r in rows:
        if str(r["id"] or "") == str(build_id or ""):
            replacing = r
            break
    projected_count = count if replacing is not None else count + 1
    projected_bytes = used - (int(replacing["bytes"] or 0) if replacing is not None else 0) + max(0, int(incoming_bytes or 0))
    ok = projected_count <= max_items and projected_bytes <= max_bytes
    return ok, {
        "plan": plan, "items": count, "max_items": max_items,
        "used_bytes": used, "max_bytes": max_bytes,
        "projected_items": projected_count, "projected_bytes": projected_bytes,
    }


def _simo_profit_schema_init():
    conn = get_db()
    cur = conn.cursor()
    ensure_column(conn, "users", "plan", "TEXT DEFAULT 'free'")
    ensure_column(conn, "users", "auto_reload_enabled", "INTEGER DEFAULT 0")
    ensure_column(conn, "users", "auto_reload_pack", "TEXT DEFAULT '100'")
    ensure_column(conn, "users", "auto_reload_threshold", "INTEGER DEFAULT 20")
    ensure_column(conn, "users", "auto_reload_monthly_cap_cents", "INTEGER DEFAULT 5000")
    ensure_column(conn, "users", "auto_reload_spend_month", "TEXT")
    ensure_column(conn, "users", "auto_reload_spend_cents", "INTEGER DEFAULT 0")
    cur.execute(
        """
        CREATE TABLE IF NOT EXISTS simo_credit_events (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            user_key TEXT,
            email TEXT,
            event_type TEXT,
            action_type TEXT,
            credits INTEGER DEFAULT 0,
            source TEXT,
            reference_id TEXT,
            metadata_json TEXT,
            created_at TEXT
        )
        """
    )
    # Existing paid users become Pro unless they already carry a Team plan.
    cur.execute(
        """
        UPDATE users
        SET plan = CASE
            WHEN lower(COALESCE(plan,'')) = 'team' THEN 'team'
            WHEN pro = 1 THEN 'pro'
            ELSE 'free'
        END
        WHERE plan IS NULL OR trim(plan) = '' OR lower(plan) NOT IN ('free','pro','team')
        """
    )
    conn.commit()
    conn.close()


_simo_profit_schema_init()


def _simo_db_row_value(row, key, default=""):
    try:
        value = row[key]
    except Exception:
        value = default
    return default if value is None else value


def _simo_set_user_plan(email: str, plan: str):
    email = str(email or "").strip().lower()
    plan = str(plan or "free").strip().lower()
    if plan not in {"free", "pro", "team"}:
        plan = "free"
    if not email:
        return
    conn = get_db()
    conn.execute(
        "UPDATE users SET plan = ?, updated_at = ? WHERE lower(email) = lower(?)",
        (plan, utcnow().isoformat(), email),
    )
    conn.commit()
    conn.close()


def _simo_price_plan_from_id(price_id: str) -> str:
    price_id = str(price_id or "").strip()
    if not price_id:
        return ""
    for spec in SIMO_PLAN_PRICES.values():
        if spec.get("price_id") and spec.get("price_id") == price_id:
            return str(spec.get("plan") or "")
    return ""


def _simo_subscription_plan_from_stripe(row) -> str:
    if not row or not STRIPE_SECRET_KEY:
        return ""
    sub_id = str(_simo_db_row_value(row, "stripe_subscription_id", "") or "").strip()
    if not sub_id:
        return ""
    try:
        sub = stripe.Subscription.retrieve(sub_id)
        items = normalize_stripe_obj_value(sub, "items", None)
        data = normalize_stripe_obj_value(items, "data", []) if items is not None else []
        for item in data or []:
            price = normalize_stripe_obj_value(item, "price", None)
            pid = str(normalize_stripe_obj_value(price, "id", "") or "").strip()
            plan = _simo_price_plan_from_id(pid)
            if plan:
                return plan
        meta = normalize_stripe_obj_value(sub, "metadata", {}) or {}
        if hasattr(meta, "get"):
            plan = str(meta.get("simo_plan") or meta.get("plan") or "").strip().lower()
            if plan in {"pro", "team"}:
                return plan
    except Exception:
        pass
    return ""


_simo_sync_user_pro_legacy = sync_user_pro_from_stripe

def sync_user_pro_from_stripe(email: str):
    row = _simo_sync_user_pro_legacy(email)
    email = str(email or "").strip().lower()
    if not email or not row:
        return row
    if int(_simo_db_row_value(row, "pro", 0) or 0) != 1:
        _simo_set_user_plan(email, "free")
        return get_user_by_email(email)
    current = str(_simo_db_row_value(row, "plan", "") or "").strip().lower()
    if current not in {"pro", "team"}:
        current = _simo_subscription_plan_from_stripe(row) or "pro"
        _simo_set_user_plan(email, current)
        row = get_user_by_email(email)
    return row


def _simo_account_plan(email: str = "") -> str:
    email = str(email or current_user_email() or "").strip().lower()
    if is_simo_admin_email(email) and SIMO_OWNER_UNMETERED_AI:
        return "admin"
    if not email:
        return "anon"
    try:
        row = sync_user_pro_from_stripe(email)
    except Exception:
        row = get_user_by_email(email)
    if not row or int(_simo_db_row_value(row, "pro", 0) or 0) != 1:
        return "free"
    plan = str(_simo_db_row_value(row, "plan", "pro") or "pro").strip().lower()
    return "team" if plan == "team" else "pro"


def simo_design_plan(email: str = "") -> str:
    return _simo_account_plan(email)


def simo_design_credit_limit(plan: str) -> int:
    plan = str(plan or "free").strip().lower()
    if plan == "admin":
        return -1
    if plan == "team":
        return SIMO_TEAM_CREDITS_MONTHLY
    if plan == "pro":
        return SIMO_PRO_CREDITS_MONTHLY
    return 0


def simo_design_credit_period_key(plan: str) -> str:
    plan = str(plan or "free").strip().lower()
    if plan in {"pro", "team"}:
        return f"{plan}:{utcnow().strftime('%Y-%m')}"
    if plan == "admin":
        return "admin:unlimited"
    return f"{plan}:no-funded-ai"


def simo_credit_pack_options():
    raw = [
        ("25", 25, SIMO_CREDIT_PACK_25_PRICE_ID, "25 Simo Credits", "$4.99", "Small top-up for chat, edits, or a quick creation session."),
        ("100", 100, SIMO_CREDIT_PACK_100_PRICE_ID, "100 Simo Credits", "$14.99", "Good for active creation and multiple website/design sessions."),
        ("250", 250, SIMO_CREDIT_PACK_250_PRICE_ID, "250 Simo Credits", "$29.99", "Best value for heavier Simo creation usage."),
    ]
    packs = []
    for key, credits, price_id, label, display_price, description in raw:
        if price_id:
            packs.append({
                "key": key,
                "credits": credits,
                "price_id": price_id,
                "price_cents": SIMO_CREDIT_PACK_CENTS[key],
                "display_price": display_price,
                "label": label,
                "description": description,
            })
    return packs


def _simo_credit_status(email: str = "") -> dict:
    email = str(email or current_user_email() or "").strip().lower()
    plan = _simo_account_plan(email)
    user_key = simo_design_credit_user_key(email)
    period_key = simo_design_credit_period_key(plan)
    limit = simo_design_credit_limit(plan)
    used = 0 if limit < 0 else simo_get_design_credit_usage(user_key, period_key)
    included_remaining = None if limit < 0 else max(0, limit - used)
    purchased_remaining = 0 if limit < 0 else simo_get_purchased_design_credit_remaining(user_key)
    total_remaining = None if limit < 0 else max(0, int(included_remaining or 0) + int(purchased_remaining or 0))
    row = get_user_by_email(email) if email else None
    auto = {
        "enabled": bool(row and int(_simo_db_row_value(row, "auto_reload_enabled", 0) or 0) == 1),
        "pack": str(_simo_db_row_value(row, "auto_reload_pack", "100") or "100"),
        "threshold": int(_simo_db_row_value(row, "auto_reload_threshold", 20) or 20) if row else 20,
        "monthly_cap_cents": int(_simo_db_row_value(row, "auto_reload_monthly_cap_cents", 5000) or 5000) if row else 5000,
        "spend_month": str(_simo_db_row_value(row, "auto_reload_spend_month", "") or "") if row else "",
        "spend_cents": int(_simo_db_row_value(row, "auto_reload_spend_cents", 0) or 0) if row else 0,
    }
    return {
        "enabled": True,
        "loggedIn": bool(email),
        "email": email,
        "plan": plan,
        "user_key": user_key,
        "period_key": period_key,
        "limit": limit,
        "used": used,
        "remaining": total_remaining,
        "included_remaining": included_remaining,
        "purchased_remaining": purchased_remaining,
        "unlimited": limit < 0,
        "requires_payment": plan in {"anon", "free"},
        "packs_enabled": bool(SIMO_CREDIT_PACKS_ENABLED),
        "pack_options": [{k: v for k, v in p.items() if k != "price_id"} for p in simo_credit_pack_options()],
        "costs": dict(SIMO_CREDIT_COSTS),
        "auto_reload": auto,
        "storage": _simo_media_storage_status(),
    }


def simo_design_credit_status(email: str = "") -> dict:
    # Compatibility name retained for existing frontend code.
    return _simo_credit_status(email)


def _simo_log_credit_event(email, user_key, event_type, action_type, credits, source="", reference_id="", metadata=None, conn=None):
    own = conn is None
    if own:
        conn = get_db()
    conn.execute(
        """
        INSERT INTO simo_credit_events
        (user_key,email,event_type,action_type,credits,source,reference_id,metadata_json,created_at)
        VALUES (?,?,?,?,?,?,?,?,?)
        """,
        (
            str(user_key or ""), str(email or ""), str(event_type or ""), str(action_type or ""),
            int(credits or 0), str(source or ""), str(reference_id or ""),
            json.dumps(metadata or {}, separators=(",", ":")), utcnow().isoformat(),
        ),
    )
    if own:
        conn.commit(); conn.close()


def _simo_find_payment_method(row):
    if not row or not STRIPE_SECRET_KEY:
        return ""
    customer_id = str(_simo_db_row_value(row, "stripe_customer_id", "") or "").strip()
    sub_id = str(_simo_db_row_value(row, "stripe_subscription_id", "") or "").strip()
    if sub_id:
        try:
            sub = stripe.Subscription.retrieve(sub_id)
            pm = normalize_stripe_obj_value(sub, "default_payment_method", "")
            if pm:
                return str(normalize_stripe_obj_value(pm, "id", pm) or "").strip()
        except Exception:
            pass
    if customer_id:
        try:
            customer = stripe.Customer.retrieve(customer_id)
            invoice_settings = normalize_stripe_obj_value(customer, "invoice_settings", {}) or {}
            pm = normalize_stripe_obj_value(invoice_settings, "default_payment_method", "")
            if pm:
                return str(normalize_stripe_obj_value(pm, "id", pm) or "").strip()
        except Exception:
            pass
        try:
            methods = stripe.PaymentMethod.list(customer=customer_id, type="card", limit=1)
            data = normalize_stripe_obj_value(methods, "data", []) or []
            if data:
                return str(normalize_stripe_obj_value(data[0], "id", "") or "").strip()
        except Exception:
            pass
    return ""


def _simo_try_auto_reload(email: str, needed_credits: int = 1) -> dict:
    email = str(email or "").strip().lower()
    row = get_user_by_email(email) if email else None
    plan = _simo_account_plan(email)
    if plan not in {"pro", "team"} or not row:
        return {"ok": False, "reason": "not_paid_plan"}
    if int(_simo_db_row_value(row, "auto_reload_enabled", 0) or 0) != 1:
        return {"ok": False, "reason": "disabled"}
    pack_key = str(_simo_db_row_value(row, "auto_reload_pack", "100") or "100")
    pack = simo_credit_pack_by_key(pack_key)
    if not pack:
        return {"ok": False, "reason": "pack_not_configured"}

    month = utcnow().strftime("%Y-%m")
    spend_month = str(_simo_db_row_value(row, "auto_reload_spend_month", "") or "")
    spend = int(_simo_db_row_value(row, "auto_reload_spend_cents", 0) or 0)
    if spend_month != month:
        spend = 0
    amount = int(SIMO_CREDIT_PACK_CENTS.get(pack_key, 0) or 0)
    cap = max(0, int(_simo_db_row_value(row, "auto_reload_monthly_cap_cents", 5000) or 5000))
    if amount <= 0 or (cap and spend + amount > cap):
        return {"ok": False, "reason": "monthly_cap_reached"}

    customer_id = str(_simo_db_row_value(row, "stripe_customer_id", "") or "").strip()
    payment_method = _simo_find_payment_method(row)
    if not customer_id or not payment_method:
        return {"ok": False, "reason": "payment_method_required"}

    try:
        intent = stripe.PaymentIntent.create(
            amount=amount,
            currency="usd",
            customer=customer_id,
            payment_method=payment_method,
            off_session=True,
            confirm=True,
            description=f"Simo Auto-Reload — {pack['credits']} credits",
            metadata={
                "type": "simo_auto_reload",
                "user_email": email,
                "credits": str(pack["credits"]),
                "pack": pack_key,
            },
        )
        status = str(normalize_stripe_obj_value(intent, "status", "") or "").lower()
        intent_id = str(normalize_stripe_obj_value(intent, "id", "") or "").strip()
        if status != "succeeded" or not intent_id:
            return {"ok": False, "reason": f"payment_{status or 'not_succeeded'}"}
        grant = simo_grant_purchased_design_credits(
            email=email,
            credits=int(pack["credits"]),
            stripe_session_id=intent_id,
            source="stripe_auto_reload",
        )
        if not grant.get("ok"):
            return {"ok": False, "reason": "credit_grant_failed"}
        conn = get_db()
        conn.execute(
            """
            UPDATE users SET auto_reload_spend_month = ?, auto_reload_spend_cents = ?, updated_at = ?
            WHERE lower(email) = lower(?)
            """,
            (month, spend + amount, utcnow().isoformat(), email),
        )
        conn.commit(); conn.close()
        _simo_log_credit_event(email, simo_design_credit_user_key(email), "auto_reload", "credit_pack", int(pack["credits"]), "stripe", intent_id, {"amount_cents": amount})
        return {"ok": True, "credits": int(pack["credits"]), "amount_cents": amount, "payment_intent": intent_id}
    except Exception as exc:
        return {"ok": False, "reason": "payment_failed", "detail": str(exc)[:240]}


def _simo_reserve_credits(action_type: str, cost: int):
    storage_ok, storage_denied = _simo_media_preflight(action_type)
    if not storage_ok:
        return False, None, storage_denied
    cost = max(0, int(cost or 0))
    email = str(current_user_email() or "").strip().lower()
    plan = _simo_account_plan(email)
    user_key = simo_design_credit_user_key(email)
    if plan == "admin":
        return True, {"action": action_type, "cost": 0, "plan": plan, "unlimited": True}, None
    if plan in {"anon", "free"}:
        code = "login_required" if plan == "anon" else "upgrade_required"
        message = (
            "Sign in and choose a paid Simo plan before using live AI. No provider call was made."
            if plan == "anon" else
            "Live AI creation is a paid Simo feature. Upgrade to Pro to continue. No provider call was made."
        )
        return False, None, (jsonify({
            "ok": False, "error": message, "code": f"simo_{code}",
            "needs_login": plan == "anon", "needs_upgrade": True,
            "credits": _simo_credit_status(email),
        }), 402 if plan == "free" else 401)

    # Auto-reload when the user's chosen threshold is reached, not only at zero.
    status = _simo_credit_status(email)
    row = get_user_by_email(email)
    if row and int(_simo_db_row_value(row, "auto_reload_enabled", 0) or 0) == 1:
        threshold = max(0, int(_simo_db_row_value(row, "auto_reload_threshold", 20) or 20))
        remaining = int(status.get("remaining") or 0)
        if remaining < max(cost, threshold):
            _simo_try_auto_reload(email, max(cost, threshold) - remaining)
            status = _simo_credit_status(email)

    limit = simo_design_credit_limit(plan)
    period_key = simo_design_credit_period_key(plan)
    reference_id = "reserve_" + secrets.token_hex(12)
    now = utcnow().isoformat()

    conn = get_db()
    allocations = []
    included_take = 0
    try:
        conn.execute("BEGIN IMMEDIATE")
        row_usage = conn.execute(
            "SELECT count FROM design_credit_usage WHERE user_key = ? AND period_key = ?",
            (user_key, period_key),
        ).fetchone()
        included_used = int(row_usage["count"] or 0) if row_usage else 0
        included_remaining = max(0, int(limit) - included_used)
        purchased_rows = conn.execute(
            """
            SELECT id, credits, used FROM design_credit_purchases
            WHERE user_key = ? AND credits > used
            ORDER BY created_at ASC, id ASC
            """,
            (user_key,),
        ).fetchall()
        purchased_remaining = sum(max(0, int(r["credits"] or 0) - int(r["used"] or 0)) for r in purchased_rows)
        if included_remaining + purchased_remaining < cost:
            conn.rollback(); conn.close()
            status = _simo_credit_status(email)
            return False, None, (jsonify({
                "ok": False,
                "error": f"You need {cost} Simo Credits for this action, but only {int(status.get('remaining') or 0)} remain. Add credits or enable Auto-Reload. No provider call was made.",
                "code": "simo_credits_exhausted",
                "required_credits": cost,
                "credits": status,
            }), 402)

        included_take = min(cost, included_remaining)
        if included_take:
            new_used = included_used + included_take
            if row_usage:
                conn.execute(
                    "UPDATE design_credit_usage SET count = ?, plan = ?, updated_at = ? WHERE user_key = ? AND period_key = ?",
                    (new_used, plan, now, user_key, period_key),
                )
            else:
                conn.execute(
                    "INSERT INTO design_credit_usage (user_key,period_key,plan,count,created_at,updated_at) VALUES (?,?,?,?,?,?)",
                    (user_key, period_key, plan, included_take, now, now),
                )
        left = cost - included_take
        if left:
            for r in purchased_rows:
                if left <= 0:
                    break
                available = max(0, int(r["credits"] or 0) - int(r["used"] or 0))
                take = min(left, available)
                if take:
                    conn.execute(
                        "UPDATE design_credit_purchases SET used = used + ?, updated_at = ? WHERE id = ?",
                        (take, now, r["id"]),
                    )
                    allocations.append({"id": int(r["id"]), "credits": int(take)})
                    left -= take
        _simo_log_credit_event(email, user_key, "reserve", action_type, -cost, "meter", reference_id, {"included": included_take, "purchased": allocations}, conn=conn)
        conn.commit(); conn.close()
        return True, {
            "action": action_type, "cost": cost, "plan": plan, "email": email,
            "user_key": user_key, "period_key": period_key, "included": included_take,
            "purchased": allocations, "reference_id": reference_id,
        }, None
    except Exception as exc:
        try: conn.rollback(); conn.close()
        except Exception: pass
        return False, None, (jsonify({"ok": False, "error": "Simo could not verify prepaid usage, so the AI request was blocked before generation.", "code": "simo_credit_guard_error", "detail": str(exc)[:240]}), 503)


def _simo_release_reservation(reservation, reason="request_failed"):
    if not reservation or reservation.get("unlimited") or int(reservation.get("cost") or 0) <= 0:
        return
    conn = get_db()
    try:
        conn.execute("BEGIN IMMEDIATE")
        included = int(reservation.get("included") or 0)
        if included:
            row = conn.execute(
                "SELECT count FROM design_credit_usage WHERE user_key = ? AND period_key = ?",
                (reservation.get("user_key"), reservation.get("period_key")),
            ).fetchone()
            current = int(row["count"] or 0) if row else 0
            conn.execute(
                "UPDATE design_credit_usage SET count = ?, updated_at = ? WHERE user_key = ? AND period_key = ?",
                (max(0, current - included), utcnow().isoformat(), reservation.get("user_key"), reservation.get("period_key")),
            )
        for alloc in reservation.get("purchased") or []:
            conn.execute(
                "UPDATE design_credit_purchases SET used = MAX(0, used - ?), updated_at = ? WHERE id = ?",
                (int(alloc.get("credits") or 0), utcnow().isoformat(), int(alloc.get("id") or 0)),
            )
        _simo_log_credit_event(
            reservation.get("email"), reservation.get("user_key"), "release",
            reservation.get("action"), int(reservation.get("cost") or 0), reason,
            reservation.get("reference_id"), {}, conn=conn,
        )
        conn.commit(); conn.close()
    except Exception:
        try: conn.rollback(); conn.close()
        except Exception: pass


def _simo_response_failed(resp) -> bool:
    target = resp
    status_code = None
    if isinstance(resp, tuple):
        target = resp[0] if resp else None
        if len(resp) > 1 and isinstance(resp[1], int):
            status_code = resp[1]
    if status_code is None:
        status_code = int(getattr(target, "status_code", 200) or 200)
    if status_code >= 400:
        return True
    try:
        data = target.get_json(silent=True) if hasattr(target, "get_json") else None
        if isinstance(data, dict) and data.get("ok") is False:
            return True
    except Exception:
        pass
    return False


def _simo_metered_call(action_type: str, cost: int, fn):
    ok, reservation, denied = _simo_reserve_credits(action_type, cost)
    if not ok:
        return denied
    request.environ["simo.credit_reserved"] = True
    request.environ["simo.credit_action"] = action_type
    request.environ["simo.credit_cost"] = int(cost)
    try:
        resp = fn()
        if _simo_response_failed(resp):
            _simo_release_reservation(reservation, "request_failed")
        return resp
    except Exception:
        _simo_release_reservation(reservation, "request_exception")
        raise
    finally:
        request.environ.pop("simo.credit_reserved", None)
        request.environ.pop("simo.credit_action", None)
        request.environ.pop("simo.credit_cost", None)


# Existing visual routes have their own older 1-credit guard.  A generic Profit
# Shield reservation supersedes it for the duration of the request, preventing a
# double charge while keeping legacy behavior intact outside the metered wrappers.
_simo_legacy_check_image_credit_available = simo_check_image_credit_available
_simo_legacy_consume_image_credit = simo_consume_image_credit

def simo_check_image_credit_available(action_type: str = "image_generation"):
    if request.environ.get("simo.credit_reserved"):
        return True, _simo_credit_status(), None
    return _simo_legacy_check_image_credit_available(action_type)


def simo_consume_image_credit(action_type: str = "image_generation") -> dict:
    if request.environ.get("simo.credit_reserved"):
        status = _simo_credit_status()
        status["consumed"] = True
        status["consumed_from"] = "profit_shield_reservation"
        status["action_type"] = action_type
        return status
    return _simo_legacy_consume_image_credit(action_type)


def _simo_chat_meter_cost():
    data = request.get_json(silent=True) or {}
    mode = str(data.get("simo_mode") or data.get("lane") or "").strip().lower()
    text = str(data.get("message") or data.get("text") or "").strip().lower()
    if mode == "website" or re.search(r"\b(build|make|create|design)\b.{0,30}\b(website|site|landing page|web page)\b", text):
        return "website_generate", SIMO_CREDIT_COSTS["website_generate"]
    if mode == "design" or re.search(r"\b(create|generate|design|render|show me)\b.{0,35}\b(image|visual|logo|product|book cover)\b", text):
        if "book cover" in text:
            return "book_cover", SIMO_CREDIT_COSTS["book_cover"]
        return "generate_visual", SIMO_CREDIT_COSTS["generate_visual"]
    if mode == "analyze" or data.get("has_image"):
        return "analyze_image", SIMO_CREDIT_COSTS["analyze_image"]
    return "chat", SIMO_CREDIT_COSTS["chat"]


def _simo_visual_meter_cost():
    data = request.get_json(silent=True) or {}
    text = str(data.get("prompt") or data.get("message") or data.get("text") or "").lower()
    if "book cover" in text or "book jacket" in text:
        return "book_cover", SIMO_CREDIT_COSTS["book_cover"]
    return "generate_visual", SIMO_CREDIT_COSTS["generate_visual"]


def _simo_website_edit_meter_cost():
    data = request.get_json(silent=True) or {}
    text = str(data.get("instruction") or data.get("prompt") or data.get("message") or "").strip().lower()
    if re.search(r"try another|another premium|premium version|new version|alternate version", text):
        return "website_premium_variant", SIMO_CREDIT_COSTS["website_premium_variant"]
    if re.search(r"redesign|make.*luxur|more luxur|new theme|rebrand|complete redesign|full redesign", text):
        return "website_redesign", SIMO_CREDIT_COSTS["website_redesign"]
    if re.search(r"\b(image|photo|picture|hero image|gallery|replace image|swap image|etch|engrave|recolor)\b", text):
        return "website_image_edit", SIMO_CREDIT_COSTS["website_image_edit"]
    return "website_edit", SIMO_CREDIT_COSTS["website_edit"]


# Save original active owners, then meter them.  Function globals are replaced too
# so POST / compatibility routing cannot bypass the shield.
_simo_api_chat_unmetered = api_chat
_simo_api_generate_visual_unmetered = api_generate_visual
_simo_api_workspace_image_edit_unmetered = api_workspace_image_edit
_simo_api_analyze_image_unmetered = api_analyze_image
