@app.route("/api/credits/status", methods=["GET"])
def api_simo_credits_status():
    status = _simo_credit_status()
    status["pricing"] = {k: {kk: vv for kk, vv in v.items() if kk != "price_id"} for k, v in SIMO_PLAN_PRICES.items()}
    return jsonify({"ok": True, "credits": status})


@app.route("/api/credits/auto-reload", methods=["GET", "POST"])
def api_simo_auto_reload():
    email = str(current_user_email() or "").strip().lower()
    if not email:
        return jsonify({"ok": False, "error": "Sign in first."}), 401
    plan = _simo_account_plan(email)
    if request.method == "GET":
        return jsonify({"ok": True, "credits": _simo_credit_status(email)})
    if plan not in {"pro", "team"}:
        return jsonify({"ok": False, "error": "Auto-Reload is available on paid Simo plans."}), 403
    data = request.get_json(silent=True) or {}
    enabled = bool(data.get("enabled"))
    pack = str(data.get("pack") or "100").strip()
    if pack not in {"25", "100", "250"}:
        return jsonify({"ok": False, "error": "Choose a valid credit pack."}), 400
    threshold = min(250, max(0, int(data.get("threshold") or 20)))
    cap = min(100000, max(0, int(data.get("monthly_cap_cents") or 5000)))
    conn = get_db()
    conn.execute(
        """
        UPDATE users SET auto_reload_enabled = ?, auto_reload_pack = ?,
            auto_reload_threshold = ?, auto_reload_monthly_cap_cents = ?, updated_at = ?
        WHERE lower(email) = lower(?)
        """,
        (1 if enabled else 0, pack, threshold, cap, utcnow().isoformat(), email),
    )
    conn.commit(); conn.close()
    return jsonify({"ok": True, "credits": _simo_credit_status(email)})


def _simo_plan_price_spec(plan: str, billing: str):
    plan = str(plan or "pro").strip().lower()
    billing = str(billing or "monthly").strip().lower()
    key = f"{'team' if plan == 'team' else 'pro'}_{'annual' if billing in {'annual','yearly','year'} else 'monthly'}"
    return key, SIMO_PLAN_PRICES.get(key) or SIMO_PLAN_PRICES["pro_monthly"]


def api_create_checkout_session_profit_shield():
    if not STRIPE_SECRET_KEY:
        return jsonify({"ok": False, "error": "Stripe is not configured."}), 500
    data = request.get_json(silent=True) or {}
    plan_key, spec = _simo_plan_price_spec(data.get("plan"), data.get("billing"))
    price_id = str(spec.get("price_id") or "").strip()
    if not price_id:
        return jsonify({"ok": False, "error": f"Missing Stripe price for {plan_key}."}), 500
    email = str(current_user_email() or data.get("email") or "").strip().lower()
    google_sub = str(session.get("google_sub") or "").strip()
    if not email:
        return jsonify({"ok": False, "error": "You must be logged in before choosing a paid Simo plan."}), 401
    upsert_user(email=email, name=current_user_name(), google_sub=google_sub)
    synced = sync_user_pro_from_stripe(email)
    if synced and int(_simo_db_row_value(synced, "pro", 0) or 0) == 1:
        current = _simo_account_plan(email)
        if current == spec["plan"]:
            return jsonify({"ok": True, "already_pro": True, "pro": True, "plan": current, "email": email})
        return jsonify({"ok": False, "error": "Plan changes for an active subscription should be made through billing management before starting another subscription."}), 409

    user_row = get_user_by_email(email)
    success_url = (f"{BASE_URL}/?checkout=success" if BASE_URL else url_for("home", _external=True) + "?checkout=success")
    cancel_url = (f"{BASE_URL}/?checkout=cancel" if BASE_URL else url_for("home", _external=True) + "?checkout=cancel")
    checkout_kwargs = {
        "mode": "subscription",
        "line_items": [{"price": price_id, "quantity": 1}],
        "success_url": success_url,
        "cancel_url": cancel_url,
        "client_reference_id": email,
        "metadata": {"user_email": email, "google_sub": google_sub, "simo_plan": spec["plan"], "simo_billing": spec["billing"]},
        "subscription_data": {"metadata": {"user_email": email, "google_sub": google_sub, "simo_plan": spec["plan"], "simo_billing": spec["billing"]}},
    }
    existing_customer_id = str(_simo_db_row_value(user_row, "stripe_customer_id", "") or "").strip() if user_row else ""
    if existing_customer_id:
        try:
            stripe.Customer.retrieve(existing_customer_id)
            checkout_kwargs["customer"] = existing_customer_id
        except Exception:
            checkout_kwargs["customer_email"] = email
    else:
        checkout_kwargs["customer_email"] = email
    try:
        checkout = stripe.checkout.Session.create(**checkout_kwargs)
        # Pending plan is safe: access is still controlled by pro=1/active Stripe.
        _simo_set_user_plan(email, spec["plan"])
        return jsonify({"ok": True, "url": checkout.url, "id": checkout.id, "plan": spec["plan"], "billing": spec["billing"], "display_price": spec["display"]})
    except Exception as exc:
        return jsonify({"ok": False, "error": f"Checkout failed: {str(exc)}"}), 500


_simo_seal_endpoint("api_create_checkout_session", api_create_checkout_session_profit_shield)


